window.__LEX={"G2500":"<h1>Ioses</h1>\n<p>Strong n° 2500 <i>Prononciation [ee-o-sace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Joseph (Joses) = « élevé », « il ajoutera »\n<ol>\n<li>un des ancêtres de Christ (<a class=\"ref\" data-r=\"LUK3.30\">Luc 3.30</a>)</li>\n<li>Joses, le frère de Jésus (<a class=\"ref\" data-r=\"MRK6.3\">Marc 6.3</a>)</li>\n<li>Joseph, le fils de Marie, la sœur de la mère de Jésus (<a class=\"ref\" data-r=\"MAT27.56\">Matthieu 27.56</a>)</li>\n<li>Joseph, un Lévite (<a class=\"ref\" data-r=\"ACT4.36\">Actes 4.36</a>)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">'Ιωσης - Ἰωσῆς</font>\n<br><br>définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (3)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2501":"<h1>Ioseph</h1>\n<p>Strong n° 2501 <i>Prononciation [ee-o-safe']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Joseph = « il ajoutera »\n<ol>\n<li>le patriarche, onzième fils de Jacob</li>\n<li>le fils de Jonam, un des ancêtres de Christ (<a class=\"ref\" data-r=\"LUK3.30\">Luc 3.30</a>)</li>\n<li>Josech, fils de Joda, un autre ancêtre de Jésus (<a class=\"ref\" data-r=\"LUK3.26\">Luc 3.26</a>)</li>\n<li>le fils de Mattathias, un autre ancêtre de Christ (<a class=\"ref\" data-r=\"LUK3.24\">Luc 3.24</a>)</li>\n<li>l'époux de Marie, la mère de Jésus</li>\n<li>un demi-frère de Jésus (<a class=\"ref\" data-r=\"MAT13.55\">Matthieu 13.55</a>)</li>\n<li>Joseph d'Arimathée, un membre du Sanhédrin, qui défendit Jésus (<a class=\"ref\" data-r=\"MAT27.57,59\">Matthieu 27.57, 59</a> ; <a class=\"ref\" data-r=\"MRK15.43,45\">Marc 15.43, 45</a>)</li>\n<li>Joseph surnommé Barnabas (<a class=\"ref\" data-r=\"ACT4.36\">Actes 4.36</a>)</li>\n<li>Joseph appelé Barsabas (Barsabbas) et surnommé Justus (<a class=\"ref\" data-r=\"ACT1.23\">Actes 1.23</a>)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">'Ιωσηφ</font> &lt; יוסף - <font face=\"Georgia\">Ἰωσήφ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n33 fois dans 32 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (2)</li>\n<li>Luc (9)</li>\n<li>Jean (4)</li>\n<li>Actes (6)</li>\n<li>Hébreux (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2502":"<h1>Iosias</h1>\n<p>Strong n° 2502 <i>Prononciation [ee-o-see'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Josias (Angl. Josiah) = « celui que l'Eternel guérit »\n<ol><li>roi de Juda, qui restaura parmi les Juifs le culte du vrai Dieu, et fut tué à la bataille vers 611 av. J.C., après un règne de trente et un ans</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">'Ιωσιας</font> &lt; יאשיהו - <font face=\"Georgia\">Ἰωσίας</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT).\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G2503":"<h1>iota</h1>\n<p>Strong n° 2503 <i>Prononciation [ee-o'-tah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la lettre hébr. yôd`, y, la plus petite de toutes\n<ol type=\"a\">\n<li>ce qui paraît de peu d'importance</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἰῶτα (τὸ)</b> <i>indécl</i>. la lettre ι, CALLIAS (ATH. <i>453</i> d) ; <i>fig. pour signifier</i> un rien, peu de chose, <i>l’ι étant la plus petite lettre de l’alphabet,</i> NT. <i>Matth. 5, 18</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ιωτα</font> &lt; י - <font face=\"Georgia\">ἰῶτα</font>\n<br><br>origine : Hébreu (la dixième lettre de l'alphabet Hébreu)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G2504":"<h1>kago</h1>\n<p>Strong n° 2504 <i>Prononciation [kag-o']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>et je</li>\n<li>moi aussi, aussi bien, de manière que je</li>\n<li>même moi</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κἀγώ</b>, <i>crase p</i>.  .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καγω - κἀγώ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Conjonction</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n72 fois dans 68 versets de 15 livres bibliques (NT)\n<ul>\n<li>Matthieu (8)</li>\n<li>Marc (1)</li>\n<li>Luc (6)</li>\n<li>Jean (22)</li>\n<li>Actes (5)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (7)</li>\n<li>2 Corinthiens (8)</li>\n<li>Galates (2)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (2)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (2)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G2505":"<h1>katha</h1>\n<p>Strong n° 2505 <i>Prononciation [kath-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>selon ce que, juste comme</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθά</b>, <i>adv. pour</i> καθ' ἅ, de même que, comme, POL. <i>3, 107, 10 ;</i> SPT. <i>Gen. 7, 9</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Forme usuelle dans les inscr. att., v. Meisterh. p. 215, 50</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθα - καθά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Conjonction</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G2506":"<h1>kathairesis</h1>\n<p>Strong n° 2506 <i>Prononciation [kath-ah'-ee-res-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un renversement, une destruction, une démolition, une ruine</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθαίρεσις, εως (ἡ)</b> <span>[ᾰ]</span> renversement, <i>d’où :</i><br><b>      1</b> destruction (d’une ville, <i>etc</i>.) THC. <i>5, 42 ;</i> XÉN. <i>Hell. 2, 2, 15 ;</i> ISOCR. <i>153</i> b ; <i>au pl</i>. αἱ καθαιρέσεις, PHIL. BYZ. <i>Bel. 92, 31 Thévenot</i> ruines ; <i>fig. en parl. de la fortune, de la puissance, etc</i>. SPT. <i>1Macc. 3, 43 ;</i> NT. <i>2Cor. 10, 8 ; particul</i>. action de détrôner, HDN <i>2, 4, 9 ;</i><br><b>      2</b> meurtre, PLUT. <i>Ant. 82 ;</i><br><b>      3</b> diminution, réduction, PLAT. <i>Tim. 58</i> e ; ARSTT. <i>Phys. 3, 6, 9 ; d’où</i> exténuation, amaigrissement, HPC. <i>1174</i> g ; ARSTT. <i>G.A. 2, 4, 11</i>.<br><span><b>Étym</b>. καθαιρέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθαιρεσις - καθαίρεσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (3)</li>\n</ul>\n</td></tr>\n</table>","G2507":"<h1>kathaireo</h1>\n<p>Strong n° 2507 <i>Prononciation [kath-ahee-reh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>descendre\n<ol type=\"a\">\n<li>sans la notion de violence : détacher un crucifié de la croix</li>\n<li>avec l'usage de la force : renverser, jeter à terre</li>\n</ol>\n</li>\n<li>mettre à bas, démolir\n<ol type=\"a\">\n<li>les raisonnements subtils des opposants comme on abat une forteresse, c.à.d réfuter, détruire</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθ·αιρέω</b> <span>[ᾰ]</span> <span>(<i>f</i>. καθαιρήσω, <i>postér</i>. καθελῶ, <i>ao.2</i> καθεῖλον)</span><br><b>   I</b> faire descendre, baisser, abaisser : τὴν σελήνην, AR. <i>Nub. 750 ;</i> PLAT. <i>Gorg. 513</i> a, faire descendre la lune, <i>en parl. de magiciens ;</i> ἱστία, OD. <i>9, 149,</i> caler des voiles ; ἀπὸ πασσαλόφι ζυγόν, IL. <i>24, 268,</i> décrocher un joug du clou auquel il est suspendu ; ἄχθος, AR. <i>Ran. 10,</i> débarrasser d’un fardeau ; ὅσσε, IL. <i>11, 453 ;</i> ὀφθαλμούς, OD. <i>24, 296,</i> abaisser les paupières, fermer les yeux (d’un mort) ;<br><b>   II</b> <i>particul. avec idée d’efforts pénibles, de violence ou d’hostilité :</i><br><b>      1</b> abattre, renverser : ἀθλητήν, PLAT. <i>Leg. 201</i> b, renverser un athlète, le vaincre ; τείχη, PLAT. <i>Menex. 244</i> c, des murailles ;<br><b>      2</b> abattre, tuer : τινα, OD. <i>2, 100 ; 3, 238, etc. ;</i> ESCHL. <i>Ag. 398 ;</i> SOPH. <i>Aj. 517,</i> faire périr qqn ; <i>fig</i>. Κῦρον καὶ τὴν Περσέων δύναμιν, HDT. <i>1, 71,</i> détrôner Cyrus et détruire la puissance des Perses ; τὸ λῃστικὸν ἐκ τῆς θαλάσσης, THC. <i>1, 4,</i> purger la mer des pirates ; ὕϐριν τινός, HDT. <i>9, 27,</i> abattre l’insolence de qqn ;<br><b>      3</b> <i>en parl. de décisions légales, de décrets, de sentences :</i> καθαιροῦσα ψῆφος, LYS. <i>133, 12,</i> arrêt de condamnation (<i>propr</i>. vote qui jette à bas) ; κ. ψήφισμα, THC. <i>1, 140 ;</i> PLUT. <i>Per. 29,</i> abroger un décret ; <i>avec un inf. :</i> ἐμὲ πάλος καθαιρεῖ λαϐεῖν, SOPH. <i>Ant. 275,</i> le sort me condamne à prendre ; <i>d’où abs</i>. décider par un vote : τι, DH. <i>7, 36, 39,</i> qqe ch. ;<br><b>      4</b> amoindrir, ARSTT. <i>Rhet. 1, 15, 20, etc. ;</i> τὸ σῶμα, PLUT. <i>Ant. 53,</i> exténuer le corps, l’épuiser ;<br><b>      5</b> s’emparer de, mettre la main sur : τινά, HDT. <i>6, 29,</i> s’emparer de qqn ; ναῦν, HDT. <i>6, 41,</i> s’emparer d’un vaisseau ; χρήματα, HDT. <i>5, 36,</i> enlever de l’argent ; ἀγῶνα, PLUT. <i>Pomp. 8,</i> emporter le prix d’une lutte ; κ. τῶν ὤτων, THCR. <i>5, 132,</i> saisir par les oreilles ; <i>fig</i>. μεγάλα πρήγματα, HDT. <i>7, 50,</i> accomplir de grandes choses (<i>propr</i>. abattre de grandes besognes) ;<br><b><i>Moy</i>. καθαιρέομαι-οῦμαι</b> <span>(<i>f</i>. -ήσομαι, <i>ao.2</i> καθειλόμην)</span><br><b>      1</b> abaisser pour soi : τὰ τόξα, HDT. <i>3, 78,</i> décrocher son arc ; τοὺς ἱστούς, POL. <i>1, 61, 1,</i> abaisser les mâts ;<br><b>      2</b> arranger (une querelle) EUR. <i>Suppl. 749</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut</i>. καθελῶ, A. PL. <i>334 ; ao.2, 3 pl. alex</i>. καθείλοσαν, SPT. <i>Esaï. 22. Prés. ion</i>. καταιρέω, HDT. <i>1, 71, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθαιρεω - καθαιρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 4 livres bibliques (NT)\n<ul>\n<li>Marc (2)</li>\n<li>Luc (3)</li>\n<li>Actes (3)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2508":"<h1>kathairo</h1>\n<p>Strong n° 2508 <i>Prononciation [kath-ah'-ee-ro]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>nettoyer, enlever les impuretés\n<ol type=\"a\">\n<li>émonder les arbres et vignes des pousses inutiles</li>\n<li>métaph. supprimer la culpabilité, expier</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθαίρω</b> <span>[ᾰ]</span> <span>(<i>f</i>. καθαρῶ <span>[ᾰᾰ]</span>, <i>ao</i>. ἐκάθηρα <span>[κᾰ]</span> ; <i>pass. ao</i>. ἐκαθάρθην <span>[κᾰ]</span>, <i>pf</i>. κεκάθαρμαι <span>[κᾰ]</span>)</span> purifier, <i>d’où :</i><br><b>   I</b> <i>en gén. :</i> nettoyer, laver, purifier, <i>avec l’acc. de l’objet purifié ;</i> κρητῆρας, OD. <i>20, 152 ;</i> τραπέζας, OD. <i>22, 439,</i> nettoyer des coupes, des tables ; χρυσόν, PLAT. <i>Pol. 303</i> d, purifier de l’or ; ἵππον αὐχμηρᾶς τριχός, SOPH. <i>fr. 422,</i> nettoyer la crinière <i>ou</i> le poil sali d’un cheval ; γῆν λῃστηρίων, PLUT. <i>Mar. 6, ou simpl</i>. γαῖαν, SOPH. <i>Tr. 1061,</i> purger la terre (de monstres, de brigands) ; <i>avec l’acc. de la souillure :</i> λύματα πάντα, IL. <i>14, 171 ;</i> ῥύπα πάντα, OD. <i>6, 93,</i> enlever toutes les souillures ; <i>fig</i>. τὰ λῃστικά, DC. <i>37, 52,</i> supprimer le brigandage ; <i>avec double acc. (de l’objet purifié et de la souillure</i>) : αἷμα κ. τινά, IL. <i>16, 667,</i> laver le sang de qqn ;<br><b>   II</b> <i>abs. :</i><br><b>      1</b> émonder un arbre, NT. <i>Joh. 15, 2 ;</i><br><b>      2</b> <i>c</i>. μαστιγόω, fouetter qqn (<i>cf. les locut</i>. laver la tête, nettoyer qqn) THCR. <i>5, 119 ;</i><br><b>   III</b> <i>au sens relig</i>. purifier, <i>avec l’acc. de l’objet purifié :</i> δέπας θεείῳ, IL. <i>16, 228,</i> une coupe par le soufre ; νῆσον, HDT. <i>1, 64,</i> purifier une île ; τινά, HDT. <i>1, 35 ;</i> τινὰ φόνου, HDT. <i>1, 44,</i> purifier qqn d’un meurtre ; <i>avec l’acc. de la souillure :</i> φόνον, ESCHL. <i>Ch. 74,</i> laver un meurtre ; <i>au pass</i>. être purifié, se purifier : φόνον, HDT. <i>1, 43,</i> d’un meurtre ;<br><b><i>Moy.</i></b> :<br><b>   I <i>intr</i>.<br>      1</b> <i>t. de méd</i>. se purger, PLUT. <i>M. 128</i> b ;<br><b>      2</b> <i>au sens relig</i>. se purifier, HDT. <i>4, 73 ;</i> PLAT. <i>Phæd. 114</i> c, <i>etc. ;</i><br><b>   II <i>tr.</i></b> nettoyer pour soi ; <i>fig</i>. γῆρας, ESCHL. <i>fr. 42,</i> écarter de soi la vieillesse.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. att</i>. ἐκάθηρα (<i>v. Meisterh. p. 146, 8) ; dor</i>. ἐκάθαρα, THCR. <i>5, 119. Ion</i>. καταίρω, HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. καθαρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθαιρω - καθαίρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2509":"<h1>kathaper</h1>\n<p>Strong n° 2509 <i>Prononciation [kath-ap'-er]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>selon ce que, juste comme, aussi bien</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθ·άπερ</b> <span>[ᾰᾰ]</span> <i>adv</i>., de même que, comme, AR. <i>Eccl. 61, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Forme usuelle dans les inscr. att</i>. CIA. <i>1, 31 a, 10 (444/440 av. J.C.) etc. ; une fois avec l’aspiration intérieure</i> καθἅπερ, <i>v. Meisterh. p. 215, 52. Ion</i>. κατάπερ, HDT. <i>1, 131, 144, 145, etc</i>.<br><span><b>Étym</b>. κ. ἅπερ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθαπερ - καθάπερ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 13 versets de 5 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (4)</li>\n<li>1 Thessaloniciens (4)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G2510":"<h1>kathapto</h1>\n<p>Strong n° 2510 <i>Prononciation [kath-ap'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ajuster ou s'attacher à, lié sur</li>\n<li>mettre la main sur, s'attacher à (d'une façon hostile)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθ·άπτω</b> <span>(<i>f</i>. -άψω, <i>ao</i>. -ῆψα)</span> <span>[κᾰ]</span><br><b>   I <i>tr</i>.<br>      1</b> attacher de haut en bas, <i>d’où</i> suspendre : ὠμοῖς ἀμφίϐληστρον, SOPH. <i>Tr. 1051,</i> jeter un manteau autour de ses épaules ; τι ἀμφί τινι, EUR. <i>Ion 1006,</i> envelopper qqn de qqe ch. ; <i>au pass</i>. βρόχῳ καθημμένη, SOPH. <i>Ant. 1222,</i> pendue au moyen d’un lacet ;<br><b>      2</b> <i>p. ext</i>. attacher à : τι ἐπί τι, XÉN. <i>Cyn. 6, 9 ; ou</i> εἴς τι, POL. <i>8, 8, 3, ou</i> τι ἔκ τινος, PLUT. <i>M. 647</i> e, une chose à une autre ;<br><b>   II <i>intr</i>.<br>      1</b> s’attacher à, <i>gén</i>. NT. <i>Ap. 28, 3 ;</i> ARR. <i>Epict. 3, 20, 10 ;</i><br><b>      2</b> se rattacher à, s’étendre jusqu’à, <i>avec</i> εἰς <i>ou</i> πρός <i>et l’acc</i>. ARSTT. <i>H.A. 3, 4, 9 et 12 ;</i><br><b><i>Moy</i>. καθάπτομαι</b> <span>(<i>f</i>. -άψομαι)</span><br><b>   I <i>tr.</i></b> attacher pour soi <i>ou</i> sur soi : κισσὸν ἐπὶ κρατί, THCR. <i>Ep. 3, 4,</i> se couronner la tête de lierre ; σῶμα σκευῇ, EUR. <i>Rhes. 202,</i> s’envelopper le corps d’un vêtement ;<br><b>   II <i>intr</i>.<br>      1</b> s’attacher à, <i>d’où</i> tenir fortement : βρέφεος, THCR. <i>17, 65,</i> un enfant ; τυραννίδος, SOL. <i>30,</i> s’emparer de la royauté ;<br><b>      2</b> <i>particul</i>. s’adresser à : τινα ἐπέεσσι, adresser à qqn des paroles bienveillantes, IL. <i>1, 582 ;</i> OD. <i>10, 70 ; 24, 293, ou</i> blessantes, OD. <i>18, 415 ; 20, 323 ;</i> HÉS. <i>O. 330 (propr</i>. s’attacher <i>ou</i> s’attaquer à qqn par des paroles) ; φίλον ἦτορ, OD. <i>20, 22,</i> parler à son propre cœur, <i>càd</i>. se parler à soi-même ; <i>postér. en mauv. part,</i> s’attaquer à, <i>gén</i>. THC. <i>6, 16 ;</i> XÉN. <i>Hell. 1, 7, 4 ;</i> PLAT. <i>Crit. 52</i> a ; <i>abs</i>. THC. <i>6, 82 ;</i><br><b>      3</b> se rattacher à qqn (comme à un soutien), <i>d’où</i> invoquer, attester, prendre à témoin : τινος, HDT. <i>6, 68 ; 8, 65,</i> qqn ;<br><b>      4</b> s’attacher à, faire attention à, être sensible à : ψόφου, HPC. <i>68</i> d, à un reproche.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. κατάπτομαι, HDT. <i>l. c</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθαπτω - καθάπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2511":"<h1>katharizo</h1>\n<p>Strong n° 2511 <i>Prononciation [kath-ar-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre propre, nettoyer\n<ol type=\"a\">\n<li>enlever physiquement taches et saleté\n<ol>\n<li>ustensiles, nourriture</li>\n<li>un lépreux, purifier par des remèdes</li>\n<li>rénover par nettoyage</li>\n</ol>\n</li>\n<li>dans un sens moral\n<ol>\n<li>libérer de la souillure du péché et des fautes</li>\n<li>purifier de la méchanceté</li>\n<li>libérer de la culpabilité du péché, purifier</li>\n<li>consacrer par purification</li>\n<li>consacrer, dédier</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>déclaré pur dans un sens lévitique</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθαρίζω</b> <span>[ᾰᾰ]</span> purifier, SPT. <i>Sir. 38, 10 ;</i> NT. <i>Matth. 23, 5, etc</i>.<br><span><b>Étym</b>. καθαρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθαριζω - καθαρίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n30 fois dans 29 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (4)</li>\n<li>Luc (7)</li>\n<li>Actes (3)</li>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (3)</li>\n<li>Jacques (1)</li>\n<li>1 Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G2512":"<h1>katharismos</h1>\n<p>Strong n° 2512 <i>Prononciation [kath-ar-is-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un nettoyage, une purification, purge rituelle ou lavage\n<ol type=\"a\">\n<li>le lavage des Juifs avant et après leurs repas</li>\n<li>la purification lévitique des femmes après un accouchement</li>\n<li>purification de la culpabilité des péchés apportée par le sacrifice expiatoire de Christ</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθαρισμός, οῦ (ὁ)</b> <span>[ᾰᾰ]</span> purification, SPT. <i>Ex. 29, 36 ; Lev. 14, 32 ; Num. 14, 18, etc</i>.<br><span><b>Étym</b>. καθαρίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθαρισμος - καθαρισμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 5 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Jean (2)</li>\n<li>Hébreux (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2513":"<h1>katharos</h1>\n<p>Strong n° 2513 <i>Prononciation [kath-ar-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>propre, pur\n<ol type=\"a\">\n<li>physiquement\n<ol>\n<li>purifié par le feu</li>\n<li>en similitude, comme une vigne éclaircie par élagage et portant plus de fruit</li>\n</ol>\n</li>\n<li>sens lévitique\n<ol>\n<li>pur, dont l'usage n'est pas interdit, qui n'amène pas de l'impureté</li>\n</ol>\n</li>\n<li>moralement\n<ol>\n<li>libéré de désirs corrompus, du péché, de la culpabilité</li>\n<li>libre de tout mélange à ce qui est faux, sincère, véritable</li>\n<li>sans reproche, innocent</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθαρός, ά, όν</b> <span>[ᾰᾰ]</span> pur, <i>càd. :</i><br><b>      1</b> sans tache, sans souillure, propre : εἵματα, OD. <i>6, 61, etc</i>. vêtements sans tache ; <i>au sens mor</i>. pur de toute souillure, <i>en parl. de pers. :</i> καθ. κατὰ τὸ σῶμα καὶ κατὰ τὴν ψυχήν, PLAT. <i>Crat. 405</i> b, pur de corps et d’âme ; <i>particul. en parl. de suppliants,</i> ESCHL. <i>Eum. 474,</i> SOPH. <i>O.C. 548, etc. ; en parl. de choses (autel, demeure, etc</i>.) ESCHL. <i>Suppl. 655 ;</i> EUR. <i>I.T. 1163, etc. ;</i> καθ. τινος (ἀδικίας, φόνου, <i>etc</i>.) ATT. <i>ou</i> ἀπό τινος, DC. <i>37, 24,</i> pur de souillure (injustice, meurtre, <i>etc</i>.) ; καθαραὶ ἡμέραι, PLAT. <i>Leg. 800</i> d, jours purs (<i>lat</i>. dies fasti) <i>p. opp. à</i> ἀποφράδες ;<br><b>      2</b> pur de tout mélange : ἄρτος, HDT. <i>2, 40,</i> pain de bonne qualité, pur ; χρυσός, HDT. <i>2, 166,</i> or pur ; <i>particul</i>. limpide, <i>en parl. de l’eau,</i> HDT. <i>4, 53 ; p. opp. à</i> θολερός, EUR. <i>Hipp. 210 ; à</i> βορϐορώδης, PLAT. <i>Phæd. 111</i> e ; <i>joint à</i> διαφανής, PLAT. <i>Phædr. 229</i> b ; <i>en parl. de son,</i> net, pur, ARSTT. <i>Aud. 25 ; en parl. du langage, du style,</i> DH. <i>Lys. 2 ; en parl. de prosodie,</i> DRAC. <i>22, 25, etc</i>. voyelle pure, <i>càd</i>. précédée d’une autre ; <i>en parl. de la naissance :</i> καθ. σπέρμα θεοῦ, PD. <i>P. 6, 14,</i> pur rejeton d’un dieu ; τῶν Ἀθηναίων ὅπερ ἐστράτευε καθαρὸν ἐξῆλθε, THC. <i>5, 8,</i> tous ceux des Athéniens qui faisaient partie de l’expédition étaient purement des citoyens, <i>càd</i>. des citoyens sans mélange d’étrangers ; <i>en parl. de l’intelligence :</i> κ. νοῦς, XÉN. <i>Cyr. 8, 7, 30,</i> esprit net ; δοῦλος, ANTIPH. (<i>Bkk. 105, 5</i>) pur esclave, véritable esclave ; κ. Τίμων, AR. <i>Av. 1549,</i> un Timon pur et simple ; κ. ζημία, ALCIPHR. <i>3, 21,</i> pur fléau ;<br><b>      3</b> pur de toute fraude, DÉM. <i>303, 22 ;</i><br><b>      4</b> exempt d’infirmité : τὸ καθαρὸν τοῦ στρατοῦ, HDT. <i>1, 211 ; 4, 135,</i> la partie valide de l’armée ;<br><b>      5</b> <i>p. suite,</i> nettoyé, débarrassé de tout obstacle, <i>d’où</i> vide : ἐν καθαρῷ, IL. <i>8, 491, etc</i>. dans un espace libre : ἐν καθαρῷ βῆναι, SOPH. <i>O.C. 1575,</i> s’avancer librement ; ἐν καθαρῷ οἰκεῖν, PLAT. <i>Rsp. 520</i> d, habiter dans la région de la pure lumière ; <i>cf</i>. HDT. <i>1, 202</i>.<br><span>•<i> Cp</i>. -ώτερος, PLAT. <i>Phæd. 111</i> e ; <i>sup</i>. -ώτατος, DC. <i>41, 55 ; 43, 25</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθαρος - καθαρός</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – dénote la liberté envers les mensonges et la fausseté\n<br><br> – dénote la liberté envers les souillures, de la chair et de la parole</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n27 fois dans 23 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (1)</li>\n<li>Jean (4)</li>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>1 Timothée (2)</li>\n<li>2 Timothée (2)</li>\n<li>Tite (3)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n<li>Apocalypse (6)</li>\n</ul>\n</td></tr>\n</table>","G2514":"<h1>katharotes</h1>\n<p>Strong n° 2514 <i>Prononciation [kath-ar-ot'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>propreté, pureté\n<ol type=\"a\">\n<li>dans un sens Lévitique</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθαρότης, ητος (ἡ)</b> <span>[ᾰᾰ]</span> pureté, <i>d’où :</i><br><b>      1</b> <i>au propre,</i> netteté, limpidité, HPC. <i>152</i> g ;<br><b>      2</b> <i>fig</i>. pureté morale, PLAT. <i>Phæd. 111</i> b, <i>etc. ; particul</i>. probité, désintéressement, POL. <i>32, 11, 9</i>.<br><span><b>Étym</b>. καθαρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθαροτης - καθαρότης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2515":"<h1>kathedra</h1>\n<p>Strong n° 2515 <i>Prononciation [kath-ed'-rah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une chaise, un siège, une chaire\n<ol type=\"a\">\n<li>pour le siège élevé occupé par les hommes au rang éminent, ou ayant grande influence, tels les enseignants ou les juges</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθ·έδρα, ας (ἡ)</b> <span>[κᾰ]</span><br><b>   I</b> ce qui sert à s’asseoir, <i>d’où :</i><br><b>      1</b> siège, banc, HDN <i>2, 3 ;</i> PLUT. <i>M. 714</i> e ; <i>particul</i>. banc de rameurs, POL. <i>1, 21, 2 ;</i><br><b>      2</b> fondement, <i>t. de physiol</i>. HPC. <i>557, 48 ;</i><br><b>      3</b> base d’une colonne, STR. <i>816 ;</i><br><b>      4</b> gîte d’un animal, XÉN. <i>Cyn. 4, 4 ;</i><br><b>   II</b> action d’être <i>ou</i> de demeurer assis, <i>d’où :</i><br><b>      1</b> état <i>ou</i> posture d’une personne assise, ARSTT. <i>Categ. 7, 3, etc. ;</i> TH. <i>fr. 7, 5 ;</i> PLUT. <i>M. 45</i> c ;<br><b>      2</b> <i>p. suite,</i> immobilité, inertie, THC. <i>2, 18 ;</i> PLUT. <i>Cam. 28</i>.<br><span><b>Étym</b>. κατά, ἕδρα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθεδρα - καθέδρα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G2516":"<h1>kathezomai</h1>\n<p>Strong n° 2516 <i>Prononciation [kath-ed'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>s'asseoir, être assis, faire asseoir, siéger</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθ·έζομαι</b> <span>(<i>impf</i>. ἐκαθεζόμην, <i>fut</i>. καθεδοῦμαι, <i>ao</i>. ἐκαθέσθην)</span> <span>[ᾰ]</span><br><b>   I</b> s’asseoir, OD. <i>1, 372 ;</i> HÉS. <i>O. 257 ;</i> ἐπί τινι, OD. <i>9, 417, etc. ;</i> EUR. <i>Ph. 75 ;</i> ἔν τινι, SOPH. <i>Tr. 918 ;</i> ἔς τι, ESCHL. <i>Pr. 229,</i> sur qqe ch. ;<br><b>   II</b> être <i>ou</i> demeurer assis :<br><b>      1</b> <i>en parl. de suppliants,</i> THC. <i>3, 70 ;</i> EUR. <i>Her. 33 ;</i> DÉM. <i>262, 18, etc. ;</i><br><b>      2</b> <i>avec idée d’immobilité, d’inertie,</i> OD. <i>6, 295 ; 10, 378</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. dor</i>. καθέσδομαι, MOSCH. <i>3, 46. Impf. poét</i>. καθεζόμην, IL. <i>1, 536, etc. ;</i> ESCHL. <i>Pr. 229 ;</i> AR. <i>Lys. 1139, etc. Fut. réc</i>. καθεδῶ, SYN. <i>Prov. 2, 123 ;</i> καθεδήσομαι, DL. <i>2, 72, et</i> καθεσθήσομαι, SPT. <i>Lev. 12, 5. L’ao</i>. ἐκαθέσθην (PAUS. <i>3, 22 ;</i> LYS. <i>2, 38 ;</i> CHARIT. <i>3, 2 ;</i> ANTH. <i>11, 392) blâmé par</i> LUC. <i>Sol. 11</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθεζομαι - καθέζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Jean (3)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2517":"<h1>kathexes</h1>\n<p>Strong n° 2517 <i>Prononciation [kath-ex-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>l'un après l'autre, successivement, dans l'ordre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθ·εξῆς</b>, <i>adv</i>., par rang, par ordre, de suite, <i>d’où</i> ensuite, NT. <i>1, 3 ; 8, 1, etc. ;</i> PLUT. <i>M. 615</i> b.<br><span><b>Étym</b>. κ. ἑξῆς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθεξης - καθεξῆς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G2518":"<h1>katheudo</h1>\n<p>Strong n° 2518 <i>Prononciation [kath-yoo'-do]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tomber de sommeil, s'endormir</li>\n<li>dormir\n<ol type=\"a\">\n<li>dormir normalement</li>\n<li>par euphémisme : être mort</li>\n<li>métaph.\n<ol>\n<li>céder à la paresse et au péché</li>\n<li>être indifférent à son salut</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθ·εύδω</b> <span>(<i>impf. att</i>. καθηῦδον, <i>ou</i> ἐκάθευδον, <i>f</i>. καθευδήσω)</span> se coucher <i>ou</i> être couché pour dormir, <i>d’où</i> dormir, <i>en parl. de pers</i>. IL. <i>1, 611 ;</i> OD. <i>1, 4, etc. ;</i> HDT. <i>2, 95 ;</i> ESCHL. <i>Ch. 881 ;</i> PLAT. <i>Phædr. 251</i> e, <i>etc. ;</i> μετά τινος, PLAT. <i>Conv. 219</i> d, avec qqn ; <i>p. euph. en parl. des morts,</i> NT. <i>1Thess. 5, 10 ; en parl. d’oiseaux,</i> AR. <i>Nub. 1431 ; fig. en parl. de pers</i>. être endormi, inactif, inerte, XÉN. <i>An. 1, 3, 11 ; Hell. 5, 1, 20 ;</i> PLUT. <i>Pomp. 15 ;</i> DÉM. <i>438, 15, etc. ;</i> être endormi, dormir, <i>en parl. d’espérances, de ruines, etc</i>. EUR. <i>Ph. 634 ;</i> PLAT. <i>Leg. 771</i> d ; τοὺς νόμους ἐᾶν καθ. PLUT. <i>Ages. 30,</i> laisser dormir les lois.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. épq. et poét</i>. καθεῦδον, IL. <i>1, 611 ;</i> AR. <i>Av. 495. Ion</i>. κατεύδω, HDT. <i>l. c</i>.<br><span><b>Étym</b>. κατά, εὕδω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθευδω - καθεύδω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n22 fois dans 20 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (8)</li>\n<li>Luc (2)</li>\n<li>Ephésiens (1)</li>\n<li>1 Thessaloniciens (4)</li>\n</ul>\n</td></tr>\n</table>","G2519":"<h1>kathegetes</h1>\n<p>Strong n° 2519 <i>Prononciation [kath-ayg-ay-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un guide</li>\n<li>un maître, un enseignant, un docteur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθηγητής, οῦ (ὁ)</b> <span>[ᾰ]</span><br><b>      1</b> guide, conducteur, NUMÉN. (ATH. <i>313</i> d) ;<br><b>      2</b> <i>fig</i>. précepteur, maître, DH. <i>Thuc. 3 ;</i> PLUT. <i>M. 70</i> e.<br><span><b>Étym</b>. καθηγέομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθηγητης - καθηγητής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (3)</li>\n</ul>\n</td></tr>\n</table>","G2520":"<h1>katheko</h1>\n<p>Strong n° 2520 <i>Prononciation [kath-ay'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>descendre</li>\n<li>aller à, atteindre\n<ol type=\"a\">\n<li>en cours</li>\n<li>ce qui est convenable</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθ·ήκω</b> <span>(<i>impf</i>. καθῆκον, <i>f</i>. καθήξω)</span> <span>[ᾰ]</span><br><b>   I</b> descendre dans la lice, dans l’arène (pour le combat) ESCHL. <i>Ch. 455 ;</i><br><b>   II</b> descendre jusqu’à, s’abaisser jusqu’à, <i>d’où</i> aboutir à :<br><b>      1</b> <i>en parl. du lieu :</i> εἰς θάλασσαν, HDT. <i>7, 22 et 130 ;</i> XÉN. <i>An. 1, 4, 4 ; 6, 2, 3 ;</i> ἐπὶ θάλασσαν, HDT. <i>2, 32 ; 5, 49 ;</i> THC. <i>2, 27 ;</i> ἐπὶ ποταμόν, XÉN. <i>An. 4, 3, 11 ;</i> πρὸς κόλπον, THC. <i>3, 96,</i> descendre, <i>càd</i>. s’étendre jusqu’à la mer, jusqu’à un fleuve, un golfe, <i>en parl. de pays touchant à la mer, à un cours d’eau, ou à un autre pays situé plus bas ; fig. :</i> καθῆκεν εἰς ἡμᾶς ὁ λόγος, ESCHN. <i>31, 27,</i> le discours descendit jusqu’à nous, <i>càd</i>. notre tour de parler arriva enfin ;<br><b>      2</b> <i>en parl. du temps :</i> εἰς ἡμέραν τινά, PLUT. <i>Fab. 18,</i> aboutir à un certain jour, <i>càd</i>. tomber un certain jour ; <i>abs</i>. οἱ καθήκοντες χρόνοι, ARSTT. <i>H.A. 8, 2 ;</i> POL. <i>5, 30, 7 ;</i> ὁ καθήκων χρόνος, SOPH. <i>O.R. 75 ; cf</i>. DÉM. <i>50, 6 ;</i> ESCHN. <i>71, 29,</i> le temps marqué, l’époque fixée ; αἱ καθήκουσαι ἡμέραι, DÉM. <i>1372, 8,</i> les jours marqués ; τὰ κατήκοντα πρήγματα, HDT. <i>8, 102, ou</i> τὰ κατήκοντα, HDT. <i>1, 97 ; 5, 49,</i> l’état actuel des affaires ;<br><b>      3</b> <i>p. suite,</i> toucher à, concerner, convenir à : ἐσθῆτες καθήκουσαί τινι, POL. <i>3, 78, 3,</i> vêtements qui conviennent à qqn ; καθήκει μοι, il me convient, il m’appartient de, <i>avec l’inf</i>. XÉN. <i>An. 1, 9, 7, ou avec une prop. inf</i>. XÉN. <i>Cyr. 8, 1, 4 ;</i> τὸ καθῆκον, <i>ou</i> τὰ καθήκοντα, XÉN. <i>Cyr. 1, 2, 5,</i> ce qui convient, les obligations, le devoir ; <i>particul. dans le langage des Stoïciens,</i> DL. <i>7, 25 ;</i> CIC. <i>Off. 1, 3</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. κατήκω, HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. κ. ἥκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθηκω - καθήκω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G2521":"<h1>kathemai</h1>\n<p>Strong n° 2521 <i>Prononciation [kath'-ay-mahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire asseoir, s'asseoir, monter un cheval</li>\n<li>être assis, occuper une place\n<ol type=\"a\">\n<li>avoir une demeure fixe, demeurer</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κάθ·ημαι</b> <span>(<i>d’où sbj</i>. καθῶμαι, <i>opt</i>. καθοίμην <i>ou mieux</i> καθῄμην, <i>inf</i>. καθῆσθαι, <i>part</i>. καθήμενος ; <i>impf</i>. ἐκαθήμην, <i>d’ord. sans augm. à la 2<sup>e</sup> et à la 3<sup>e</sup> pers. du sg</i>. καθῆσο, καθῆτο <i>ou</i> καθῆστο, <i>et du plur</i>. καθῆσθε <i>et</i> καθῆντο)</span><br><b>   I</b> être assis, demeurer : ἐπ' ἀκτῆς, OD. <i>5, 82,</i> sur le rivage ; ἐπὶ δίφρου, PLAT. <i>Rsp. 328</i> c ; ἐφ' ἵππων, XÉN. <i>Cyr. 4, 5, 54,</i> sur un char, à cheval ; ἐν θρόνῳ, HDT. <i>2, 149, ou</i> θρόνῳ, EUR. <i>El. 315,</i> sur un siège ; θύρῃσι, OD. <i>17, 530,</i> à la porte ; ἐπὶ πέτρῃ, IL. <i>16, 407,</i> sur un rocher ; <i>ou simpl. avec l’acc</i>. IL. <i>2, 191, etc. ;</i> siéger, <i>en parl. de juges,</i> AR. <i>Nub. 208 ;</i> PLAT. <i>Ap. 35</i> c ; οἱ καθήμενοι, THC. <i>5, 85 ;</i> DÉM. <i>66, 13, etc</i>. les juges, la cour ; <i>en parl. d’une assemblée</i> (βουλή, ἐκκλησία) XÉN. <i>An. 5, 10, 5 ;</i> AND. <i>6, 42 ;</i> DÉM. <i>552, 16 ;</i> οἱ καθήμενοι, HÉGÉSIPPE (ATH. <i>290</i> b) ceux qui sont assis (au théâtre), les spectateurs ;<br><b>   II</b> <i>p. ext</i>. demeurer à la même place, <i>càd. :</i><br><b>      1</b> rester tranquille, IL. <i>11, 76 ;</i> OD. <i>16, 264 ;</i> HDT. <i>1, 45, etc. ; en mauv. part,</i> demeurer immobile, inactif, inerte, HDT. <i>3, 134 ;</i> DÉM. <i>156, 28, etc. ; en parl. d’une armée,</i> THC. <i>4, 124 ;</i><br><b>      2</b> être sédentaire, vivre d’une vie sédentaire, <i>en parl. d’artisans, d’ouvriers, d’hommes engagés dans les affaires ou dans l’étude,</i> HDT. <i>2, 86 ;</i> XÉN. <i>Œc. 4, 2 ;</i> DÉM. <i>1367, 26, etc. ;</i><br><b>      3</b> être fixé, établi : ἐν Δελφοῖσιν, HDT. <i>5, 63,</i> à Delphes ; <i>en parl. de statues,</i> être placé, PLAT. <i>Conv. 215</i> a ;<br><b>      4</b> <i>en parl. de pays,</i> être situé, TH. <i>H.P. 8, 8, 7 ; particul</i>. être bas, EL. <i>V.H. 3, 1 dout</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. 2 sg</i>. κάθησαι, XÉN. <i>Cyr. 3, 1, 6, etc. ; ou</i> κάθῃ, HYPÉR. <i>fr. 136 ;</i> COM. (<i>Com. fr. 4, 676) ; impér</i>. κάθησο, IL. <i>2, 191, etc. ; ou</i> κάθου, AR. (<i>Com. fr. 2, 1190, 62), etc. Impf. 3 sg</i>. καθῆτο, DÉM. <i>18, 169, etc. ou</i> καθῆστο, IL. <i>1, 569. Ion. prés. 3 pl</i>. κατέαται, HDT. <i>2, 86 ; impf. 3 sg</i>. κατῆστο, HDT. <i>1, 46 ; 3, 83 ; 3 pl</i>. ἐκατέατο, HDT. <i>3, 144 ; 8, 73 ou</i> κατέατο, HDT. <i>9, 90 ; épq</i>. καθείατο, IL. <i>11, 76</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθημαι - κάθημαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n89 fois dans 87 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (18)</li>\n<li>Marc (11)</li>\n<li>Luc (12)</li>\n<li>Jean (4)</li>\n<li>Actes (7)</li>\n<li>1 Corinthiens (1)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (2)</li>\n<li>Apocalypse (32)</li>\n</ul>\n</td></tr>\n</table>","G2522":"<h1>kathemerinos</h1>\n<p>Strong n° 2522 <i>Prononciation [kath-ay-mer-ee-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>quotidien, quotidiennement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθ·ημερινός, ή, όν</b> <span>[ᾰ]</span> quotidien, journalier, PLUT. <i>M. 141</i> b ; SPT. <i>Judith 12, 15 ;</i> NT. <i>Ap. 6, 1</i>.<br><span><b>Étym</b>. <i>cf</i>. καθημέριος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθημερισνος - καθημερινός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2523":"<h1>kathizo</h1>\n<p>Strong n° 2523 <i>Prononciation [kath-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire asseoir\n<ol type=\"a\">\n<li>poser, désigner, conférer un royaume à quelqu'un</li>\n</ol>\n</li>\n<li>intransitif\n<ol type=\"a\">\n<li>s'asseoir</li>\n<li>asseoir\n<ol>\n<li>avoir fixé sa demeure</li>\n<li>séjourner, s'établir</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθ·ίζω</b> <span>(<i>f</i>. καθίσω, <i>att</i>. καθιῶ, <i>ao</i>. ἐκάθισα, <i>att</i>. καθῖσα, <i>pf</i>. κεκάθικα)</span> <span>[ᾰ]</span><br><b>   I <i>tr.</i></b> faire asseoir :<br><b>      1</b> <i>au pr. :</i> τινά, IL. <i>3, 68, etc</i>. qqn ; ἐπὶ γούνεσσι, IL. <i>9, 488,</i> sur les genoux ; καθίσαι τινὰ εἰς θρόνον, XÉN. <i>An. 2, 1, 4,</i> faire asseoir qqn sur un trône, faire roi ;<br><b>      2</b> <i>p. suite,</i> faire siéger, convoquer : ἀγοράς, OD. <i>2, 69,</i> tenir des assemblées (<i>p. opp. à</i> λύειν) ; δικαστήριον, AR. <i>Vesp. 305 ;</i> τοὺς νομοθέτας, DÉM. <i>708, 1,</i> réunir en séance un tribunal, les nomothètes, <i>etc. ;</i><br><b>      3</b> établir, poster : στρατόν, EUR. <i>Her. 664 ;</i> THC. <i>4, 90,</i> établir une armée dans une position ; φύλακας, XÉN. <i>Cyr. 2, 2, 14,</i> poser des gardes ; ἐνέδραν, PLUT. <i>Popl. 19,</i> dresser une embuscade ; <i>fig</i>. δικαστήν, PLAT. <i>Leg. 873</i> e, instituer un juge ; τὴν βουλὴν ἐπίσκοπον, PLUT. <i>Sol. 19,</i> établir le sénat comme surveillant ;<br><b>      4</b> mettre dans telle <i>ou</i> telle situation : τινὰ κλαίοντα, PLAT. <i>Ion 535</i> e, <i>ou</i> κλάειν τινά, XÉN. <i>Cyr. 2, 2, 14,</i> faire pleurer qqn, <i>propr</i>. le mettre dans l’état d’un homme qui pleure ;<br><b>   II <i>intr</i>.<br>      1</b> s’asseoir, IL. <i>3, 394 ; avec une prép</i>. ἔν τινι, OD. <i>8, 422 ;</i> ἐπί τι, AR. <i>Nub. 954 ;</i> THC. <i>1, 126 ; ou simpl</i>. τι, EUR. <i>Ion 366,</i> sur qqe ch. ; <i>particul. en parl. de juges, de magistrats,</i> siéger, HDT. <i>1, 97, etc. ;</i> PLAT. <i>Leg. 659</i> b ;<br><b>      2</b> se coucher : ἐπὶ τὰ ἴσχια, PLAT. <i>Phædr. 254</i> b, sur les flancs, <i>en parl. de chevaux ;</i><br><b>      3</b> <i>en parl. d’une armée,</i> s’établir dans une position, camper, THC. <i>4, 93 ;</i><br><b>      4</b> <i>en parl. de navires,</i> s’échouer, POL. <i>1, 39, 3 ;</i> STR. <i>99 ;</i><br><b><i>Moy.</i></b> (<i>fut</i>. καθιζήσομαι) s’asseoir, PLAT. <i>Phædr. 229</i> a, <i>etc. ;</i> DÉM. <i>532, 20, etc. ; en parl. d’oiseaux,</i> se poser, ARSTT. <i>H.A. 9, 10, 1</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. épq</i>. καθῖζον, IL. <i>3, 426, etc. ;</i> OD. <i>16, 408. Dans les inscr. att. seul. le fut</i>. καθιῶ, <i>inf</i>. καθιεῖν, CIA. <i>2, 308, 13 (290/288 av. J.C. ; v. Meisterh. p. 143, 1). Fut. dor</i>. καθιξῶ, BION <i>4, 16. Ao. épq</i>. κάθισα, IL. <i>19, 280 ; part. épq</i>. καθίσσας, IL. <i>9, 488 ; ao. dor. sbj. 3 sg</i>. καθίξῃ, THCR. <i>1, 51 ; part</i>. καθίξας, THCR. <i>1, 12 ; ao. réc</i>. ἐκαθίζησα, DC. <i>37, 27 ; 54, 30. Pf</i>. κεκάθικα, DYSC. <i>Synt. 323 ;</i> DS. <i>17, 115. Ao. pass. part</i>. καθιζηθείς, DC. <i>63, 5. — Ion. prés</i>. κατίζω, HDT. <i>1, 181 ; f</i>. κατίσω, HDT. <i>4, 190, etc</i>.<br><span><b>Étym</b>. <i>cf</i>. καθιζάνω <i>et</i> *καθέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθιζω - καθίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n48 fois dans 46 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (8)</li>\n<li>Luc (8)</li>\n<li>Jean (3)</li>\n<li>Actes (9)</li>\n<li>1 Corinthiens (2)</li>\n<li>Ephésiens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Hébreux (4)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G2524":"<h1>kathiemi</h1>\n<p>Strong n° 2524 <i>Prononciation [kath-ee'-ay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>descendre, faire descendre, envoyer vers le bas</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθ·ίημι</b> <span>(<i>f</i>. καθήσω, <i>ao</i>. καθῆκα, <i>pf</i>. καθεῖκα)</span> <span>[ᾰ]</span><br><b>   I <i>tr.</i></b> faire descendre, <i>d’où :</i><br><b>      1</b> faire tomber, lancer de haut en bas : κεραυνὸν χαμᾶζε, IL. <i>8, 134,</i> la foudre sur la terre ; ὑψόθεν ἐέρσας, IL. <i>11, 53,</i> faire tomber la rosée d’en haut ; οἶνον λαυκανίης, IL. <i>24, 642,</i> faire couler du vin dans son gosier ; ἑαυτὸν εἰς ἅλα, EUR. <i>Hel. 1613, ou</i> ὅπλα εἰς ἅλα, EUR. <i>Hel. 391,</i> se jeter <i>ou</i> jeter des armes dans la mer ; ἄγκυραν, HDT. <i>7, 36 ;</i> δίκτυα, ARSTT. <i>H.A. 4, 8, 12,</i> jeter l’ancre, les filets ; <i>fig</i>. σκῶμμα ἐπί τινα, LUC. <i>M. cond. 34,</i> lancer une raillerie contre qqn ; <i>cf</i>. DC. <i>41, 47 ; 73, 2 ;</i><br><b>      2</b> laisser tomber : τὰς κώπας, THC. <i>2, 91,</i> les rames, <i>de façon à arrêter la marche du navire ;</i> γόνυ πρὸς γαῖαν, EUR. <i>Hec. 561,</i> baisser le genou vers la terre ; κόμας εἰς ὤμους, EUR. <i>Bacch. 695,</i> laisser flotter ses cheveux sur ses épaules ; καθειμένος τὸν πώγωνα, PLUT. <i>Phoc. 10,</i> ayant laissé croître sa barbe ; <i>fig</i>. τὸ καθειμένον τῆς φωνῆς, HDN <i>5, 2,</i> voix basse ;<br><b>      3</b> faire descendre dans la lice, lancer dans la carrière : ἅρματα, THC. <i>6, 16 ;</i> ζεύγη, ISOCR. <i>353</i> d, des chars, des attelages ; <i>fig</i>. εἰς κίνδυνον ἑαυτόν, DH. <i>5, 27,</i> se jeter dans un péril ; διδασκαλίαν, PLUT. <i>Cim. 8,</i> présenter une didascalie ;<br><b>      4</b> faire descendre : πώγωνα, AR. <i>Eccl. 100,</i> laisser descendre, s’étaler sa barbe ; τείχη, THC. <i>4, 103,</i> prolonger des remparts jusqu’en bas ; ὄρη πρὸς τὴν θάλατταν καθειμένα, PLAT. <i>Criti. 118</i> a, montagnes qui s’abaissent vers la mer ;<br><b>      5</b> rappeler d’exil, XÉN. <i>Hell. 2, 3, 20 ;</i><br><b>   II</b> <i>intr. (ou s.-e</i>. ἑαυτόν) descendre (ou se lancer) PLAT. <i>Phæd. 112</i> e ; ἀφ' ὑψηλῶν, XÉN. <i>Hipp. 8, 3,</i> d’un lieu élevé ; εἰς γόνυ, PLUT. <i>Ant. 45,</i> tomber sur le genou ; εἰς ἀγῶνα, PLUT. <i>M. 616</i> d, descendre dans la lice ;<br><b><i>Moy</i>. καθίεμαι</b> <span>(<i>f</i>. καθήσομαι, <i>ao</i>. καθείμην, <i>pf</i>. καθεῖμαι)</span> descendre dans, se transporter dans, <i>avec</i> ἐς <i>et l’acc</i>. HDT. <i>7, 138</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. épq</i>. καθέηκα, IL. <i>24, 641. Ao.2, 1 pl</i>. κάθεμεν, OD. <i>9, 72 ; 3 pl</i>. καθεῖσαν, EUR. <i>Bacch. 695 ; duel</i> κάθετον, HH. <i>2, 309 ; sbj</i>. καθῶ, PLAT. COM. (<i>Com. fr. 2, 622, 4). Ion</i>. κατίημι, <i>d’où ao</i>. κατῆκα, HDT. <i>7, 76 ; ao.2 inf</i>. κατεῖναι, HDT. <i>7, 35, etc. ; pass</i>. κατίεμαι, HDT. <i>2, 28, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθιημι - καθίημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G2525":"<h1>kathistemi</h1>\n<p>Strong n° 2525 <i>Prononciation [kath-is'-tay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fixer, placer, poser\n<ol type=\"a\">\n<li>charger quelqu'un d'une chose</li>\n<li>confier à quelqu'un l'administration d'une fonction</li>\n<li>constituer, déclarer, montrer ce qui doit être</li>\n<li>rendre, faire</li>\n<li>conduire ou amener vers un certain lieu</li>\n<li>se montrer</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθ·ίστημι</b> <span>[ᾰ]</span><br><b>   I</b> <i>tr. aux temps suiv. (prés., impf</i>. καθίστην, <i>f</i>. καταστήσω, <i>ao</i>. κατέστησα, <i>pf</i>. καθέστακα <span>[ᾰκ]</span>, <i>mais v. ci-dessous pf. intr</i>. καθέστηκα) placer devant, présenter :<br><b>      1</b> κρητῆρα, IL. <i>9, 202,</i> une coupe ;<br><b>      2</b> arrêter : νῆα, OD. <i>12, 185,</i> un navire ; πόδα, EUR. <i>Bacch. 184,</i> arrêter ses pas ; <i>avec mouv</i>. transporter pour déposer : τινὰ Πύλονδε, OD. <i>13, 274 ;</i> ἐς Δῖον, THC. <i>4, 78,</i> transporter qqn à Pylos, à Dion ; ἐς φῶς, EUR. <i>Alc. 362,</i> produire à la lumière ;<br><b>      3</b> disposer, établir, <i>acc. en parl. de troupes,</i> XÉN. <i>Cyr. 2, 4, 2, etc. ;</i> ἑαυτὸν εἰς κρίσιν, THC. <i>1, 131,</i> se présenter en jugement ; <i>fig</i>. ἄρχοντα, XÉN. <i>Cyr. 3, 1, 12 ;</i> δικαστάς, AR. <i>Pl. 917,</i> instituer un magistrat, des juges ; νόμους, EUR. <i>Or. 892,</i> établir des lois ; <i>qqf. avec une prop. inf. :</i> τύραννον εἶναί τινα, HDT. <i>5, 94,</i> instituer qqn comme roi <i>ou</i> tyran ; <i>avec un double rég. :</i> δῆμον εἰς μοναρχίαν, EUR. <i>Suppl. 352,</i> constituer un peuple en monarchie ; τινὰ ἐπὶ τὰς ἀρχάς, ISOCR. <i>260</i> a, porter qqn au pouvoir ; τὴν πόλιν ἐν πολέμῳ, PLAT. <i>Men. 242</i> a, engager l’État dans une guerre ; τινὰ εἰς κινδύνους, ANT. <i>118, 5,</i> mettre qqn en péril ; τινὰ εἰς ἀσφάλειαν, ISOCR. <i>107</i> b, <i>ou</i> ἐν ἀκινδύνῳ, XÉN. <i>Cyr. 4, 5, 28,</i> mettre qqn en sûreté ; <i>avec un adj. ou un part. :</i> ἐντιμότερόν τινα, XÉN. <i>Mem. 6, 3, 11,</i> rendre qqn plus honoré, le combler d’honneurs ; κλαίοντά τινα, EUR. <i>Andr. 635,</i> faire pleurer qqn ; τι φανερόν, THC. <i>2, 42,</i> rendre qqe ch. évident ; <i>avec un inf. :</i> τινὰ φεύγειν, THC. <i>2, 84,</i> porter qqn à fuir (<i>propr</i>. le mettre en disposition de fuir) ; <i>particul</i>. établir fermement, mettre dans son assiette, mettre en bon état : τὰς κόρας, ALEX. (ATH. <i>340</i> a) les pupilles (d’un louche) ;<br><b>   II</b> <i>intr. aux temps suiv. (ao.2</i> κατέστην, <i>pf</i>. καθέστηκα, <i>pl.q.pf</i>. καθειστήκειν, <i>f. ant</i>. καθεστήξω) :<br><b>      1</b> se transporter : ἐς Ῥήγιον, THC. <i>3, 86,</i> à Rhégium ; ἐπί τινα, ATT. venir près de qqn, devant qqn ;<br><b>      2</b> être posé, placé, <i>en parl. de troupes,</i> XÉN. <i>An. 2, 1, 1 ; fig</i>. s’établir, se constituer : ὅταν καταστῶσιν οἱ ἄρχοντες, PLAT. <i>Rsp. 543</i> b, aussitôt que les archontes entrent en charge ; καταστῆναι εἰς ἀγῶνα, EUR. <i>Andr. 328 ;</i> εἰς ἔχθραν τινί, ISOCR. <i>202</i> d, entrer en lutte, en rivalité de haine avec qqn ; φύλαξ δέ μου πιστὴ κατέστης, SOPH. <i>O.C. 356,</i> tu es devenue pour moi une gardienne fidèle ; φονέα τινὸς καθεστάναι, SOPH. <i>O.R. 703,</i> être devenu le meurtrier de qqn ; <i>d’où</i> ὅσου κατέστη, PLUT. <i>M. 349</i> a, autant que cela a coûté (<i>propr</i>. autant que le prix auquel cela a été établi) ; <i>particul</i>. prendre <i>ou</i> reprendre son assiette, se fixer, devenir tranquille : ὅταν ἡ λίμνη καταστῇ, AR. <i>Eq. 865,</i> lorsque l’étang est redevenu calme ; κατέστη ὁ θόρυϐος, HDT. <i>3, 80,</i> le tumulte s’apaisa ; <i>p. suite, au pf</i>. avoir pris <i>ou</i> repris son assiette, être établi fermement : θάλασσα καθεστηκυῖα, POL. <i>22, 14, 10,</i> mer calme et unie ; <i>fig</i>. καθεστηκὸς καὶ λεῖον πνεῦμα, AR. <i>Ran. 1003,</i> vent paisible et léger ; καθεστηκυῖα ἡλικία, PLAT. <i>Ep. 316</i> c, l’âge où l’on est un homme posé, rassis, calme ; μαίνεσθαι καὶ ἔξω τοῦ καθεστηκότος εἶναι, LUC. <i>Philops. 5,</i> être en démence et hors de son assiette ; καθεστηκυῖα τιμή, DÉM. <i>918, 25,</i> prix bien établi, <i>càd</i>. convenable, juste ; <i>particul. en parl. de la situation d’un pays, d’institutions, d’affaires en gén. :</i> καθεστῶτες νόμοι, SOPH. <i>Ant. 1113 ;</i> AR. <i>Nub. 1400,</i> lois établies ; κατεστεὼς κόσμος, HDT. <i>1, 65,</i> ordre établi ; τὰ καθεστῶτα, PLAT. <i>Leg. 798</i> b, l’ordre établi, l’état régulier des affaires ;<br><b><i>Moy</i>. καθίσταμαι</b> <span>(<i>f</i>. καταστήσομαι, <i>ao</i>. κατεστησάμην)</span><br><b>      1 <i>tr.</i></b> établir : φρούρημα, ESCHL. <i>Eum. 706,</i> une garde ; <i>fig</i>. τύραννον, HDT. <i>5, 92,</i> un tyran ; ἄρχοντας, XÉN. <i>An. 3, 1, 39,</i> des chefs <i>ou</i> des magistrats ;<br><b>      2</b> <i>intr. (seul. prés. impf. fut.)</i> s’établir, se mettre dans telle <i>ou</i> telle situation : εἰς πόλεμον, EUR. <i>H.f. 1168,</i> entrer en guerre ; εἰς κινδύνους, ANT. <i>118, 5,</i> se mettre en danger ; ἄπαρνος οὐδενὸς καθίστατο, SOPH. <i>Ant. 435,</i> elle ne niait rien.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. au sens act</i>. καθέστακα, SPT. <i>Jer. 1, 10 ; 1 Macc. 10, 20 ; fut. moy</i>. καταστήσομαι, <i>au sens pass. Sur les formes du pf</i>. καθέστηκα, <i>j. au 1<sup>er</sup> siècle av. J.C., v</i>. ἵστημι. <i>À partir de l’époque impériale, au lieu de</i> καθέστηκα <i>on trouve dans les inscr. att. le pf</i>. καθέσταμαι, CIA. <i>2, 471, 24, 80 (commenc. du 1<sup>er</sup> siècle av. J.C.), etc. ; v. Meisterh. p. 153, 9. Ion</i>. κατ. HDT. <i>ll. cc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθιστημι - καθίστημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n21 fois dans 20 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Luc (3)</li>\n<li>Actes (5)</li>\n<li>Romains (2)</li>\n<li>Tite (1)</li>\n<li>Hébreux (3)</li>\n<li>Jacques (2)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2526":"<h1>katho</h1>\n<p>Strong n° 2526 <i>Prononciation [kath-o']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>selon ce que\n<ol type=\"a\">\n<li>comme</li>\n<li>aussi loin que, en raison de</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθ·ό</b>, <i>pour</i> <b>καθ' ὅ :<br>      1</b> selon que, comme, en tant que, LYS. <i>213, 19 ;</i> ARSTT. <i>Metaph. 4, 18, 1, etc. ;</i><br><b>      2</b> de telle sorte que, PLAT. <i>Soph. 267</i> d ; PLUT. <i>M. 51</i> b.<br><span><b><span class=\"arrow\"></span></b> <i>Sans exemple dans les inscr. att. ; seul</i>. καθ' ὅ <i>relatif (v. Meisterh. p. 215, 51)</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθο - καθό</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2527":"<h1>katholou</h1>\n<p>Strong n° 2527 <i>Prononciation [kath-ol'-oo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>entièrement, absolument, tout à fait, sans exception, totalement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθ·όλου</b> <span>[ᾰ]</span> <i>adv. :</i><br><b>      1</b> d’ensemble, en général : καθόλου τὰς πράξεις γράφειν, POL. <i>3, 32, 8,</i> écrire l’histoire générale (<i>p. opp. à</i> κατὰ μέρος) ; ἡ τῶν καθ. πραγμάτων σύνταξις, POL. <i>1, 4, 2,</i> histoire universelle ; τὸ καθόλου, DS. <i>1, 77 ;</i> PLUT. <i>M. 1109</i> f, d’une manière générale, généralement ; <i>particul. t. de philos</i>. le général <i>ou</i> l’idéal, ARSTT. <i>Rhet. 1, 2, 15, etc. (p. opp. à</i> τὸ κατὰ μέρος, le particulier) ; ἡ καθ. ἀπόδειξις, ARSTT. <i>An. post. 24,</i> preuve universelle (<i>p. opp. à</i> ἡ κατὰ μέρος) ;<br><b>      2</b> au total, <i>d’où</i> absolument, SPT. <i>Ex. 22, 11 ; avec une nég</i>. οὐ κ. DÉM. <i>827, 9,</i> pas du tout.<br><span><b>Étym</b>. <i>pour</i> καθ' ὅλου, <i>ainsi écrit d’ordinaire avant Aristote</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθολου - καθόλου</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2528":"<h1>kathoplizo</h1>\n<p>Strong n° 2528 <i>Prononciation [kath-op-lid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>fourni en armes, être revêtu de ses armes</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθ·οπλίζω</b> <span>(<i>ao</i>. καθώπλισα)</span> <span>[ᾰ]</span><br><b>      1</b> armer, ESCHN. <i>75, 33 ;</i> PLUT. <i>Phil. 9 ; p. ext</i>. munir de, pourvoir de : τινί, JOS. <i>Macc. 7, 117,</i> de qqe ch. ;<br><b>      2</b> triompher de, vaincre, <i>acc</i>. SOPH. <i>El. 1086 ;</i><br><b><i>Moy.</i></b> s’armer, POL. <i>3, 62, 7</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθοπλιζω - καθοπλίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2529":"<h1>kathorao</h1>\n<p>Strong n° 2529 <i>Prononciation [kath-or-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>regarder vers en bas, voir de dessus, voir d'une hauteur</li>\n<li>voir complètement, percevoir clairement, comprendre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθ·οράω</b> <span>[κᾰ]</span> <span>(<i>f</i>. κατόψομαι, <i>ao.2</i> κατεῖδον, <i>etc</i>.)</span><br><b>      1</b> regarder d’en haut, IL. <i>7, 21 ; 11, 337 ;</i> PLAT. <i>Rsp. 616</i> b ; ἐπί τινος, HDT. <i>7, 44,</i> qqe ch. ;<br><b>      2</b> <i>p. ext</i>. examiner, observer, <i>acc</i>. PLAT. <i>Leg. 905</i> b ; <i>d’où</i> remarquer, se rendre compte de, <i>acc</i>. HDT. <i>2, 38 ;</i> ATT. ; <i>avec le gén. :</i> ἃ πανουργεῖς καθορᾷ σου, AR. <i>Eq. 803,</i> il se rend compte de tes méfaits ;<br><b>      3</b> avoir égard à, respecter : τὸ τοῦ θεοῦ κράτος, SPT. <i>3Macc. 3, 11,</i> la puissance de Dieu ;<br><b><i>Moy.</i></b> voir d’en haut, contempler : ἐπὶ αἶαν, IL. <i>13, 4,</i> la terre.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. κατοράω, HDT. <i>2, 38, etc. ; impf. 3 sg. ion</i>. κατώρα, HDT. <i>7, 208</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθοραω - καθοράω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G2530":"<h1>kathoti</h1>\n<p>Strong n° 2530 <i>Prononciation [kath-ot'-ee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>selon ce que\n<ol type=\"a\">\n<li>aussi loin que</li>\n<li>parce que</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθ·ότι</b>, <i>conj. :</i><br><b>      1</b> comment, de quelle manière, THC. <i>1, 82 ;</i><br><b>      2</b> selon que, comme, SPT. <i>Jos. 3, 7 ;</i> DS. <i>4, 5 ;</i> καθότι δοκεῖ, CIA. <i>2, 349, 5 (av. 270 av. J.C</i>.), comme il semble bon ; καθότι ἂν δοκῇ αὐτῇ, CIA. <i>I. 59, 44 (410 av. J.C</i>.) selon qu’il lui plaira ;<br><b>      3</b> en ce que, en tant que, POL. <i>18, 19, 5</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Forme usuelle dans les inscr. att. (v. Meisterh. p. 214, 49). Ion</i>. κατότι, HDT. <i>7, 2</i>.<br><span><b>Étym</b>. κατά, ὅτι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθοτι - καθότι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G2531":"<h1>kathos</h1>\n<p>Strong n° 2531 <i>Prononciation [kath-oce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>selon que\n<ol type=\"a\">\n<li>juste comme, de même que</li>\n<li>en proportion de, à hauteur de, jusqu'à</li>\n</ol>\n</li>\n<li>depuis, voyant cela, conformément au fait que</li>\n<li>quand, après ceci</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καθ·ώς</b>, <i>conj. :</i><br><b>      1</b> selon que, comme, SPT. <i>1Esdr. 6, 29 ;</i><br><b>      2</b> quand, lorsque, SPT. <i>Neh. 5, 6</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Forme réc., dans les inscr. att. seul. à partir du 2<sup>e</sup> siècle av. J.C. (v. Meisterh. p. 215, 53</i>.<br><span><b>Étym</b>. κατά, ὡς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καθως - καθώς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n181 fois dans 179 versets de 21 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (7)</li>\n<li>Luc (16)</li>\n<li>Jean (31)</li>\n<li>Actes (12)</li>\n<li>Romains (20)</li>\n<li>1 Corinthiens (20)</li>\n<li>2 Corinthiens (12)</li>\n<li>Galates (3)</li>\n<li>Ephésiens (10)</li>\n<li>Philippiens (3)</li>\n<li>Colossiens (5)</li>\n<li>1 Thessaloniciens (12)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (8)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (9)</li>\n<li>2 Jean (2)</li>\n<li>3 Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G2532":"<h1>kai</h1>\n<p>Strong n° 2532 <i>Prononciation [kahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>et, aussi, même, en effet, mais</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καί</b>, <i>conj. et adv. ;</i><br><b>A</b> <i>conj. :</i><br><b>   I</b> et : <i>s’emploie :</i><br><b>      1</b> <i>dans une même propos. pour unir deux mots de même catégorie (noms, adj., verbes, etc</i>.) : αἱ βάλανοι τῶν φοινίκων θαυμάσιαι ἦσαν τὸ κάλλος καὶ τὸ μέγεθος, XÉN. <i>An. 2, 3, 15,</i> les dattes étaient merveilleuses de beauté et de grosseur ; δεινόν τινα λέγεις καὶ θαυμαστὸν ἄνδρα, PLAT. <i>Rsp. 586</i> c, tu parles là d’un homme bien habile et merveilleux ; <i>même si les deux mots expriment une idée contraire, dans ce cas</i> καί <i>équivaut à notre</i> « mais » : εἰ δέ τι τυγχάνει ἀηδὲς καὶ ὠφέλιμον, PLAT. <i>Gorg. 502</i> b, et s’il se trouve qu’une chose est à la fois désagréable et utile (<i>càd</i>. mais utile) ; <i>particul. pour attirer l’attention sur une partie d’un tout :</i> θεῶν ἁπάντων ᾤετο καὶ Ποσειδῶνος κρατήσειν, ESCHL. <i>Pers. 749,</i> il pensait devoir être plus fort que tous les dieux et que Poséidon en particulier ; <i>pour exprimer avec plus de précision une idée générale :</i> πρὸς δῶμα Διὸς καὶ μακρὸν Ὄλυμπον, IL. <i>5, 398,</i> vers la demeure de Zeus, vers le vaste Olympe ; <i>cf</i>. HH. <i>Ap. 17 ; après l’adj</i>. πολύς, <i>pour rattacher à l’idée de nombre une idée de qualité :</i> πολλοὶ καὶ ἀγαθοὶ φίλοι εἰσὶν ἐμοί, XÉN. <i>Cyr. 5, 2, 11,</i> j’ai beaucoup de bons amis ; ὑμᾶς εἶδον εἰς πολλὰ καὶ ἀμήχανα ἐμπεπτωκότας, XÉN. <i>An. 2, 3, 18,</i> j’ai vu que vous étiez tombés dans de graves et nombreux embarras ; — <i>après les adj. ou adv. qui marquent la parité ou la ressemblance :</i> εἰ τοίνυν ἐκεῖνοι γνώμῃσι ἐχρέοντο ὁμοίῃσι καὶ σύ, HDT. <i>7, 50,</i> si donc ils avaient les mêmes sentiments que toi ; σεϐίζω σ' ἴσα καὶ μάκαρας, EUR. <i>El. 994,</i> je t’honore à l’égal des bienheureux ; <i>cf</i>. SOPH. <i>O.R. 612, O.R. 1187 ;</i> THC. <i>2, 60 ; 3, 14, etc. ;</i> αἱ δαπάναι οὐχ ὁμοίως καὶ πρίν, ἀλλὰ πολλῷ μείζους καθέστασαν, THC. <i>7, 28,</i> les dépenses étaient non plus les mêmes qu’auparavant, mais bien plus considérables ; — <i>après les adj. ou adv. qui marquent une idée de différence</i> (<i>v</i>. ἄλλος <i>et</i> ἄλλως, ἕτερος <i>et</i> ἑτέρως) : πᾶν τοὐναντίον ἔχει νῦν τε καὶ ὅτε, PLAT. <i>Leg. 967</i> a, c’est maintenant tout le contraire du temps où, <i>etc. ;</i><br><b>      2</b> <i>pour unir deux propos. :</i> ὁ ἵππος πίπτει εἰς γόνατα, καὶ μικροῦ κἀκεῖνον ἐξετραχήλισεν, XÉN. <i>Cyr. 1, 4, 8,</i> le cheval tombe sur les genoux, et peu s’en fallut qu’il ne précipitât Cyrus ; <i>même si les deux propos. expriment une idée contraire :</i> γιγνώσκειν ὅστις τε εὐδαίμων ἐστὶ καὶ ὅστις μή, PLAT. <i>Gorg. 472</i> d, apprendre qui est heureux et qui ne l’est pas ; <i>cf</i>. PLAT. <i>Theæt. 176</i> b ; — <i>pour marquer une conséquence de l’idée exprimée dans la première propos. :</i> σμικρὸν λαϐὲ παράδειγμα καὶ πάντα εἴσει ἃ βούλομαι, PLAT. <i>Theæt. 154</i> c, prends un petit exemple et tu sauras tout ce que je veux dire ; — <i>pour marquer un rapport de simultanéité entre deux propos. :</i> καὶ ἤδη τε ἦν περὶ πλήθουσαν ἀγορὰν καὶ ἔρχονται παρὰ βασιλέως κήρυκες. XÉN. <i>An. 2, 1, 7,</i> c’était l’heure où le marché est plein, lorsque arrivèrent des hérauts de la part du grand roi ; καὶ ἥκομεν καὶ ἡμῖν ἐξελθὼν ὁ θυρωρὸς εἶπε, PLAT. <i>Phæd. 59</i> e, nous étions arrivés : alors le portier sortit et nous dit ; οἱ Λακεδαιμόνιοι οὐκ ἔφθασαν τὴν ἀρχὴν κατασχόντες καὶ τοῖς Θηϐαίοις εὐθὺς ἐπεϐούλευσαν, ISOCR. <i>8, 98 Baiter-Sauppe,</i> les Lacédémoniens ne furent pas plus tôt en possession du pouvoir qu’ils tendirent des embûches aux Thébains ;<br><b>      3</b> <i>au commenc. d’une phrase :</i> καὶ ὁ Σωκράτης ἔφη, PLAT. <i>Phæd. 60</i> a, alors Socrate dit ; <i>particul. dev. un impér. pour marquer un mouvement d’affection ou d’encouragement au sens du franç</i>. « et maintenant » <i>ou</i> « allons ! » : καί μοι δὸς τὴν χεῖρα, IL. <i>23, 75,</i> allons ! donne-moi la main ; καί μοι λέγε, PLAT. <i>Euthyphr. 3</i> a, allons ! dis-moi, <i>etc. ; — dans les interrog. pour donner plus de vivacité à la phrase :</i> καὶ ταῦτα δρᾶν νοεῖς ; SOPH. <i>Ph. 921,</i> et tu penses à faire cela ? κἄπειτ' ἔκανες ; EUR. <i>Med. 1398,</i> et c’est par suite de cet amour (<i>càd</i>. parce qu’ils te sont chers) que tu les as tués ? — <i>Rem. Au sens de</i> « et » καί <i>se construit en relation avec un autre</i> καί <i>au sens de</i> « et… et » : ἐπολιόρκει Μίλητον καὶ κατὰ γῆν καὶ κατὰ θάλατταν, XÉN. <i>An. 1, 1, 7,</i> il assiégeait Milet et par terre et par mer ; καὶ τότε καὶ νῦν, PLAT. <i>Phil. 60</i> c, et alors et maintenant ; <i>au sens de</i> « aussi bien que », « non seulement… mais encore » : ἐν τῇ Κύρου ἀρχῇ ἐγένετο καὶ Ἕλληνι καὶ βαρϐάρῳ μηδὲν ἀδικοῦντι ἀδεῶς πορεύεσθαι ὅπῃ τις ἤθελεν, XÉN. <i>An. 1, 9, 13,</i> dans le gouvernement de Cyrus, il était loisible à tout Grec ou barbare qui ne faisait rien de mal d’aller sans crainte par où il voulait ; <i>dans cette construct. le second</i> καί <i>peut avoir une valeur restrictive, au sens de notre</i> « et cependant » : σὺ καὶ δέδορκας, κοὐ βλέπεις ἵν' εἶ κακοῦ, SOPH. <i>O.R. 413,</i> toi tu vois (la lumière du jour) et cependant tu ne vois pas l’étendue de ton malheur. <i>Dans une énumération,</i> καί <i>est répété autant de fois qu’il y a de termes dans l’énumération :</i> Ἀγησιλάῳ ἑαυτὸν καὶ τὴν γυναῖκα καὶ τὰ τέκνα καὶ τὴν δύναμιν ἐνεχείρισε, XÉN. <i>Ages. 3, 3</i> (le Perse Spithridatès) se remit à la discrétion d’Agésilas avec sa femme, ses enfants et toute sa fortune ; αἱ δὲ ἔλαφοι καὶ δορκάδες καὶ οἱ ἄγριοι οἶες καὶ οἱ ὄνοι οἱ ἄγριοι, XÉN. <i>Cyr. 1, 4, 7,</i> les biches, les chevreuils, les brebis sauvages et les onagres ; <i>ainsi répété quatre fois,</i> SOPH. <i>O.R. 1091 ; cinq fois,</i> SOPH. <i>Ant. 354 ; dans ce cas, le dernier</i> καί <i>peut être remplacé par</i> δέ, <i>lorsqu’on veut appeler l’attention particulièrement sur ce dernier terme</i> (<i>v</i>. δέ) ; <i>avec</i> τε <i>antérieur pour relier plus étroitement deux mots d’une propos. :</i> ἀεί τε καὶ τότε, PLAT. <i>Phædr. 254</i> a, et toujours et alors en particulier ; ἐθήρευεν ἀπὸ ἵππου, ὁπότε γυμνάσαι βούλοιτο ἑαυτόν τε καὶ τοὺς ἵππους, XÉN. <i>An. 1, 2, 7,</i> Cyrus chassait à cheval, toutes les fois qu’il voulait s’exercer lui et ses chevaux ; <i>particul. entre</i> πολύς <i>ou</i> ὀλίγος <i>et un autre adj. :</i> πολλάς τε καὶ εὐδαίμονας καὶ μεγάλας πόλεις οἰκοῦσιν, XÉN. <i>An. 3, 2, 23,</i> (les Mysiens) habitent un grand nombre de villes florissantes et considérables ; πολλὰ καὶ κακά, πολλά τε καὶ ἀνόσια, PLAT. <i>Rsp. 615</i> d, beaucoup de mauvaises choses, et aussi beaucoup de choses impies ; <i>dans cette construct. la propos. commençant par</i> καί <i>peut être anacoluthique :</i> ἔρχεται δὲ αὐτὴ ἡ Μανδάνη πρὸς τὸν πατέρα καὶ τὸν Κῦρον τὸν υἱὸν ἔχουσα, XÉN. <i>Cyr. 1, 3, 1 (pour</i> καὶ ὁ Κῦρος ὁ υἱὸς μετ' αὐτῆς ἔρχεται), Mandane arrive chez son père amenant avec elle son fils Cyrus ; <i>cf</i>. HDT. <i>9, 104, etc. ; — avec</i> τε <i>postérieur,</i> SOPH. <i>Ph. 421, 581, etc</i>. (<i>v</i>. τε) ;<br><b>   II</b> et même, même :<br><b>      1</b> <i>entre deux adj. dont le second renchérit sur le sens du premier,</i> « et même », « et de plus », « et en outre » : ἀλλὰ παρῆσάν τινες καὶ πολλοί γε, PLAT. <i>Phæd. 58</i> d, mais il y en avait là quelques-uns et même en grand nombre ; ἡ ἀνθρωπίνη σοφία ὀλίγου τινὸς ἀξία ἐστὶ καὶ οὐδενός, PLAT. <i>Ap. 23</i> a, la sagesse humaine a bien peu de valeur ou même elle n’en a aucune ; <i>dans cette construct. dev. un compar. ou un superl</i>. ἐχθροὶ καὶ ἔχθιστοι, THC. <i>7, 68,</i> ennemis et même ennemis acharnés ;<br><b>      2</b> <i>dans les locut</i>. καὶ τοῦτο, καὶ ταῦτα, <i>au sens du franç</i>. « et cela » (<i>cf. lat</i>. idque), « et en même temps » : γελᾶν ἀναπείθων, καὶ ταῦθ' οὕτω πολέμιον ὄντα τῷ γέλωτι, XÉN. <i>Cyr. 2, 2, 16,</i> (en) lui persuadant de rire, et cela quand il est un ennemi déclaré du rire ; σὺ δέ μοι δοκεῖς οὐ προσέχειν τὸν νοῦν τούτοις, καὶ ταῦτα σοφὸς ὤν, PLAT. <i>Gorg. 508</i> a, il me semble que tu ne fais pas attention à cela, tout sage que tu es (<i>litt</i>. et cela bien que tu sois sage) ;<br><b>      3</b> <i>dev. un adv. marquant l’affirmation ou placé dev. un adj. pour lui donner la valeur d’un superl</i>. καὶ πάνυ, ATT. ; καὶ μάλα ; IL. <i>13, 237, etc. ;</i> καὶ λίην, OD. <i>1, 46 ; 11, 180, etc</i>. même tout à fait ;<br><b>   III</b> et en outre : παντάπασιν ἀπόρων ἐστὶ καὶ ἀμηχάνων καὶ ἀνάγκῃ ἐχομένων, καὶ τούτων πονηρῶν, XÉN. <i>An. 2, 5, 21,</i> c’est un moyen digne de gens absolument dépourvus de ressources, impuissants, pressés par la nécessité, et en outre pervers ;<br><b>   IV</b> et ensuite, puis : μικρὸς καὶ μέγας, SOPH. <i>O.R. 1082,</i> petit d’abord, grand ensuite ;<br><b>   V</b> ou : ὁμοίως καὶ παραπλησίως, DÉM. <i>36, commenc</i>. semblablement ou d’une façon très rapprochée ; <i>particul. entre deux n. de nombre :</i> ἕνα καὶ δύο, IL. <i>2, 346,</i> un ou deux ; δύο καὶ τρία βήματα, XÉN. <i>An. 4, 7, 10,</i> deux ou trois pas ; <i>avec le plus petit nombre le dernier :</i> ἐν ἓξ καὶ πέντε σταδίοις, POL. en cinq ou six stades ;<br><b>B</b> <i>adv</i>., aussi, même :<br><b>   I</b> aussi, de même : ἔστι δὲ καὶ βασίλεια ἐν Κελαιναῖς, XÉN. <i>An. 1, 2, 8,</i> il y a aussi un château royal à Kélænes, <i>càd</i>. un autre château royal ; <i>particul. :</i><br><b>      1</b> <i>dans une propos. en corrélation avec une propos. conditionn. :</i> ἐὰν τριγώνου αἱ δύο γωνίαι ἴσαι ἀλλήλαις ὦσι, καὶ αἱ ὑπὸ τὰς ἴσας γωνίας ὑποτείνουσαι πλευραὶ ἴσαι ἀλλήλαις ἔσονται, EUCL. <i>Elem. 1, 6,</i> si deux angles d’un triangle sont égaux entre eux, les côtés opposés aux angles égaux seront également égaux entre eux ;<br><b>      2</b> <i>dans les périodes qui expriment une comparaison, et où</i> καί <i>s’emploie : dans la propos. démonstrative seule :</i> γίγνεται γὰρ δὴ καὶ παισὶ πρὸς ἀλλήλους ὥσπερ ἀνδράσιν ἐγκλήματα, XÉN. <i>Cyr. 1, 2, 6,</i> car parmi les enfants les uns à l’égard des autres, comme parmi les hommes, naissent des accusations ; — <i>dans les deux propos. (démonstrative et relative</i>) : σκέψαι δὴ ἐὰν ἄρα καὶ σοὶ ξυνδοκῇ ἅπερ καὶ ἐμοί, PLAT. <i>Phæd. 64</i> c, examine donc si toi aussi tu penses comme moi ; ἀπάγγελλε τοίνυν ὅτι καὶ ἡμῖν ταὐτὰ δοκεῖ ἅπερ καὶ βασιλεῖ, XÉN. <i>An. 2, 1, 22,</i> retourne donc annoncer que nous sommes du même avis que le roi ; δεῖ ὑμᾶς, ὥσπερ καὶ τιμῶν μεθέξετε, οὕτω καὶ τῶν κινδύνων μετέχειν, XÉN. <i>Hell. 2, 4, 9,</i> il faut que, partageant les honneurs, vous partagiez de même les périls ; — <i>dans la propos. relative seule :</i> βασιλεὺς ὥσπερ καὶ ἐν πολέμῳ ἡγεμών ἐστιν αὐτοῖς, XÉN. <i>Cyr. 1, 2, 10,</i> le roi les conduit là (à la chasse) absolument comme à la guerre ; <i>même lorsqu’il semblerait que</i> καί <i>se rattache plutôt à la propos. démonstrative :</i> ὅσ' οἶδα κἀγὼ πάντ' ἐπιστήσει κλύων, SOPH. <i>O.C. 53,</i> écoute, et tout ce que je sais moi-même, tu le sauras (<i>pour</i> ὅσ' οἶδ' ἐγὼ καὶ σὺ ἐπιστήσει, tout ce que je sais, tu le sauras toi-même) ; <i>cf</i>. SOPH. <i>O.C. 77 ;</i> XÉN. <i>Cyr. 4, 2, 22 ;</i> AN. <i>7, 7, 47 ;</i><br><b>      3</b> <i>dans les locut</i>. εἴ τις καὶ ἄλλος, <i>etc. ;</i> ὥς τις καὶ ἄλλος, <i>etc. ;</i> εἴ τις καὶ ἄλλος ἀνήρ, καὶ Κῦρος ἄξιός ἐστι θαυμάζεσθαι, XÉN. <i>Cyr. 5, 1, 6,</i> si qqn est digne d’admiration, c’est bien Cyrus ; εἴπερ τις καὶ ἄλλος, PLAT. <i>Phæd. 66</i> a, si jamais il en fut ; <i>cf</i>. PLAT. <i>Phæd. 58</i> e : ἱκανὸς ὥς τις καὶ ἄλλος φροντίζειν ἦν ὅπως ἔχοι ἡ στρατιὰ τὰ ἐπιτήδεια, XÉN. <i>An. 2, 6, 8,</i> il était capable autant que personne d’imaginer les moyens de fournir des vivres à l’armée ;<br><b>      4</b> <i>devant les pron</i>. αὐτός <i>et</i> οὗτος : καὶ αὐτός, lui-même aussi (<i>lat</i>. ipse quoque) ; καὶ οὗτος, celui-ci aussi (<i>lat</i>. hic quoque) : ἐπειδὴ σαφῶς ἀπιόντας ἤδη ἑώρων οἱ Ἕλληνες, ἐπορεύοντο καὶ αὐτοὶ ἀναζεύξαντες, XÉN. <i>An. 3, 4, 37,</i> lorsque les Grecs virent (les barbares) s’éloigner sans qu’on en pût douter, ils levèrent le camp eux aussi et se mirent en marche ; ῥεῖ ὁ Μαίανδρος διὰ τῆς πόλεως· ἔστι δὲ καὶ βασίλεια ἐν Κελαιναῖς ἐπὶ ταῖς πηγαῖς τοῦ Μαρσύου ποταμοῦ· ῥεῖ δὲ καὶ οὗτος διὰ τῆς πόλεως, XÉN. <i>An. 1, 2, 8,</i> le Méandre coule à travers la ville ; il y a aussi un château royal à Kélænes aux sources du Marsyas ; ce fleuve aussi coule à travers la ville ;<br><b>      5</b> <i>devant les pron</i>. ἐγώ, ἡμεῖς, σύ, <i>etc. :</i> ἦ καὶ ἐγὼ εἴπω ὅ τι γιγνώσκω ; XÉN. <i>Cyr. 2, 4, 8,</i> et moi aussi dirai-je ce que je pense ? <i>cf</i>. κἀγώ, SOPH. <i>Ph. 192, etc. ;</i> κἀμοῦ, SOPH. <i>O.R. 575, etc. ;</i> κἀμοί, SOPH. <i>O.R. 1356, etc. ;</i> κἀμέ, SOPH. <i>Ph. 1255, etc. ;</i> χἠμεῖς, SOPH. <i>O.C. 1037, etc. ;</i> καὶ σύ, SOPH. <i>Ph. 248, etc. ;</i> καὶ σοί, SOPH. <i>O.R. 1294, etc. ; devant les pron. réfléchis :</i> κἀμαυτήν, SOPH. <i>El. 332,</i> moi-même aussi ; <i>devant les pron. démonstrat. :</i> κἀκείνῳ, SOPH. <i>El. 459,</i> à celui-là aussi ; <i>devant les pron. possessifs :</i> κἀμὸν γένος, SOPH. <i>El. 965,</i> ma race aussi ;<br><b>      6</b> <i>devant l’article :</i> χὠ, SOPH. <i>El. 1030,</i> et le… aussi, <i>etc. ;</i><br><b>      7</b> <i>devant un adv. :</i> κἀνταῦθα, SOPH. <i>Ph. 429,</i> et là aussi ; καὶ νῦν, SOPH. <i>Ph. 1011, etc</i>. maintenant encore ; καὶ ὡς, ATT. de cette manière aussi ; <i>particul. devant un adv. de temps et en corrélation avec une conj. antérieure marquant une idée de temps, pour exprimer une idée de simultanéité, surt. chez les Épq. :</i> ἦμος δ' ἠέλιος μέσον οὐρανὸν ἀμφιϐεϐήκει, καὶ τότε δὴ χρύσεια πατὴρ ἐτίταινε τάλαντα, IL. <i>8, 68,</i> mais quand le soleil fut monté au milieu du ciel, juste à ce moment le maître des dieux tendit ses balances d’or ; <i>de même</i> ὅτε… καὶ τότε : ἀλλ' ὅτε δή… καὶ τότε δή, IL. <i>1, 494,</i> mais lorsque… alors, <i>etc. ; cf</i>. IL. <i>24, 31 ; ou simpl. sans être construit devant un autre adv., pour marquer une corrélation avec une conj. antérieure exprimant soit une idée de temps, soit une condition :</i> ἐπεὶ… καί : αὐτὰρ ἐπεὶ δείπνησε, καί οἱ δῶκε σκύφος, OD. <i>14, 111,</i> quand il eut achevé son repas, alors (Eumée) lui donna la coupe ; <i>cf</i>. OD. <i>3, 130 ;</i> εἰ δέ τευ ἐξ ἄλλου γε θεῶν γένευ, καί κεν δὴ πάλαι, <i>etc</i>. IL. <i>5, 897,</i> mais si tu étais né de quelque autre dieu, sans doute il y a longtemps que, <i>etc. ;</i><br><b>   II</b> même :<br><b>      1</b> <i>en gén. :</i> Ἀγησίλαος καὶ ὁπότε εὐτυχοίη, οὐκ ἀνθρώπων ὑπερεφρόνει, ἀλλὰ θεοῖς χάριν ᾔδει, XÉN. <i>Ages. 11, 2,</i> Agésilas, même dans la prospérité, ne méprisait pas les hommes, et quant aux dieux, il leur rendait grâces ; <i>particul. dev. un superl. pour en augmenter encore la valeur :</i> σκέψασθε εἰ ἄρα τοῦτο καὶ μωρότατον πεποιήκασιν οἱ βάρϐαροι, XÉN. <i>An. 3, 2, 22,</i> voyez si par hasard ce ne serait même pas là la plus grande folie qu’auraient faite les barbares ; οὗτοι οἱ λόγοι καὶ μάλιστα ἐνδύονται ταῖς ψυχαῖς τῶν ἀκουόντων, XÉN. <i>Cyr. 2, 1, 13,</i> ces discours s’enfoncent profondément dans l’esprit de ceux qui les entendent ; <i>cf</i>. PLAT. <i>Epin. 985</i> c, <i>etc. ; — dev</i>. τοῦτο <i>ou</i> ταῦτα : ἀλλ' ἀρκεῖ καὶ τοῦτο, PLAT. <i>Gorg. 498</i> a <i>ou</i> ἀλλὰ καὶ ταῦτα ἀρκεῖ, PLAT. <i>Phæd. 108</i> e, mais cela (même) suffit ; <i>après</i> εἴπερ <i>et</i> ἵνα : εἴπερ καὶ νῦν, PLAT. <i>Parm. 155</i> d, si toutefois maintenant ; ἵνα καὶ εἰδῶ ὅ τι λέγεις, PLAT. <i>Gorg. 467</i> c, afin que je sache ce que tu veux dire ; <i>cf</i>. PLAT. <i>Theæt. 163</i> c, <i>Rsp. 450</i> c, <i>etc. En ce sens, construit dev. un part</i>. καί <i>équivaut à</i> « quoique » : πὰρ δύναμιν δ' οὐκ ἔστι καὶ ἐσσύμενον πολεμίζειν, IL. <i>13, 787,</i> même (<i>càd</i>. quoique) emporté par son ardeur, un guerrier ne peut combattre au delà de ses forces ; ἐγὼ σκοτώσω βλέφαρα καὶ δεδορκότα, SOPH. <i>Aj. 85,</i> j’obscurcirai ses paupières même ouvertes à la lumière du jour ; <i>particul. dev. un n. de nombre :</i> γενομένης καὶ δὶς ἐκκλησίας, THC. <i>1, 44, litt</i>. une assemblée ayant été tenue jusqu’à deux fois ;<br><b>      2</b> même, <i>au sens de</i> « seulement » : ἱέμενος καὶ καπνὸν νοῆσαι, OD. <i>1, 58,</i> (Ulysse) qui souhaiterait voir seulement la fumée (s’élever de la terre natale) ;<br><b>C</b> <i>Rem. :</i><br><b>   I</b> <i>conj. ou adv</i>. καί <i>se joint à diverses particules :</i><br><b>      1</b> καὶ ἄν (<i>v</i>. ἄν) ;<br><b>      2</b> καὶ γάρ, et en effet ; <i>en ce sens</i> καί <i>se rapporte à ce qui suit immédiatement,</i> IL. <i>3, 188 ; cf</i>. OD. <i>18, 261, etc. ;</i> XÉN. <i>An. 2, 1, 5, etc. ;</i> — car aussi bien, <i>avec un second</i> καί <i>ayant le sens de notre</i> « que » <i>dans la locut</i>. « aussi bien… que », XÉN. <i>An. 1, 9, 10 ;</i> — et en effet, <i>pour rattacher plus étroitement la propos. à ce qui précède, particul. pour annoncer un développement de preuves,</i> XÉN. <i>An. 2, 6, 2 ;</i> — καὶ γὰρ οὖν, ainsi donc, par conséquent, XÉN. <i>An. 1, 9, 8 et 9</i> — καὶ γάρ τοι, <i>m. sign</i>. ISOCR. <i>7, 30 Baiter-Sauppe ;</i> — καὶ γὰρ δή (<i>v</i>. γάρ) ; — καὶ γὰρ δὴ τότε, IL. <i>16, 810,</i> et en effet certes ; — καὶ γάρ ῥα, IL. <i>1, 113, m. sign. ;</i> — καὶ γὰρ… τε, IL. <i>1, 63,</i> et en effet… aussi ;<br><b>      3</b> καί γε, et certes : καὶ καλῶς γε, ἔφη, λέγεις, PLAT. <i>Rsp. 314</i> d, et vraiment tu parles bien, dit-il ; <i>cf</i>. PLAT. <i>Rsp. 335</i> b ;<br><b>      4</b> καὶ… δέ, et… aussi, et… de plus : Δαρεῖος Κῦρον σατράπην ἐποίησε, καὶ στρατηγὸν δὲ ἀπέδειξεν, XÉN. <i>An. 1, 1, 2,</i> Darius fit Cyrus satrape, et le nomma en outre chef d’armée ;<br><b>      5</b> καὶ δή, et déjà, et voilà que, IL. <i>1, 161 ; 2, 135 ; 15, 251 ;</i> OD. <i>9, 496 ; 10, 30 ; 22, 249 ;</i> — καὶ δὴ καί, PLAT. <i>Phæd. 59</i> d, et naturellement aussi ; <i>cf</i>. PLAT. <i>Phæd. 112</i> e, <i>Pol. 268</i> e, <i>Rsp. 618</i> a ;<br><b>      6</b> καὶ εἰ <i>ou</i> κεἰ, même si, quand même, quand bien même : Μυσοῖς βασιλεὺς πολλοὺς μὲν ἡγεμόνας ἂν δοίη καὶ ὁδοποιήσειέ γ' ἂν αὐτοῖς, καὶ εἰ σὺν τεθρίπποις βούλοιντο ἀπιέναι, XÉN. <i>An. 3, 2, 24,</i> le grand roi donnerait aux Mysiens beaucoup de guides, et irait jusqu’à leur frayer des routes, même si c’était avec des chars attelés de quatre chevaux qu’ils voulaient se retirer ; <i>dans Hom</i>. καὶ εἰ <i>se construit soit avec l’indic</i>. IL. <i>13, 316 ; 15, 51, etc. ; soit avec le sbj</i>. IL. <i>5, 351 ;</i> OD. <i>16, 98, etc. ; soit avec l’opt</i>. IL. <i>4, 347 ; 9, 318 ;</i> OD. <i>13, 292, etc. ;</i> — εἰ καί <i>ou</i> ἢν καί, <i>m. sign. :</i> πάντες ποταμοί, εἰ καὶ πρόσω τῶν πηγῶν ἄποροί εἰσι (<i>var</i>. ἢν καὶ… ὦσι) προσιοῦσι πρὸς τὰς πηγὰς διαϐατοὶ γίγνονται, XÉN. <i>An. 3, 2, 22,</i> tous les fleuves, alors même qu’on ne les peut traverser à quelque distance de leur source, deviennent guéables dans le voisinage des sources ; <i>dans Hom</i>. εἰ καί <i>se construit d’ord. avec l’ind</i>. IL. <i>3, 215 ; 5, 410 ;</i> OD. <i>6, 313, etc. ; qqf. avec l’opt</i>. OD. <i>8, 117, 139 ; la construct</i>. καὶ εἰ <i>est qqf. remplacée par</i> καί <i>suivi d’un part. :</i> Ἕκτορα καὶ μεμαῶτα μάχης σχήσεσθαι ὀΐω, IL. <i>9, 655,</i> je pense que, malgré son ardeur (<i>litt</i>. quoique ardent) Hector se retirera du combat ; <i>cf</i>. IL. <i>13, 787 ; 16, 627 ;</i> OD. <i>2, 343 ; et souvent chez les Att. ;</i><br><b>      7</b> καὶ μέν, et en outre, <i>d’ord. avec une ou plusieurs particules :</i> καὶ μὲν δή, PLAT. <i>Gorg. 507</i> b, et en outre, bien plus ; καὶ μὲν δὴ… γε, <i>m. sign</i>. PLAT. <i>Theæt. 155</i> e, <i>Pol. 287</i> d, <i>Conv. 197</i> a, <i>etc. ;</i><br><b>      8</b> καὶ μήν <i>pour affirmer avec plus de force :</i> et certes, et en vérité, PLAT. <i>Phæd. 84</i> d, <i>88</i> e ; <i>Theæt. 143</i> e ; — <i>pour marquer une objection :</i> et pourtant, <i>usuel en ce sens chez les Att. ; — ou simpl. pour ajouter à ce qui vient d’être dit :</i> « d’ailleurs », « en outre », « mais de plus », XÉN. <i>An. 1, 9, 10 ;</i> — καὶ μήν γε, <i>pour affirmer avec plus de force,</i> PLAT. <i>Pol. 328</i> d ;<br><b>      9</b> καί νύ κε δή, et alors en ce moment même, <i>avec idée d’un conditionnel,</i> IL. <i>7, 273 ; 23, 490 ;</i> OD. <i>21, 128</i> :<br><b>      10</b> καί περ (<i>v</i>. καίπερ) :<br><b>      11</b> καί ῥα <i>pour lier plus étroitement deux propos</i>. et donc, et alors, IL. <i>1, 360 ; cf</i>. OD. <i>2, 362</i> :<br><b>      12</b> καί τε, et même, IL. <i>1, 521 ; cf</i>. OD. <i>23, 13 ;</i> καί τ' οὔνομα (<i>vulg</i>. καὶ τοὔνομα) IL. <i>3, 235,</i> et (je dirais) même le nom (de chacun d’eux) ; <i>particul. au commencement d’une période,</i> OD. <i>17, 485</i> :<br><b>      13</b> καί τοι (<i>v</i>. καίτοι) ;<br><b>   II</b> <i>En poésie</i> καί <i>se réduit qqf. par élision à</i> κ' : εἰ δέ κ' ἔτι, IL. <i>23, 526,</i> et si même (la course était) encore (plus longue) ; <i>cf</i>. OD. <i>18, 318 (dans ces passages, beaucoup d’édd. prennent</i> κ' <i>p</i>. κέ, <i>cf</i>. κέν, E, 5) ;<br><b>   III</b> καί <i>se contracte par crase :</i><br><b>      1</b> <i>avec l’art. :</i> χὠ, SOPH. <i>Aj. 456, O.R. 401, etc. ;</i> χἠ, SOPH. <i>El. 1042, Ph. 326, etc. ;</i> χοἰ, SOPH. <i>O.R. 275, etc. ;</i><br><b>      2</b> <i>avec des subst. ;</i> κεὐγένειαν = καὶ εὐγένειαν, ESCHL. <i>Pers. 442, etc. ;</i><br><b>      3</b> <i>avec des adj</i>. κἀγαθός, SOPH. <i>Ph. 119, etc</i>. (<i>v</i>. ἀγαθός) ; κἀδάκρυτος, SOPH. <i>Tr. 1200 ;</i> καἰσχρῶν <i>ou</i> κᾀσχρῶν = καὶ αἰσχρῶν, ESCHL. <i>Sept. 685 ;</i> χἄτερος = καὶ ἕτερος (<i>v</i>. ἕτερος) SOPH. <i>O.C. 1192, etc. ;</i> κἀφανής = καὶ ἀφανής, SOPH. <i>O.C. 77 ;</i> κἄλλος = καὶ ἄλλος (<i>v</i>. ἄλλος) SOPH. <i>Ph. 658, etc. ;</i><br><b>      4</b> <i>avec des pron</i>. κἀγώ (<i>v</i>. ἐγώ) ; κἀμοῦ, SOPH. <i>Aj. 520, O.R. 575, etc. ;</i> κἀμοί, SOPH. <i>Aj. 392 ; O.R. 630, etc. ;</i> κἀμέ, SOPH. <i>Aj. 497, etc. ;</i> χἠμεῖς <i>ou</i> χἡμεῖς (<i>sel. Dind</i>. χ' ἡμεῖς) = καὶ ἡμεῖς, IL. <i>2, 238 ;</i> χὐμεῖς = καὶ ὑμεῖς, ESCHL. <i>Eum. 1003 ;</i> καὐτός, καὐτοῦ = καὶ αὐτός, καὶ αὐτοῦ (<i>v</i>. αὐτός) OD. <i>3, 255 ;</i> SOPH. <i>Aj. 347, etc. ;</i> χαὐτοῦ = καὶ ἑαυτοῦ, SOPH. <i>O.R. 234, etc. ;</i> χοὗτος = καὶ οὗτος, SOPH. <i>Ph. 435 ;</i> χᾦ = καὶ ᾧ, ESCHL. <i>Pr. 915 ;</i> κἀκεῖνος = καὶ ἐκεῖνος, SOPH. <i>Aj. 1035, etc. ;</i><br><b>      5</b> <i>avec des verbes :</i> κἄστιν <i>ou</i> κἀστίν = καὶ ἔστιν <i>ou</i> ἐστίν, SOPH. <i>Aj. 1157, O.R. 1045, etc. ;</i> κἀνάγει = καὶ ἀνάγει, SOPH. <i>Aj. 131 ;</i> κἀναθεῖσα = καὶ ἀναθεῖσα, SOPH. <i>Aj. 476 ;</i> χἀρπάσαι = καὶ ἁρπάσαι, SOPH. <i>Ph. 644 ;</i> κἀποδύρομαι = καὶ ἀποδύρομαι, SOPH. <i>El. 1122 ;</i> κἀπόλωλα = καὶ ἀπόλωλα, SOPH. <i>Ph. 978, etc. ;</i><br><b>      6</b> <i>avec des mots invariables : adverbes :</i> κἀθέως = καὶ ἀθέως, SOPH. <i>O.R. 354, El. 1181 ;</i> κἄτι = καὶ ἔτι, SOPH. <i>O.R. 272, etc. ;</i> κἀχθές = καὶ ἐχθές, SOPH. <i>Ant. 456 ;</i> κἀκεῖ = καὶ ἐκεῖ, SOPH. <i>Aj. 855 ;</i> κἄνθεν = καὶ ἔνθεν, SOPH. <i>Aj. 725 ;</i> κἀντεῦθεν = καὶ ἐντεῦθεν, SOPH. <i>El. 728 ;</i> καὖθις = καὶ αὖθις. SOPH. <i>Aj. 1359 ;</i> κἆτα = καὶ εἶτα, SOPH. <i>O.R. 544, Ant. 1019, etc. ; ou</i> κἆθ' <i>dev. un esprit rude,</i> SOPH. <i>O.R. 1023, etc ; — prépositions :</i> κἀνά = καὶ ἀνά, ESCHL. <i>Sept. 1028 ;</i> κἀπό = καὶ ἀπό, SOPH. <i>Aj. 1230, etc. ; ou</i> κἀφ' <i>dev. un esprit rude,</i> SOPH. <i>O.R. 351 ;</i> κἀν = καὶ ἐν, SOPH. <i>O.R. 757, O.C. 1410, etc. ;</i> κἀκ = καὶ ἐκ <i>et</i> κἀξ = καὶ ἐξ, SOPH. <i>O.R. 458, 563, etc. ; El. 264, etc. ;</i> κἀπί = καὶ ἐπί, SOPH. <i>Aj. 48, etc. ; — conj. :</i> χὤτι = καὶ ὅτι, SOPH. <i>Aj. 1041, O.R. 933, etc. ;</i> χὤτε = καὶ ὅτε, SOPH. <i>O.C. 1035, Ph. 1271 ;</i> χὤταν = καὶ ὅταν, SOPH. <i>O.C. 1530, etc. ;</i> χὤπως = καὶ ὅπως, SOPH. <i>O.R. 1251, etc. ;</i> κεἰ = καὶ εἰ, SOPH. <i>O.R. 227, etc. ; dor</i>. καἰ = καὶ αἰ (<i>p</i>. καὶ εἰ) THCR. <i>29, 16 ; — particules :</i> κἄν = καὶ ἄν, SOPH. <i>Aj. 45, etc. ; ou</i> = καὶ ἐάν, SOPH. <i>Aj. 15, 1068, etc. ; particul. avec la nég</i>. οὐ, οὐκ : κοὐ, SOPH. <i>Aj. 33, etc. ;</i> κοὐκ, SOPH. <i>O.R. 58, etc. ; et avec les dérivés :</i> κοὐδέ = καὶ οὐδέ, SOPH. <i>Ant. 1034 ;</i> κοὐδείς = καὶ οὐδείς, SOPH. <i>O.R. 63, etc. ;</i> κοὔτε = καὶ οὔ τε <i>et</i> καὶ οὔτε, SOPH. <i>Aj. 1232, etc. ;</i> κοὔπω = καὶ οὔπω, SOPH. <i>Tr. 461, etc. ;</i> κοὔποτε = καὶ οὔποτε, SOPH. <i>O.C. 628, etc. (pour un grand nombre de formes analogues, rares ou difficiles, v. le mot à son rang alphabétique</i>).<br><span><b>Étym</b>. <i>indo-europ</i>. *ḱm̥t-, avec, le long de, vers le bas ; <i>p</i>. *κατι, <i>d’où</i> *κασι, κάς (<i>chypriote), cf</i>. κασίγνητος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">και - καί</font>\n<br><br>apparemment, particule primaire, sens de liaison et quelquefois une force cumulative</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Conjonction</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9192 fois dans 5199 versets de 27 livres bibliques (NT)\n<ul>\n<li>Matthieu (1214)</li>\n<li>Marc (1084)</li>\n<li>Luc (1518)</li>\n<li>Jean (860)</li>\n<li>Actes (1120)</li>\n<li>Romains (289)</li>\n<li>1 Corinthiens (292)</li>\n<li>2 Corinthiens (201)</li>\n<li>Galates (74)</li>\n<li>Ephésiens (137)</li>\n<li>Philippiens (107)</li>\n<li>Colossiens (107)</li>\n<li>1 Thessaloniciens (101)</li>\n<li>2 Thessaloniciens (51)</li>\n<li>1 Timothée (95)</li>\n<li>2 Timothée (69)</li>\n<li>Tite (37)</li>\n<li>Philémon (16)</li>\n<li>Hébreux (253)</li>\n<li>Jacques (116)</li>\n<li>1 Pierre (71)</li>\n<li>2 Pierre (62)</li>\n<li>1 Jean (128)</li>\n<li>2 Jean (16)</li>\n<li>3 Jean (11)</li>\n<li>Jude (22)</li>\n<li>Apocalypse (1141)</li>\n</ul>\n</td></tr>\n</table>","G2533":"<h1>Kaiaphas</h1>\n<p>Strong n° 2533 <i>Prononciation [kah-ee-af'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Caïphe (Angl. Caiaphas) = « avenant », « pierre », « dépression »\n<ol><li>un souverain sacrificateur des Juifs nommé à cette fonction par Valerius Gratus, gouverneur de Judée, en remplacement de Simon, fils de Camith, en 18 ap. J.C. et remplacé en 36 ap. J.C. par Jonathan, fils de Ananus, par une décision de Vitellius, gouverneur de Syrie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Καιαφας</font> &lt; קיפא - <font face=\"Georgia\">Καϊάφας</font>\n<br><br>origine : Araméen</td></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n<li>Jean (5)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2534":"<h1>kaige</h1>\n<p>Strong n° 2534 <i>Prononciation [kah'-ee-gheh]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>et au moins, en effet</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\nVoir <b></b>, <i>conj. et adv. ;</i>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καιγε - καί γε</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Conjonction</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT).\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2535":"<h1>Kain</h1>\n<p>Strong n° 2535 <i>Prononciation [kah'-in]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Caïn (Angl. Cain) = « artisan (littéralement forgeron) », « acquisition »\n<ol><li>le fils aîné d'Adam et Eve, et qui tua son frère, Abel</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Καιν</font> &lt; קין - <font face=\"Georgia\">Κάϊν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Hébreux (1)</li>\n<li>1 Jean (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G2536":"<h1>Kainan</h1>\n<p>Strong n° 2536 <i>Prononciation [kah-ee-nan']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Kaïnam (Angl. Cainan) = « leur forgeron »\n<ol>\n<li>Kénan, le fils de Enosch (<a class=\"ref\" data-r=\"GEN5.9\">Genèse 5.9</a>)</li>\n<li>fils d'Arpacschad et ancêtre de Christ (<a class=\"ref\" data-r=\"LUK3.36\">Luc 3.36</a>)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Καιναμ</font> &lt; קינן - <font face=\"Georgia\">Καϊνάμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G2537":"<h1>kainos</h1>\n<p>Strong n° 2537 <i>Prononciation [kahee-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>nouveau, neuf, récent, qui vient de se produire\n<ol type=\"a\">\n<li>en ce qui concerne la forme\n<ol>\n<li>fait récemment, frais, récent, non usé, non porté</li>\n</ol>\n</li>\n<li>en ce qui concerne la substance\n<ol>\n<li>nouvelle sorte, sans précédent, non commun, inouï, inconnu inattendu, imprévu, différent de ce qui s'était produit jusqu'alors</li>\n</ol>\n</li>\n<li>étrange, extraordinaire</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καινός, ή, όν</b>, nouveau, <i>càd. :</i><br><b>      1</b> qui vient de se produire, récent, neuf, ATT. ; <i>p. opp. à</i> παλαιός, HDT. <i>9, 26 ;</i> καινοὺς λόγους φέρειν, ESCHL. <i>Ch. 659,</i> apporter des nouvelles ; τί δ' ἔστι καινόν ; SOPH. <i>O.C. 722,</i> quoi de nouveau ? ἐκ καινῆς (<i>s.-e</i>. ἀρχῆς) THC. <i>3, 92,</i> de nouveau ; τραγῳδῶν τῇ καινῇ (<i>s.-e</i>. ἡμέρᾳ <i>ou</i> εἰσόδῳ) DÉM. <i>244, 1, ou</i> τραγῳδοῖς καινοῖς, DÉM. <i>243, 17,</i> le jour des tragédies nouvelles ;<br><b>      2</b> différent de ce qui s’était produit jusqu’alors, innové : οὐδὲν καινότερον εἰσέφερε τῶν ἄλλων, XÉN. <i>Mem. 1, 1, 3,</i> il n’a pas introduit plus de nouveau que les autres ; καινὰ πράγματα, PLUT. <i>Cic. 14,</i> affaires nouvelles, changement dans les affaires, révolution (<i>lat</i>. res novæ) ;<br><b>      3</b> <i>p. suite,</i> inattendu, imprévu ; τὸ καινὸν τοῦ πολέμου, THC. <i>3, 30,</i> le tour imprévu que prend une guerre ;<br><b>      4</b> étrange, extraordinaire, SOPH. <i>Ph. 52, etc. ;</i> καινοὶ σοφισταί, PLAT. <i>Euthyd. 271,</i> sophistes étranges ; κ. καὶ ἄτοπα, PLAT. <i>Rsp. 405,</i> choses nouvelles et étranges ; τὸ καινότατον, LUC. <i>Nigr. 21,</i> ce qu’il y a de plus extraordinaire, <i>d’ord. parenth. ;</i><br><b>      5</b> <i>en parl. de pers. :</i> κ. ἄνθρωπος, PLUT. <i>Cato ma. 1,</i> homme nouveau, parvenu (<i>lat</i>. homo novus).<br><span>•<i> Cp</i>. -ότερος, BATR. <i>116 ;</i> XÉN. <i>Mem. 1, 1, 3, etc. ;</i> <i>• Sup</i>. -ότατος, ANT. <i>119, 25 ;</i> LUC. <i>l. c. etc</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *ken-, nouveau, frais ; <i>cf. lat</i>. re-cēns.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καινος - καινός</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – dénote la nouveauté en référence à la qualité, ce qui est frais, non usé\n<br><br> – dénote la nouveauté en référence au temps, ce qui est jeune, récent.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n42 fois dans 36 versets de 14 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (5)</li>\n<li>Luc (5)</li>\n<li>Jean (2)</li>\n<li>Actes (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (3)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (2)</li>\n<li>Hébreux (3)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (2)</li>\n<li>2 Jean (1)</li>\n<li>Apocalypse (9)</li>\n</ul>\n</td></tr>\n</table>","G2538":"<h1>kainotes</h1>\n<p>Strong n° 2538 <i>Prononciation [kahee-not'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>nouveauté\n<ol type=\"a\">\n<li>un nouvel état de vie dans lequel le Saint Esprit nous place comme pour produire un nouvel état, qui est la vie éternelle</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καινότης, ητος (ἡ) :<br>      1</b> nouveauté, fraîcheur, PLUT. <i>Per. 13 ;</i> PHILSTR. <i>922 ;</i><br><b>      2</b> nouveauté, singularité, THC. <i>3, 38 ;</i> ISOCR. <i>208</i> b ; <i>souv. au pl</i>. ISOCR. <i>23</i> a ; DC. <i>44, 3</i>.<br><span><b>Étym</b>. καινός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καινοτης - καινότης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Romains (2)</li>\n</ul>\n</td></tr>\n</table>","G2539":"<h1>kaiper</h1>\n<p>Strong n° 2539 <i>Prononciation [kah'-ee-per]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>bien que</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καί·περ</b>, <i>adv</i>., quoique :<br><b>      1</b> <i>devant un part. ou une construct. supposant un part. :</i> καίπερ πολλὰ παθόντα, OD. <i>7, 224,</i> bien qu’ayant beaucoup souffert (<i>cf</i>. PD. <i>I. 8, 9 ;</i> ESCHL. <i>Pr. 907</i>) ; λέγεις ἀληθῆ, καίπερ ἐκ μακροῦ χρόνου (<i>s.-e</i>. λέγων) SOPH. <i>O.R. 1141,</i> tu dis la vérité, bien que ce que tu dis date de loin ; <i>dans Hom. touj. avec tmèse (sauf l’ex. ci-dessus</i>) : καὶ ἀχνύμενός περ, IL. <i>8, 125,</i> bien qu’affligé (<i>cf</i>. καὶ οὐκ ἀγαθόν περ ἐόντα, IL. <i>9, 627 ; cf</i>. IL. <i>1, 577, etc. ;</i> OD. <i>17, 555 ; de même</i> καὶ θεός περ, ESCHL. <i>Ag. 1176</i>) ;<br><b>      2</b> <i>rar. dev. un mode personn. :</i> καίπερ… ᾤμην, PLAT. <i>Conv. 219</i> c, bien que je pensasse.<br><span><b>Étym</b>. καί, περ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καιπερ - καίπερ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Conjonction</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Philippiens (1)</li>\n<li>Hébreux (3)</li>\n<li>2 Pierre (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2540":"<h1>kairos</h1>\n<p>Strong n° 2540 <i>Prononciation [kahee-ros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mesure</li>\n<li>mesure de temps, plus ou moins grande portion de temps, de là :\n<ol type=\"a\">\n<li>un temps fixé et défini, une époque décisive attendue</li>\n<li>le temps favorable et opportun</li>\n<li>le temps convenable</li>\n<li>une période limitée de temps</li>\n<li>ce que le temps apporte, l'état du temps, les choses et événements dans le temps</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καιρός, οῦ (ὁ) :<br>A</b> mesure convenable, juste mesure, HÉS. <i>O. 692 ;</i> THGN. <i>401 ;</i> ATT. ; μείζων τοῦ καιροῦ γαστήρ, XÉN. <i>Conv. 2, 19,</i> ventre d’une grosseur démesurée ; καιροῦ πέρα, ESCHL. <i>Pr. 507,</i> sans mesure ;<br><b>B</b> <i>p. suite :</i><br><b>   I</b> <i>avec idée de temps :</i><br><b>      1</b> moment convenable <i>ou</i> opportun, temps favorable, occasion, PD. <i>P. 4, 508, etc. ;</i> ATT. (DÉM. <i>32, 25, etc</i>.) ; τινος, HPC. <i>386, 50,</i> pour qqe ch. ; καιρός ἐστι, <i>avec l’inf</i>. HDT. <i>8, 144 ;</i> ESCHL. <i>Pr. 523, etc. ;</i> καιρὸν ἔχει, THC. <i>1, 42,</i> il est temps de, c’est le moment de ; ἐν καιρῷ, ESCHL. <i>Pr. 379 ;</i> SOPH. <i>O.C. 809 ;</i> PLAT. <i>Crit. 44</i> a ; εἰς καιρόν, HDT. <i>4, 139 ; 7, 144 ;</i> EUR. <i>Tr. 739 ;</i> πρὸς καιρόν, SOPH. <i>Aj. 38, O.R. 325, Tr. 59, etc. ;</i> κατὰ καιρόν, HDT. <i>1, 30 ;</i> σὺν καιρῷ, POL. <i>2, 38, 7 ;</i> καιρῷ, SOPH. <i>O.R. 1516,</i> THC. <i>4, 59 ;</i> καιρόν, SOPH. <i>Aj. 34, 1316,</i> en temps utile, au moment opportun, à propos ; ἀπὸ καιροῦ, PLAT. <i>Theæt. 187</i> e ; παρὰ καιρόν, EUR. <i>I.A. 800 ;</i> PLAT. <i>Pol. 277</i> a ; ἄνευ καιροῦ, PLAT. <i>Ep. 339</i> c, à contretemps ; πρὸ καιροῦ, ESCHL. <i>Ag. 367,</i> prématurément : ἐκ τοῦ καιροῦ, POL. <i>6, 32, 3,</i> tout à coup ; ἐπὶ καιροῦ, à propos, DÉM. <i>424, 2, ou</i> tout à coup : ἐπὶ καιροῦ λέγειν, PLUT. <i>Dem. 8,</i> parler d’improvisation ; καιροῦ τυχεῖν, EUR. <i>Hec. 593 ;</i> PLAT. <i>Leg. 687</i> a, rencontrer l’occasion ; καιρὸν λαμϐάνειν, THC. <i>2, 34 ;</i> LYS. <i>130, 18, ou</i> λαϐέσθαι, LUC. <i>Tim. 13 ;</i> καιρῷ χρῆσθαι, PLUT. <i>Pyrrh. 7,</i> saisir l’occasion ; καιρὸν ἁρπάζειν, PLUT. <i>Phil. 15,</i> saisir l’occasion aux cheveux ; καιρὸν παριέναι, THC. <i>4, 27,</i> laisser passer l’occasion ; <i>particul</i>. καιροὶ σωμάτων, ARSTT. <i>Pol. 7, 16, 11,</i> le moment favorable pour le développement du corps, l’âge où le corps est dans sa fraîcheur, dans sa première jeunesse ;<br><b>      2</b> <i>p. ext</i>. opportunité, convenance, <i>en gén., d’où</i> avantage, utilité, ESCHL. <i>Suppl. 1061 ;</i> τι πρὸς καιρόν, SOPH. <i>Tr. 59,</i> qqe ch. d’opportun, d’utile ; πρὸς καιρόν, SOPH. <i>Ph. 1279,</i> utilement ; ἐπὶ σῷ καιρῷ, SOPH. <i>Ph. 151,</i> en vue de ton avantage, dans ton intérêt ; σοὶ ἰὸν πρὸς καιρόν, SOPH. <i>O.R. 324,</i> allant à ton avantage, devant tourner à ton avantage ; τίνος ἕνεκα καιροῦ ; DÉM. <i>681, 21,</i> à quoi bon ? ἐν καιρῷ γίγνεσθαί τινι, XÉN. <i>Cyr. 5, 1, 17,</i> être utile à qqn ;<br><b>      3</b> <i>p. ext</i>. temps, <i>particul</i>. temps où l’on vit, moment présent : ὁ παρὼν καιρός, DÉM. <i>32, 25,</i> le temps présent, l’état actuel des affaires ; <i>en gén</i>. οἱ καιροί, les circonstances, PLAT. <i>Rsp. 374</i> c ; ESCHN. <i>63, 12 ;</i> ἐν τοῖς μεγίστοις καιροῖς, XÉN. <i>Hell. 6, 5, 33,</i> dans les circonstances les plus graves <i>ou</i> critiques ; <i>particul. en mauv. part,</i> ἔσχατος καιρός, POL. <i>29, 11, 12, etc. ;</i> PLUT. <i>Syll. 12,</i> circonstances extrêmes, situation extrême, extrême danger ;<br><b>      4</b> <i>particul</i>. temps particulier, saison : κ. χειμῶνος, PLAT. <i>Leg. 709</i> c, la saison d’hiver ;<br><b>   II</b> <i>avec idée de lieu,</i> endroit convenable (pour qqe ch.) : ἐναυλισάμενοι τῶν χωρίων οὗ καιρὸς εἴη, THC. <i>4, 54,</i> s’étant établis en pleine campagne, là où était une place convenable ; πρὸ καιροῦ βέλος σκήπτειν, ESCHL. <i>Ag. 367,</i> lancer le trait en avant du but (<i>propr</i>. en avant du point précis qui convient), <i>càd</i>. prématurément ; <i>particul. en parl. du corps,</i> point vital, organe essentiel : ἐς καιρὸν τυπείς, EUR. <i>Andr. 1120,</i> frappé au bon endroit, <i>càd</i>. à l’endroit mortel.<br><span><b>Étym</b>. <i>incert</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καιρος - καιρός</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – une portion définie et limitée de temps avec en plus la notion de convenable et favorable\n<br><br> – le temps en général</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n86 fois dans 81 versets de 19 livres bibliques (NT)\n<ul>\n<li>Matthieu (10)</li>\n<li>Marc (5)</li>\n<li>Luc (13)</li>\n<li>Jean (4)</li>\n<li>Actes (9)</li>\n<li>Romains (6)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (3)</li>\n<li>Galates (3)</li>\n<li>Ephésiens (4)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (3)</li>\n<li>2 Timothée (3)</li>\n<li>Tite (1)</li>\n<li>Hébreux (4)</li>\n<li>1 Pierre (4)</li>\n<li>Apocalypse (7)</li>\n</ul>\n</td></tr>\n</table>","G2541":"<h1>Kaisar</h1>\n<p>Strong n° 2541 <i>Prononciation [kah'-ee-sar]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>César (Angl. Caesar) = « séparé », « chef »\n<ol><li>le surnom de Jules César, qui, adopté par Octavius Augustus et ses successeurs devint ensuite un titre, et les empereurs Romains se l'appropriaient comme faisant partie de leur titre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Καῖσαρ, αρος (ὁ)</b> <span>[ᾰρ]</span> = <i>lat</i>. Cæsar, César :<br><b>   I</b> <i>surn. des membres de la gens Julia, à Rome, d’où au plur</i>. οἱ Καίσαρες, PLUT. <i>Per. c. Fab. 3, etc</i>. les Césars ;<br><b>   II</b> <i>particul. :</i><br><b>      1</b> <i>général et dictateur romain,</i> DS. <i>1, 4 ;</i> PLUT. <i>Cæs. etc. ;</i><br><b>      2</b> <i>titre des empereurs romains,</i> DH. <i>1, 21 Reiske ;</i> NT. <i>Matth. 22, 17 ;</i> PLUT. <i>M. 319</i> c, <i>etc. ;</i><br><b>      3</b> <i>titre donné, à partir d’Hadrien, à l’héritier désigné de l’empire,</i> JOS. <i>B.J. 5, 2, 5, etc. ;</i> DC. <i>66, 11, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Καισαρ - Καῖσαρ</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n29 fois dans 23 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (4)</li>\n<li>Luc (7)</li>\n<li>Jean (3)</li>\n<li>Actes (10)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2542":"<h1>Kaisereia</h1>\n<p>Strong n° 2542 <i>Prononciation [kahee-sar'-i-a]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Césarée (Angl. Caesarea) = « appartenant à César »\n<ol>\n<li>Césarée de Philippes était situé au pied du Liban, près des sources du Jourdain; son nom vient de César Tibère</li>\n<li>Césarée de Palestine était près de la Méditerranée, entre Joppé et Dora ; son nom vient de César Auguste. C'était la résidence des procurateurs Romains, la majorité des habitants étaient Grecs</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Καισάρεια, ας (ἡ)</b> <span>[σᾰ]</span> = <i>lat</i>. Cæsarea, Césarée :<br><b>      1</b> <i>v. de Cappadoce (auj</i>. ruines près de Kæsarieh) ANTH. <i>1, 92 ; 8, 2, etc. ;</i><br><b>      2</b> <i>v. de Maurétanie (auj</i>. Cherchell) LUC. <i>H. conscr. 28</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Καισερεια - Καισάρεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n17 fois dans 17 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Actes (15)</li>\n</ul>\n</td></tr>\n</table>","G2543":"<h1>kaitoi</h1>\n<p>Strong n° 2543 <i>Prononciation [kah'-ee-toy]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>et encore, bien que</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καί·τοι</b>, <i>adv. :</i><br><b>      1</b> et certes, et en vérité, IL. <i>13, 267 ;</i><br><b>      2</b> quoi qu’il en soit, cependant, toutefois, ATT. ; <i>d’ord. pour marquer une objection que se fait à lui-même celui qui parle :</i> καίτοι τί φημι ; ESCHL. <i>Pr. 101 ;</i> καίτοι τί φωνῶ ; SOPH. <i>O.C. 1132,</i> mais quoi ! que dis-je ? καίτοι καὶ τοῦτο, DÉM. <i>43, 16, etc</i>. mais quoi ! cela même, <i>etc. ; souv</i>. renforcé par γε : καίτοι γε, AR. <i>Ach. 611 ; d’ord. séparés :</i> καίτοι… γε, ATT. ;<br><b>      3</b> quoique, <i>devant un part</i>. AR. <i>Eccl. 159 ;</i> LUC. <i>Alex. 3 ; renforcé par</i> περ : καίτοι περ, HDT. <i>8, 53</i>.<br><span><b>Étym</b>. καί, τοι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καιτοι - καίτοι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2544":"<h1>kaitoige</h1>\n<p>Strong n° 2544 <i>Prononciation [kah'-ee-toyg-eh]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>et encore, bien que</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καιτοιγε - καίτοιγε</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G2545":"<h1>kaio</h1>\n<p>Strong n° 2545 <i>Prononciation [kah'-yo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre en feu, allumer, brûlant</li>\n<li>brûler, consumer par le feu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καίω</b> <span>(<i>impf</i>. ἔκαιον, <i>att</i>. ἔκαον <span>[ᾱ]</span>, <i>f</i>. καύσω ; <i>ao</i>. ἔκαυσα ; <i>pf. inus. ; pass. f</i>. καυθήσομαι, <i>ao</i>. ἐκαύθην, <i>ao.2</i> ἐκάην, <i>pf</i>. κέκαυμαι, <i>pl.q.pf</i>. ἐκεκαύμην)</span><br><b>      1</b> allumer : πῦρ, IL. <i>15, 97 ;</i> OD. <i>9, 231,</i> du feu ; πυρὰ πολλά, IL. <i>9, 77,</i> des feux nombreux ; σέλας καιομένοιο πυρός, IL. <i>19, 376,</i> la lueur du feu qui brûle ; πυραὶ νεκύων καίοντο, IL. <i>1, 52,</i> les bûchers des morts étaient allumés ; <i>en parl. de météores,</i> ARSTT. <i>Meteor. 1, 4, 1 ;</i><br><b>      2</b> faire brûler, consumer par le feu : ὀστέα, HÉS. <i>Th. 557 ;</i> νεκρούς, IL. <i>21, 343, 357,</i> des ossements, des morts ; <i>en parl. de médecins,</i> HPC. <i>Art. 787, etc. joint à</i> τέμνειν (<i>v. ce mot) ; en parl. de la guerre, joint à</i> τέμνειν, XÉN. <i>Hell. 4, 2, 15 ; à</i> πορθεῖν, XÉN. <i>Hell. 6, 5, 27 ;</i><br><b>      3</b> brûler, <i>en parl. simpl. d’une chaleur extrême, particul. du soleil,</i> HDT. <i>3, 104 ;</i> PLAT. <i>Crat. 413</i> b, <i>etc. ; du froid,</i> XÉN. <i>Cyn. 8, 2 ;</i> ARSTT. <i>Meteor. 4, 5, 5 ; p. ext. de la fièvre,</i> THC. <i>2, 49 ;</i><br><b>      4</b> <i>fig</i>. consumer (d’amour, de colère, <i>etc.) surt. au pass</i>. être brûlé, brûler, AR. <i>Lys. 8 ;</i> PLAT. <i>Leg. 783</i> a, <i>etc. ;</i> τινός, HERMÉS. (ATH. <i>598</i> a) d’amour pour qqn ;<br><b><i>Moy</i>. καίομαι</b> <span>(<i>f</i>. καύσομαι, <i>ao. épq</i>. κηάμην)</span> allumer pour soi : πῦρ, IL. <i>9, 88, etc. ;</i> OD. <i>16, 2,</i> du feu.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att. seul</i>. καίω (<i>non</i> κάω) CIA. <i>1, 9, 17 (464/457 av. J. C) ; v. Meisterh. p. 142, 24. Prés. inf. épq</i>. καιέμεν, IL. <i>14, 397. Fut. rare</i> καύσομαι, AR. <i>Pl. 1054. Ao. épq</i>. ἔκηα, IL. <i>1, 40, etc. ;</i> OD. <i>19, 366 (3 sg</i>. κῆεν, IL. <i>21, 349 ; 3 pl</i>. κεῖαν, A. RH. <i>1, 588), d’où impér</i>. κῆον, OD. <i>21, 176 ; sbj. 1 pl. épq</i>. κήομεν (<i>p</i>. κήωμεν) IL. <i>7, 377, 396 ; opt. 3 sg</i>. κήαι, IL. <i>21, 336 ; 3 pl</i>. κήαιεν, IL. <i>24, 38 ; inf</i>. κῆαι, OD. <i>15, 97 ; part</i>. κήας, OD. <i>9, 231 ; pl</i>. κέαντες, ESCHL. <i>Ag. 840. Pass. prés. impér. 2 sg. épq</i>. καίεο, OD. <i>24, 67 ; ao.2 inf. épq</i>. καήμεναι, IL. <i>23, 210. De cet ao. fut. réc</i>. καήσομαι, SIB. <i>3, 507</i>.<br><span><b>Étym</b>. <i>th</i>. καυ- <i>pour</i> *καϝ-, <i>p.-ê. de la R. indo-europ</i>. *keh₂u-, brûler.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καιω - καίω</font>\n<br><br>apparemment un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (2)</li>\n<li>Jean (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (5)</li>\n</ul>\n</td></tr>\n</table>","G2546":"<h1>kakei</h1>\n<p>Strong n° 2546 <i>Prononciation [kak-i']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>et là</li>\n<li>ici aussi</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κἀκεῖ</b>, <i>crase p</i>.  .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κακει - κἀκεῖ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (2)</li>\n<li>Jean (1)</li>\n<li>Actes (5)</li>\n</ul>\n</td></tr>\n</table>","G2547":"<h1>kakeithen</h1>\n<p>Strong n° 2547 <i>Prononciation [kak-i'-then]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>de lieu\n<ol type=\"a\">\n<li>et de là, depuis, de</li>\n</ol>\n</li>\n<li>de temps\n<ol type=\"a\">\n<li>et ensuite, alors</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κἀκεῖθεν</b>, <i>crase p</i>.  .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κακειθεν - κἀκεῖθεν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Actes (8)</li>\n</ul>\n</td></tr>\n</table>","G2548":"<h1>kakeinos</h1>\n<p>Strong n° 2548 <i>Prononciation [kak-i'-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>et lui, lui aussi</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κἀκεῖνος</b>, <i>crase p</i>.  .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κακεινος - κἀκεῖνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Conjonction</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n23 fois dans 23 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (4)</li>\n<li>Luc (4)</li>\n<li>Jean (6)</li>\n<li>Actes (3)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2549":"<h1>kakia</h1>\n<p>Strong n° 2549 <i>Prononciation [kak-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>malignité, malice, mauvais vouloir, désir de nuire à</li>\n<li>méchanceté, dépravation\n<ol type=\"a\">\n<li>méchanceté qui n'a pas honte d'enfreindre la loi</li>\n</ol>\n</li>\n<li>mal, malheur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κακία, ας (ἡ)</b> <span>[ᾰᾱ]</span><br><b>   I</b> <i>act. propr</i>. nature mauvaise, <i>d’où particul. :</i><br><b>      1</b> disposition au mal, disposition vicieuse, vice, <i>p. opp. à</i> ἀρετή, THGN. <i>322 ;</i> SOPH. <i>O.R. 512 ;</i> le Vice <i>personnifié,</i> XÉN. <i>Mem. 2, 1, 26 ;</i> PLAT. <i>Rsp. 348</i> c, <i>etc. ; t. de phil</i>. le mal en soi, PLOT. <i>Enn. 1, 157 ; au pl</i>. défauts, vices, LUC. <i>H. conscr. 6 ;</i><br><b>      2</b> lâcheté, THC. <i>2, 87 ; joint à</i> ἀνανδρία, PLAT. <i>Crit. 45</i> a ;<br><b>      3</b> déshonneur, infamie, THC. <i>3, 58 ;</i><br><b>      4</b> insuffisance, incapacité, PLAT. <i>Phædr. 248</i> b ;<br><b>   II</b> <i>pass</i>. mal souffert, souffrance, affliction, SPT. <i>1Reg. 6, 9 ; Amos 3, 6 ;</i> NT. <i>Matth. 6, 34 ;</i> CHRYS. <i>7, 279 Migne</i>.<br><span><b>Étym</b>. κακός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κακια - κακία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>Tite (1)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G2550":"<h1>kakoetheia</h1>\n<p>Strong n° 2550 <i>Prononciation [kak-o-ay'-thi-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mauvais caractère, dépravation du cœur et de la vie</li>\n<li>subtilité maligne, astuce malicieuse</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κακοήθεια, ας (ἡ)</b> <span>[κᾰ]</span><br><b>      1</b> mauvaise habitude, XÉN. <i>Cyn. 13, 16 ;</i><br><b>      2</b> mauvais caractère, méchanceté, PLAT. <i>Rsp. 348</i> d ; ARSTT. <i>Rhet. 2, 13, 3, etc. ; au plur</i>. ESCHN. <i>23, 43 ;</i><br><b>      3</b> caractère mauvais (d’un mal) <i>c</i>. καχεξία, DIOSC. <i>3, 106</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -ηθίη, DÉMOCR. (STOB. <i>Fl. 10, 68</i>).<br><span><b>Étym</b>. κακοήθης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κακοητεια - κακοήθεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G2551":"<h1>kakologeo</h1>\n<p>Strong n° 2551 <i>Prononciation [kak-ol-og-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>parler mal de, insulter, injurier</li>\n<li>maudire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κακολογέω-ῶ</b> <span>[ᾰ]</span><br><b>      1</b> injurier, dire du mal de, <i>acc</i>. LYS. <i>112, 36 ;</i> HYPÉR. <i>102, 13 Bekker ;</i><br><b>      2</b> maudire, <i>acc</i>. SPT. <i>Ex. 21</i>.<br><span><b>Étym</b>. κακολόγος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κακολογεω - κακολογέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2552":"<h1>kakopatheia</h1>\n<p>Strong n° 2552 <i>Prononciation [kak-op-ath'-i-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>la souffrance du mal, c.à.d malheur, détresse, affliction</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κακοπάθεια</b>, <i>v</i>. κακοπαθία.<br><br>\n<b>κακοπαθία</b>, <i>mieux que</i> <b>κακοπάθεια, ας (ἡ)</b> <span>[ᾰᾰθ]</span> mauvais traitement, souffrance, vexation, ISOCR. <i>127</i> c ; ANT. <i>122, 19, etc. ;</i> POL. <i>2, 25, 10, etc. ; au pl</i>. THC. <i>7, 77</i>.<br><span><b><span class=\"arrow\"></span></b> κακοπαθία <i>dans une inscr. att</i>. CIA. <i>2, 341, 16 (envir. 270/265 av. J.C.) ; v. Meisterh. p. 42, note 356</i>.<br><span><b>Étym</b>. κακοπαθής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κακοπαθεια - κακοπάθεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2553":"<h1>kakopatheo</h1>\n<p>Strong n° 2553 <i>Prononciation [kak-op-ath-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>souffrir (endurer) des maux (malheurs, difficultés)</li>\n<li>être affligé</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κακοπαθέω-ῶ</b> <span>[ᾰᾰ]</span> être dans une mauvaise situation, être réduit aux extrémités, HDN <i>8, 7, 14 ;</i> ὑπό τινος, THC. <i>2, 41,</i> par qqn ; τινι, THC. <i>4, 29 ;</i> ὑπό τινος, POL. <i>3, 72, 5,</i> par suite de qqe ch. ; κ. σώματι, ANT. <i>129, 31, etc. ;</i> ISOCR. <i>24</i> a, souffrir de son corps.<br><span><b><span class=\"arrow\"></span></b> <i>Pf</i>. κεκακοπάθηκα, EN. TACT. <i>Pol. 26, 4</i>.<br><span><b>Étym</b>. κακοπαθής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κακοπαθεω - κακοπαθέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Timothée (3)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2554":"<h1>kakopoieo</h1>\n<p>Strong n° 2554 <i>Prononciation [kak-op-oy-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire le mal</li>\n<li>faire mal, faire faux</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κακοποιέω-ῶ</b> <span>[ᾰ]</span><br><b>      1</b> mal agir, agir en malhonnête homme, ESCHL. <i>102, 14 Bekker ;</i> AR. <i>Pax 731 ;</i><br><b>      2</b> mal gérer ses affaires, XÉN. <i>Œc. 3, 11 ;</i><br><b>      3</b> faire du mal, nuire à, <i>acc</i>. χώραν, XÉN. <i>Mem. 3, 5, 26,</i> commettre des dégâts <i>ou</i> des rapines dans un pays ; νῆας, POL. <i>13, 4, 1,</i> endommager des vaisseaux.<br><span><b>Étym</b>. κακοποιός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κακοποιεω - κακοποιέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>1 Pierre (1)</li>\n<li>3 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G2555":"<h1>kakopoios</h1>\n<p>Strong n° 2555 <i>Prononciation [kak-op-oy-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>celui qui fait le mal, malfaiteur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κακο·ποιός, ός, όν</b> <span>[ᾰ]</span> malfaisant, ARSTT. <i>Nic. 4, 3 ;</i> POL. <i>15, 25, 1 ;</i> SPT. <i>Prov. 12, 4 ; en parl. de choses (injure,</i> PD. <i>N. 8, 56 ; suc d’une plante,</i> TH. <i>C.P. 2, 6, 4, etc</i>.).<br><span><b>Étym</b>. κ. ποιέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κακοποιος - κακοποιός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>1 Pierre (4)</li>\n</ul>\n</td></tr>\n</table>","G2556":"<h1>kakos</h1>\n<p>Strong n° 2556 <i>Prononciation [kak-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>d'une nature mauvaise\n<ol type=\"a\">\n<li>non comme il devrait être</li>\n</ol>\n</li>\n<li>d'un mode de pensée, de sentiment, d'action\n<ol type=\"a\">\n<li>bas, faux, méchant</li>\n</ol>\n</li>\n<li>gênant, injurieux, pernicieux, destructif</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κακός, ή, όν</b> <span>[ᾰ]</span> mauvais, <i>càd. :</i><br><b>   I</b> <i>en parl. des qualités matérielles ou de l’intelligence, particul. :</i><br><b>      1</b> laid : κ. εἶδος, IL. <i>10, 316,</i> aspect difforme ;<br><b>      2</b> sordide : κ. εἷμα, OD. <i>11, 191 ; 14, 506,</i> vêtement malpropre, en mauvais état ;<br><b>      3</b> qui n’a pas les qualités propres à telle <i>ou</i> telle chose, défectueux : κ. ἡνίοχος, IL. <i>17, 487,</i> mauvais cocher ; κυϐερνήτης, EUR. <i>Suppl. 880,</i> mauvais pilote ; ἰατρός, ESCHL. <i>Pr. 473,</i> médecin inhabile, mauvais médecin ; μάγειρος, PLAT. <i>Phædr. 265</i> e, mauvais cuisinier ; κακὸς γνώμην, SOPH. <i>Ph. 910,</i> faible d’esprit, irrésolu ; <i>avec un inf</i>. inhabile à, SOPH. <i>O.R. 545 ;</i> EUR. <i>Med. 264, etc. ;</i><br><b>      4</b> lâche, IL. <i>6, 488 ; 13, 278, etc. ;</i> PLAT. <i>Ap. 28</i> c ; <i>joint à</i> ἄναλκις, IL. <i>8, 153 ;</i> OD. <i>3, 375 ; à</i> ἄθυμος, HDT. <i>7, 11 ; p. opp. à</i> θρασύς, SOPH. <i>Ph. 1307 ;</i><br><b>      5</b> de basse origine, OD. <i>6, 187 ;</i><br><b>   II</b> <i>au mor</i>. méchant, OD. <i>11, 383 ;</i> HÉS. <i>O. 238 ; p. opp. à</i> ἀγαθός, HÉS. <i>O. 344 ; à</i> ἔννομος, ESCHL. <i>Suppl. 404 ; à</i> χρηστός, SOPH. <i>Ant. 520 ; joint à</i> πονηρός, PLUT. <i>M. 653</i> d ; οἱ κακοί, ATT. (SOPH. <i>Ant. 208, etc</i>.) les méchants ; ὦ κάκιστε, SOPH. <i>O.R. 334, etc</i>. scélérat ! κακὸς πρός τινα, THC. <i>1, 86,</i> malveillant pour qqn ; <i>p. suite,</i> funeste : κακὴ τύχη, SOPH. <i>Tr. 323,</i> sort malheureux ; <i>en parl. de mots, de paroles :</i> κακοὶ λόγοι, SOPH. <i>Ant. 259,</i> paroles mauvaises, malveillantes ; πολλά τε καὶ κακὰ λέγειν, HDT. <i>8, 61,</i> faire beaucoup de reproches ; <i>subst</i>. τὸ κακόν, mal, malheur : κακὸν ἔρδειν <i>ou</i> ῥέζειν τινά, IL. <i>2, 195 ; 3, 351, ou</i> τινί, OD. <i>14, 289 ;</i> κακόν τι ποιεῖν τινα, ATT. faire du mal à qqn ; κακὰ φέρειν τινί, IL. <i>2, 304 ou</i> τεύχειν, HÉS. <i>O. 263,</i> causer du mal à qqn ; κακὸν πάσχειν ὑπό τινος, ATT. souffrir du mal de qqn ; κακὰ κακῶν, SOPH. <i>O.C. 1238,</i> les derniers des maux ; δεινὰ πρὸς κακοῖς κακά, SOPH. <i>O.C. 595,</i> maux sur maux<br><i>Cp. poét</i>. κακώτερος, OD. <i>6, 275 ; 15, 343 ; 21, 324 ;</i> A. RH. <i>3, 421 ;</i> THCR. <i>27, 21 ; réc. en prose,</i> ALCIPHR. <i>3, 62 ; d’ord</i>. κακίων <span>[ῐ <i>épq.,</i> ῑ <i>att</i>.]</span> OD. <i>2, 277, etc. ;</i> HDT. <i>7, 104 ;</i> ATT. ; <i>postér</i>. κακιότερος <span>[ῑ]</span> ANTH. <i>12, 7</i>. <i>• Sup</i>. κάκιστος, IL. <i>16, 570 ;</i> OD. <i>1, 391, etc. ;</i> SOPH. <i>O.R. 334, O.C. 744, Ph. 384, etc. ; on emploie également pour cp</i>. χείρων <i>ou</i> ἥσσων, <i>et pour</i> <i>• Sup</i>. χείριστος <i>ou</i> ἥκιστος.<br><span><b>Étym</b>. <i>p.-ê. indo-europ</i>. *knḱ-, minime, faible ; <i>autrement pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κακος - κακός</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n51 fois dans 46 versets de 19 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n<li>Actes (4)</li>\n<li>Romains (16)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (2)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (5)</li>\n<li>3 Jean (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2557":"<h1>kakourgos</h1>\n<p>Strong n° 2557 <i>Prononciation [kak-oor'-gos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un malfaiteur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κακοῦργος, ος, ον</b> <span>[ᾰ]</span> qui fait le mal, <i>d’où :</i><br><b>      1</b> <i>abs</i>. pervers, malfaisant, <i>en parl. de pers</i>. HDT. <i>1, 41 ;</i> SOPH. <i>Aj. 1043, etc. ;</i> PLAT. <i>Gorg. 465</i> b ; <i>ou de choses</i> (désir, gourmandise, parole, <i>etc</i>.) PLAT. <i>Rsp. 554</i> c ; DÉM. <i>494, 26 ; subst</i>. (ὁ, ἡ) malfaiteur (voleur, meurtrier, <i>etc</i>.) THC. <i>1, 134 ;</i> ANT. <i>115, 19, etc. ;</i> HDN <i>7, 12, 15 ;</i><br><b>      2</b> <i>avec un rég</i>. qui fait du tort à, qui cause un dommage à, nuisible à, <i>gén</i>. XÉN. <i>Mem. 1, 5, 3</i>.<br><span>•<i> Cp</i>. -ότερος, XÉN. <i>l. c. ;</i> <i>• Sup</i>. -ότατος, PLAT. <i>1 Alc. 118</i> a ; DÉM. <i>494, 26</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Poét</i>. κακοεργός, OD. <i>18, 54,</i> THCR. <i>15, 47, etc</i>.<br><span><b>Étym</b>. <i>contr. p</i>. κακοεργός, <i>de</i> κ. ἔργον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κακουργος - κακοῦργος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2558":"<h1>kakoucheo</h1>\n<p>Strong n° 2558 <i>Prononciation [kak-oo-kheh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>traiter mal, opprimer, tourmenter</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κακουχέω-ῶ</b> <span>[ᾰ]</span> maltraiter, tourmenter, <i>acc</i>. TÉLÈS (STOB. <i>Fl. 97, 31), d’où au pass</i>. être tourmenté, DS. <i>3, 23 ; 19, 11 ;</i> PLUT. <i>M. 114</i> e ; DC. <i>35, 9</i>.<br><span><b>Étym</b>. κ. ἔχω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κακουχεω - κακουχέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G2559":"<h1>kakoo</h1>\n<p>Strong n° 2559 <i>Prononciation [kak-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>opprimer, affliger, faire du mal, maltraiter</li>\n<li>aigrir, envenimer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κακόω-ῶ</b> <span>(<i>ao</i>. ἐκάκωσα)</span> <span>[ᾰ]</span> mettre en mauvais état, <i>càd. :</i><br><b>      1</b> maltraiter, <i>acc</i>. IL. <i>11, 690 ;</i> OD. <i>16, 212, etc</i>. ATT. ;<br><b>      2</b> endommager, <i>en parl. de pers. au pass. :</i> κεκακωμένος ἅλμῃ), OD. <i>6, 137,</i> abîmé par l’eau de mer ; κακοῦσθαι ὑπὸ τῆς πορείας, XÉN. <i>An. 4, 5, 35,</i> être fatigué <i>ou</i> meurtri par la marche ; κακοῦσθαι ἐκ πυρετοῖο, ANTH. <i>11, 382,</i> être en mauvais état par suite de la fièvre ; <i>fig</i>. mettre dans une situation pénible, rendre malheureux, ESCHL. <i>Pr. 976 ;</i> SOPH. <i>O.C. 261 ; en parl. de choses :</i> δένδρα κακούμενα, TH. <i>C.P. 2, 11, 2,</i> arbres qui souffrent des intempéries ; κακοῦν τὰ κοινά, HDT. <i>3, 87,</i> compromettre les affaires ; τὸ ναυτικόν, THC. <i>8, 78,</i> endommager <i>ou</i> perdre la flotte ;<br><b>      3</b> <i>au pass. en parl. de maladies,</i> κακοῦσθαι, devenir pire, s’aggraver, HPC. <i>Mochl. 853, etc</i>.<br><span><b>Étym</b>. κακός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κακοω - κακόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (5)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2560":"<h1>kakos</h1>\n<p>Strong n° 2560 <i>Prononciation [kak-oce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>misérable, être malade</li>\n<li>improprement, faussement</li>\n<li>parler mal de, insulter</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κακῶς</b> <span>[ᾰ]</span> <i>adv</i>., mal, <i>càd. :</i><br><b>      1</b> d’une manière défectueuse : κ. εἰδέναι, XÉN. <i>Cyr. 2, 3, 13,</i> savoir d’une manière insuffisante, ne savoir pas ; <i>d’où</i> avec peine, à peine, DÉM. <i>556, 1, ou</i> sans raison, à tort, EUR. <i>Hec. 326 ;</i><br><b>      2</b> d’une manière déshonorante : κ. ἀκούειν, ATT. entendre mal parler de soi, avoir mauvaise réputation (<i>v</i>. ἀκούω) ;<br><b>      3</b> méchamment : κ. λέγειν τινά, PLAT. <i>Euthyd. 284</i> e, dire du mal de qqn ; κ. ποιεῖν τινα, PLAT. <i>Rsp. 334</i> b, <i>ou</i> κ. δρᾶν τινα, ESCHL. <i>Pers. 813 ;</i> SOPH. <i>Aj. 1154,</i> faire du mal à qqn ;<br><b>      4</b> misérablement, d’une manière dommageable, <i>p. opp. à</i> εὖ, IL. <i>2, 253, etc. ;</i> κ. πάσχειν, ESCHL. <i>Pr. 759 ;</i> SOPH. <i>El. 770,</i> éprouver du mal ; κ. πράττειν, ESCHL. <i>Pr. 264 ;</i> SOPH. <i>El. 1003 ;</i> PLAT. <i>Gorg. 507</i> c, <i>etc</i>. être malheureux ; <i>souv. joint chez les Att. à l’adj. placé d’ord. avant :</i> ἀπό σ' ὀλῶ κακὸν κακῶς, AR. <i>Pl. 65,</i> misérable que tu es, je te ferai périr misérablement ; κακὸς κακῶς ἀπόλοιο, PLUT. <i>M. 760</i> c, misérable, puisses-tu périr misérablement ! <i>cf</i>. SOPH. <i>O.R. 248 ;</i> LYNC. (ATH. <i>150</i> c, <i>etc.) ; rar. après :</i> κακῶς κακὴ θανεῖται, EUR. <i>Tr. 1055,</i> misérable, elle mourra misérablement ; <i>cf</i>. SOPH. <i>Ph. 1369 ;</i> EUR. <i>Cycl. 267, etc. ;</i><br><b>      5</b> d’une manière déshonnête : κ. ἰδεῖν γυναῖκα, PHILSTR. <i>Im. p. 888,</i> regarder une femme avec des yeux déshonnêtes.<br><span>•<i> Cp</i>. κάκιον, SOPH. <i>O.R. 428, etc. ;</i> PLAT. <i>Pol. 291</i> d, <i>etc.</i> <i>• Sup</i>. κάκιστα, HDT. <i>2, 181 ;</i> SOPH. <i>Ant. 59, etc. ; on emploie aussi le cp</i>. χεῖρον.<br><span><b>Étym</b>. κακός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κακως - κακῶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 16 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (4)</li>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2561":"<h1>kakosis</h1>\n<p>Strong n° 2561 <i>Prononciation [kak'-o-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>mauvais traitement, affliction</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κάκωσις, εως (ἡ)</b> <span>[ᾰ]</span><br><b>   I</b> <i>act. :</i><br><b>      1</b> action de maltraiter, XÉN. <i>An. 4, 6, 3 ; particul</i>. action de fatiguer, de harasser, THC. <i>7, 4 ;</i><br><b>      2</b> <i>t. de droit att</i>. κακώσεως δίκη, procès, poursuites pour mauvais traitement <i>ou</i> négligence envers des parents, ORAT. (HARP.) ; pour mauvais traitement à l’égard d’une épouse, DÉM. <i>1332, 13 ; etc. ;</i><br><b>      3</b> <i>à Rome,</i> malversation : κακώσεως κρίνειν, PLUT. <i>Cæs. 4,</i> accuser de concussion (<i>lat</i>. actio repetundarum) ;<br><b>   II</b> <i>pass. :</i><br><b>      1</b> action de se détériorer, corruption, HPC. <i>V. med. 15 ;</i> σαρκός, T. LOCR. <i>102</i> c, de la chair ;<br><b>      2</b> mauvaise fortune, THC. <i>2, 43</i>.<br><span><b>Étym</b>. κακόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κακωσις - κάκωσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2562":"<h1>kalame</h1>\n<p>Strong n° 2562 <i>Prononciation [kal-am'-ay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une tige de paille ou un roseau, chaume\n<ol type=\"a\">\n<li>la paille qui reste après que les épis sont coupés</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καλάμη, ης (ἡ)</b> <span>[ᾰᾰ]</span><br><b>   I</b> chaume, paille, <i>d’où particul. :</i><br><b>      1</b> tige de blé, de roseau, IL. <i>19, 222 ;</i> CALL. <i>Del. 283, Cer. 20 ;</i> DH. <i>5, 13, etc. ;</i><br><b>      2</b> chaume qui reste après la moisson, <i>p. opp. à</i> θέρος, ARSTT. <i>Meteor. 1, 4, 5 ;</i> ANTH. <i>11, 36 ; prov</i>. <span>ἐπὶ καλάμῃ ἀροῦ</span>ν, LYS. (SUID. <i>v°</i> ἐπὶ καλάμῃ) labourer la moisson à peine faite (au risque d’épuiser la terre) ; <i>fig. càd</i>. herbe desséchée, restes flétris ; <i>en parl. de la vieillesse,</i> ARSTT. <i>Rhet. 3, 10, 2 ;</i> καλάμην γέ σ' ὀΐομαι εἰσορόωντα γιγνώσκειν, OD. <i>14, 214,</i> je pense qu’en voyant le chaume tu peux te représenter (ce qu’a été l’épi), <i>càd</i>. en me voyant vieillard, te représenter (ce que j’ai été jeune) ; Ῥήσου κ. ORACL. (POLYEN <i>6, 53</i>) les restes de Rhésus ; ἀπὸ τῆς καλάμης τεκμαίρεσθαι, LUC. <i>Alex. 5,</i> juger d’après les restes ;<br><b>   II</b> <i>c</i>. λινοκαλάμη, roseau, HLD. <i>8, 9 ;</i><br><b>   III</b> <i>c</i>. κάλαμος, CALL. <i>fr. 265</i>.<br><span><b>Étym</b>. <i>cf</i>. κάλαμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καλμη - καλάμη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2563":"<h1>kalamos</h1>\n<p>Strong n° 2563 <i>Prononciation [kal'-am-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un roseau</li>\n<li>un bâton fait d'un roseau, une verge de roseau</li>\n<li>un roseau à mesurer, ou canne</li>\n<li>un roseau pour écrire, une plume</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κάλαμος, ου (ὁ)</b> <span>[ᾰᾰ]</span><br><b>   I</b> roseau, HDT. <i>3, 99 ;</i> PLUT. <i>Lyc. 16, etc. ; d’où</i> objets divers fabriqués avec des roseaux :<br><b>      1</b> chalumeau, pipeau, EUR. <i>I.T. 1126, El. 702 ;</i> TH. <i>H.P. 4, 11 ;</i><br><b>      2</b> roseau pour écrire, THÉM. <i>Or. 15, p. 190 ;</i><br><b>      3</b> baguette transversale <i>d’où partent les cordes de la lyre,</i> SOPH. <i>fr. 34 ;</i><br><b>      4</b> canne à pêche, THCR. <i>21, 43 ;</i> LUC. <i>D. mort. 27, 9 ;</i><br><b>      5</b> flèche, TH. <i>H.P. 4, 11, 11 ;</i> GEOP. <i>2, 6, 23 ;</i><br><b>      6</b> sonde de chirurgien, THÉOPHAN. <i>Nonn. p. 160 ;</i><br><b>      7</b> mesure de 6 coudées ²⁄₃, HÉRON (<i>Anal. Benedict. p. 314</i>) ;<br><b>      8</b> épingle à cheveux, SYN. <i>65</i> a, <i>66</i> b ;<br><b>      9</b> bordure d’une robe de femme, ANTH. <i>6, 292</i> :<br><b>      10</b> <i>collect</i>. natte de jonc, PLAT. <i>Rsp. 372</i> b ;<br><b>   II</b> chaume, paille, XÉN. <i>An. 4, 5, 26 ; Œc. 18, 2 ; n. génér. de plantes qui ne sont ni arbrisseaux</i> (ὕλη) <i>ni arbres</i> (δένδρον) XÉN. <i>An. 1, 5, 1</i>.<br><span><b><span class=\"arrow\"></span></b> ἡ κάλαμος, ES. <i>23 Rochefort</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *ḱolh₂-m-, *ḱlh₂-em-, roseau, paille ; <i>cf. lat</i>. culmus, <i>all</i>. Halm ; <i>lat</i>. calamus <i>est un emprunt</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καλαμος - κάλαμος</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>3 Jean (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G2564":"<h1>kaleo</h1>\n<p>Strong n° 2564 <i>Prononciation [kal-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>appeler\n<ol type=\"a\">\n<li>appeler à haute voix, prononcer à voix haute</li>\n<li>inviter</li>\n</ol>\n</li>\n<li>appeler c.à.d nommer, par le nom\n<ol type=\"a\">\n<li>donner un nom à\n<ol>\n<li>recevoir le nom de, recevoir comme un nom</li>\n<li>donner un nom à quelqu'un, appeler son nom</li>\n</ol>\n</li>\n<li>être appelé c.à.d porter un nom ou un titre (parmi les hommes)</li>\n<li>saluer quelqu'un par son nom</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καλέω-ῶ</b> <span>(<i>f</i>. καλέσω, <i>att</i>. καλῶ, <i>ao</i>. ἐκάλεσα, <i>pf</i>. κέκληκα ; <i>pass. f</i>. κληθήσομαι, <i>ao</i>. ἐκλήθην, <i>pf</i>. κέκλημαι)</span> <span>[ᾰ]</span><br><b>   I</b> appeler, <i>d’où :</i><br><b>      1</b> appeler à soi : τινα εἰς ἕ, IL. <i>23, 203 ;</i> OD. <i>17, 330, etc</i>. qqn à soi ; ἐς Ὄλυμπον, IL. <i>1, 402,</i> dans l’Olympe ; εἰς μαρτυρίαν, PLAT. <i>Leg. 937</i> a, appeler en témoignage ; <i>particul</i>. convoquer : εἰς ἀγορήν, OD. <i>1, 90, ou</i> ἀγορήνδε, IL. <i>20, 24,</i> appeler à une assemblée ; <i>avec un acc. :</i> ὅσοι κεκλήατο (<i>épq. p</i>. -ηντο) βουλήν, IL. <i>10, 195,</i> tous ceux qui avaient été convoqués à l’assemblée, <i>abs</i>. OD. <i>10, 231 ; 17, 382, etc. ;</i><br><b>      2</b> convier à un repas, inviter : τινα ἐπὶ δεῖπνον, XÉN. <i>Mem. 2, 3, 11 ; ou abs</i>. καλεῖν, OD. <i>11, 186 ; 17, 387,</i> inviter à un repas ; κ. ἐς θοίνην, EUR. <i>Ion 1140,</i> inviter à un festin ; καλεῖσθαι πρός τινα, DÉM. <i>402, 15,</i> être invité chez qqn ; <i>abs</i>. ὁ κεκλημένος, DAMOX. (ATH. <i>102</i> d) l’invité, l’hôte ;<br><b>      3</b> citer en justice, <i>en parl. du juge (pour le plaignant, on emploie le moy., v. ci-dessous</i>) : κ. εἰς δικαστήριον, DÉM. <i>1174, 4, etc. ou abs</i>. καλεῖν, AR. <i>Vesp. 1418 ;</i> DÉM. <i>407, 5,</i> citer devant le tribunal ; κ. δίκην, AR. <i>Vesp. 1441,</i> appeler une cause pour la juger ; <i>au pass</i>. être appelé, <i>en parl. d’une affaire à juger,</i> SOPH. <i>fr. 624 ;</i> AR. <i>Nub. 780 ;</i> καλουμένης τῆς γραφῆς, DÉM. <i>1336, 10,</i> l’affaire étant appelée ;<br><b>      4</b> invoquer : θεούς, ESCHL. <i>Suppl. 873 ;</i> SOPH. <i>Tr. 1248, etc</i>. les dieux ;<br><b>      5</b> appeler, demander, réclamer : ἡ ἡμέρα ἐκείνη εὔνουν ἄνδρα ἐκάλει, DÉM. <i>285, 21,</i> ce jour-là demandait un homme de bon vouloir ;<br><b>   II</b> appeler d’un nom, <i>d’où :</i><br><b>      1</b> nommer : ὃν Βριάρεων καλέουσι θεοί, IL. <i>1, 403,</i> celui que les dieux appellent Briarée ; ὄνομά τι κ. τινα, OD. <i>8, 550 ;</i> EUR. <i>Ion 258 ;</i> PLAT. <i>Crat. 483</i> b ; κ. ὄνομά τινι, EUR. <i>Hec. 1271 ;</i> PLAT. <i>Pol. 279</i> e ; <i>ou</i> ἐπί τινι, PLAT. <i>Parm. 147</i> d, <i>etc</i>. donner un nom à qqn <i>ou</i> à qqe ch. ; <i>ou sans</i> ὄνομα : τοῦτο γὰρ αὐτὸν <i>ou</i> αὐτὴν ἐκάλουν, EL. <i>V.H. 14, 31 ;</i> CALL. (SUID. <i>v°</i> κωμῆται) car c’est ainsi qu’ils l’appelaient ; <i>cf</i>. ESCHL. <i>Ag. 1232 ;</i> καλεῖν ὀνόματι, NT. <i>Luc. 19, 2,</i> appeler de son nom ; <i>au pass</i>. Μυρμιδόνες δὲ καλεῦντο, IL. <i>2, 684,</i> on les appelait Myrmidons ; <i>avec le gén. ou le dat. :</i> κεκλῆσθαί τινος, PD. <i>P. 3, 119 ;</i> SOPH. <i>Ant. 366 ; ou</i> τινι, PD. <i>O. 7, 140,</i> être appelé d’après le nom de qqn ; <i>avec une prop. inf. :</i> ἐκάλεσσέ μιν ἰσώνυμον ἔμμεν, PD. <i>O. 9, 96,</i> il disait que son nom serait le même ; τὰς ἀμπέλους τραγᾶν καλοῦσιν, ARSTT. <i>H.A. 5, 14, 18</i> (de là) τραγᾶν appliqué à la vigne qui pousse en feuilles ; ὁ καλούμενος, ἡ καλούμενη, <i>avec un nom,</i> celui, celle qu’on appelle ; ὁ καλούμενος θάνατος, PLAT. <i>Phæd. 86</i> d, ce qu’on appelle la mort ; ἡ Θεράπνη καλευμένη (<i>ion</i>.) HDT. <i>6, 61,</i> la ville qu’on appelle Thérapnè ; <i>particul. au pf. pass</i>. κέκλημαι, j’ai reçu le nom de : σὴ παράκοιτις κέκλημαι, IL. <i>4, 61,</i> je m’appelle ton épouse ; αἲ γὰρ ἐμοὶ τοιόσδε πόσις κεκλημένος εἴη, OD. <i>6, 244,</i> plût aux dieux qu’un tel homme fût appelé mon époux ; <i>en ce sens</i> κέκλημαι <i>devient presque le syn. de</i> εἰμί, IL. <i>3, 138 ;</i> HH. <i>Ap. 324 ;</i> HÉS. <i>Th. 410 ;</i> ESCHL. <i>Pers. 2 ;</i> SOPH. <i>El. 230, etc. ;</i><br><b>      2</b> faire l’appel de, <i>d’où</i> classer <i>ou</i> compter parmi (<i>cf. le sens primit. du lat</i>. classis, <i>de la</i> R. clā- = căl, καλ, <i>v</i>. κάλεσις) : οἱ τῶν ὁμοτίμων καλούμενοι, XÉN. <i>Cyr. 2, 1, 9,</i> ceux qui sont au nombre des ὁμότιμοι ;<br><b><i>Moy</i>. καλέομαι-οῦμαι</b> <span>(<i>f</i>. καλέσομαι, <i>att</i>. καλοῦμαι, <i>ao</i>. ἐκαλεσάμην)</span> appeler à soi : τινα, IL. <i>1, 270 ;</i> OD. <i>8, 43, etc</i>. qqn ; <i>particul. :</i><br><b>      1</b> convoquer : ἀγορήνδε λαόν, IL. <i>1, 54,</i> le peuple à l’assemblée ;<br><b>      2</b> citer en justice, <i>en parl. du plaignant (v. l’act. en parl. du juge</i>) AR. <i>Nub. 1221, etc. ;</i> κ. τινα ὕϐρεως, AR. <i>Av. 1046,</i> assigner qqn pour insulte ; κ. τινα πρὸς τὴν ἀρχήν, PLAT. <i>Leg. 914,</i> assigner qqn devant le magistrat ;<br><b>      3</b> invoquer, <i>en mauv. part :</i> ἀράς τινι, SOPH. <i>O.C. 1385,</i> prononcer des imprécations sur qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. ind. 1 pl. dor</i>. καλέομες, EPICH. <i>fr. 51 Ahrens ; 3 pl. dor</i>. καλέοισι, PD. <i>N. 9, 41 ; inf. épq</i>. καλήμεναι, IL. <i>10, 125, part. épq. pl</i>. καλεῦντες, OD. <i>10, 255. Impf. itér</i>. καλέεσκον, IL. <i>9, 562 ;</i> HÉS. <i>Th. 207, ou</i> κάλεσκον, A. RH. <i>4, 1514. Dans les inscr. att. fut</i>. καλῶ <i>j. au 3<sup>e</sup> siècle av. J.C. ; à partir du 2<sup>e</sup> siècle apparaît dans les composés la forme en</i> σ, καλέσω (<i>v. Meisterh. p. 143, 4). Ao. épq</i>. ἐκάλεσσα, OD. <i>17, 379 ;</i> PD. <i>O. 6, 58, ou</i> κάλεσσα, IL. <i>16, 693. Ao. réc</i>. ἐκάλησα, Ps.-CALLISTH. <i>3, 35. — Pass. Impf. itér. 3 sg</i>. καλέσκετο, IL. <i>15, 338. Pf. 3 pl. épq</i>. κεκλήαται, A. RH. <i>1, 1128 ; ion</i>. κεκλέαται, HDT. <i>2, 164. Opt. 2 sg. poét</i>. κεκλῇο, SOPH. <i>Ph. 119. Pl.q.pf. 3 pl. ion</i>. κεκλήατο, IL. <i>10, 195. — Moy. fut. au sens pass. 2 sg</i>. καλεῖ, SOPH. <i>El. 971 ; fut. poét</i>. καλέσσομαι, NONN. <i>D. 2, 235. Ao. poét</i>. ἐκαλεσσάμην, IL. <i>3, 161, ou</i> καλεσσάμην, IL. <i>15, 143 ; dans</i> SOPH. <i>El. 230, etc. fut. ant</i>. κεκλήσομαι ; <i>dans une inscr. att</i>. CIA. <i>1, 469, 2 (6<sup>e</sup> siècle av. J.C</i>.).<br><span><b>Étym</b>. <i>R. indo-europ</i>. *klh₁-, appeler ; <i>cf. lat</i>. călāre <i>et</i> clāmāre, clārus.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καλεω - καλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n146 fois dans 138 versets de 20 livres bibliques (NT)\n<ul>\n<li>Matthieu (27)</li>\n<li>Marc (3)</li>\n<li>Luc (42)</li>\n<li>Jean (3)</li>\n<li>Actes (16)</li>\n<li>Romains (8)</li>\n<li>1 Corinthiens (12)</li>\n<li>Galates (4)</li>\n<li>Ephésiens (2)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (3)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (6)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (6)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (1)</li>\n<li>Apocalypse (7)</li>\n</ul>\n</td></tr>\n</table>","G2565":"<h1>kallielaios</h1>\n<p>Strong n° 2565 <i>Prononciation [kal-le-el'-ah-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>l'olivier cultivé par rapport à l'olivier sauvage</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καλλι·έλαιος, ος, ον</b>, qui produit de belles olives : GEOP. <i>9, 8, etc. ; subst</i>. ἡ κ. olivier cultivé, ARSTT. <i>Plant. 1, 6 ;</i> NT. <i>Rom. 11, 24</i>.<br><span><b>Étym</b>. κ. ἐλαία.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καλλιελαιος - καλλιέλαιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G2566":"<h1>kallion</h1>\n<p>Strong n° 2566 <i>Prononciation [kal-lee'-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>meilleur, mieux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κάλλιον</b>, <i>neutre de</i> καλλιών, <i>cp. de</i> .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καλλιων - καλλίον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Comparatif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2567":"<h1>kalodidaskalos</h1>\n<p>Strong n° 2567 <i>Prononciation [kal-od-id-as'-kal-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>enseigner ce qui est bon, un enseignant de bonnes choses</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καλο·διδάσκαλος, ου</b> <span>[κᾰκᾰ]</span> <i>adj. m</i>. qui enseigne le bien, NT. <i>Tit. 2, 3</i>.<br><span><b>Étym</b>. κ. διδάσκαλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καλοδιδασκαλος - καλοδιδάσκαλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G2568":"<h1>Kaloi Limenes</h1>\n<p>Strong n° 2568 <i>Prononciation [kal-oy' lee-men'-es]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Beaux-Ports (Angl. Fair Havens) = « bons ports »\n<ol><li>baie de Crète, près de la ville de Lasée, ainsi appelée à cause de son bon port</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Καλοι λιμενες - Καλοὶ λιμένες</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2569":"<h1>kalopoieo</h1>\n<p>Strong n° 2569 <i>Prononciation [kal-op-oy-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>faire bien, agir droitement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καλοποιέω-ῶ</b> <span>[ᾰ]</span> faire le bien, faire du bien, SPT. <i>Lev. 5, 4 ;</i> NT. <i>2Thess. 3, 13</i>.<br><span><b>Étym</b>. καλοποιός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καλοποιεω - καλοποιέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G2570":"<h1>kalos</h1>\n<p>Strong n° 2570 <i>Prononciation [kal-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>beau, belle, excellent, éminent, de choix, qui surpasse, précieux, utile, convenable, louable, admirable\n<ol type=\"a\">\n<li>beau à regarder, belle forme, magnifique</li>\n<li>bon, excellent dans sa nature et caractéristiques, et donc bien adapté à ses fins\n<ol>\n<li>véritable, approuvé</li>\n<li>précieux</li>\n<li>joint aux hommes désignés par leur fonction, compétent, capable, ...</li>\n<li>honorable, noble</li>\n</ol>\n</li>\n<li>beau en raison de sa pureté de cœur et de vie, et donc digne de louange\n<ol>\n<li>bon moralement, noblesse de cœur</li>\n</ol>\n</li>\n<li>honorable, digne d'honneur</li>\n<li>esprit agréable, réconfortant et confirmé</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>καλός, ή, όν</b> <span>[ᾰ]</span><br><b>A</b> <i>adj. :</i><br><b>   I</b> beau, <i>en parl. de la beauté physique (de pers. ou de ch.) ; joint à</i> ὡραῖος, PD. <i>O. 9, 142 ; à</i> εὐειδής, PLAT. <i>Crit. 44</i> a, <i>etc. ; dans Hom. souv. à</i> μέγας, IL. <i>6, 294 ;</i> OD. <i>9, 513 ; 13, 289 ; 14, 7 ; 15, 418 ; avec un acc</i>. κ. δέμας, OD. <i>17, 307 ;</i> εἶδος κ. XÉN. <i>Cyr. 1, 2, 1 ;</i> κ. τὸ σῶμα, XÉN. <i>Mem. 2, 6, 30,</i> beau de corps, de visage, <i>etc. ; qqf. avec un dat</i>. κ. ἰδέᾳ, PD. <i>O. 10, 123,</i> beau d’aspect ; <i>avec un inf</i>. κ. εἰσοράασθαι, OD. <i>10, 396, ou</i> ἐσορᾶν, PD. <i>O. 8, 25,</i> beau à contempler ; τὰ καλά, les belles choses, <i>particul</i>. les élégances de la vie, HDT. <i>1, 8, etc. ; souv. joint chez les Att. à un n. de pers. c. expression d’amitié, particul. dans les inscriptions qu’on gravait sur les arbres, sur les portes, etc. d’une personne aimée,</i> AR. <i>Ach. 194, Vesp. 98, etc. ;</i><br><b>   II</b> <i>en parl. de la beauté morale, càd</i>. beau, noble, honnête, honorable, glorieux, OD. <i>17, 381 ; 18, 255, etc. ;</i> τέθνηκεν οὗπερ τοῖς νέοις θνῄσκειν καλόν, ESCHL. <i>Sept. 1011,</i> il est mort là où il est beau pour les jeunes hommes de mourir ; <i>cf</i>. SOPH. <i>Ant. 72, etc. ;</i> τὸ καλόν, <i>p. opp. à</i> τὸ αἰσχρόν, XÉN. <i>Mem. 1, 1, 16 ;</i> PLAT. <i>Conv. 183</i> d, le beau, le bien, la vertu ; τὰ καλά, XÉN. <i>Cyr. 7, 3, 16,</i> les belles actions ; καλόν ἐστι(ν) <i>avec l’inf</i>. IL. <i>9, 615, etc. ;</i> OD. <i>20, 244, etc. ;</i> ATT. il est beau de, <i>etc. ;</i> καλὸς καὶ ἀγαθός, <i>ou</i> καλὸς κἀγαθός (<i>non</i> καλοκἀγαθός, <i>malgré</i> καλοκἀγαθία), <i>au plur</i>. καλοὶ κἀγαθοί, καλῶν κἀγαθῶν, καλοὺς κἀγαθούς, <i>primit</i>. de noble naissance, de haut rang, XÉN. <i>Cyr. 4, 3, 23 ;</i> PLUT. <i>Per. 11 ; postér</i>. honnête, XÉN. <i>Cyr. 4, 6, 3 ;</i> PLAT. <i>Gorg. 470</i> e ; τὰ καλὰ κἀγαθὰ ἔργα, XÉN. <i>Cyr. 1, 5, 9, etc</i>. les belles actions, ce qui est beau et bien, le bien, la vertu ; <i>qqf</i>. brave, courageux, DÉM. <i>1390 fin ;</i><br><b>   III</b> <i>p. anal</i>. pur, naturel, <i>en parl. de métaux non travaillés (p. opp. à</i> κίϐδηλος) XÉN. <i>Mem. 3, 1, 9 ;</i><br><b>   IV</b> <i>p. suite :</i><br><b>      1</b> parfait, achevé, accompli : στράτευμα, XÉN. <i>Cyr. 3, 3, 6,</i> armée excellente, accomplie ; <i>c. t. de politesse ou d’amitié :</i> Ἀλκιϐιάδης ὁ καλός, PLAT. <i>1 Alc. 113</i> b ; Ἰσοκράτης ὁ καλός, PLAT. <i>Phædr. 278</i> e, l’excellent Alcibiade, l’excellent Isocrate ; <i>souv. dans le dialogue ironiq</i>. καλὸν γέρας, ESCHL. <i>Eum. 209,</i> un beau privilège ;<br><b>      2</b> précieux, XÉN. <i>Cyr. 7, 2, 12 ;</i><br><b>   V</b> convenable, <i>d’où :</i><br><b>      1</b> apte à, habile à, <i>avec</i> πρός <i>et l’acc</i>. PLAT. <i>Hipp. ma. 295</i> c, <i>etc. ;</i> DÉM. <i>1411, 10 ; avec l’inf</i>. κ. τρέχειν, XÉN. <i>An. 4, 8, 26,</i> habile à la course ;<br><b>      2</b> favorable : κ. λιμήν, OD. <i>6, 263,</i> port bien situé ; κ. ἄνεμος, OD. <i>14, 299,</i> vent favorable ; <i>adv</i>., ἐν καλῷ (<i>s.-e</i>. τόπῳ) XÉN. <i>Hell. 6, 2, 9 ;</i> LUC. <i>Nav. 15,</i> en un lieu favorable ; <i>ou (s.-e</i>. χρόνῳ) SOPH. <i>El. 384 ;</i> EUR. <i>I.A. 1106, etc. ;</i> THC. <i>5, 59 ;</i> XÉN. <i>Hell. 4, 3, 5,</i> au moment opportun, en temps utile, à propos ; εἰς καλόν, SOPH. <i>O.R. 78 ;</i> XÉN. <i>Conv. 1, 4 ;</i> PLAT. <i>Conv. 174</i> e ; εἰς κάλλιστον, SOPH. <i>O.R. 78,</i> à propos, tout à fait à propos ; <i>au sens relig. :</i> κ. οἰωνοί, EUR. <i>Ion 1333 ;</i> ἱερά, ESCHL. <i>Sept. 379,</i> augures, sacrifices favorables ; <i>avec l’inf</i>. ἰέναι καλὰ τὰ ἱερὰ ἦν, XÉN. <i>An. 2, 2, 3,</i> les sacrifices étaient favorables pour aller ;<br><b>B</b> <i>adv. :</i><br><b>      1</b> καλόν, IL. <i>18, 570 ;</i> OD. <i>1, 155, ou</i> καλά, IL. <i>6, 236,</i> de belle façon, avec grâce <i>ou</i> agrément, bien ;<br><b>      2</b> τὸ καλόν, THCR. <i>3, 3 et 18 ;</i> CALL. <i>Ep. 56 ;</i> LUC. <i>Am. 1, m. sign</i>.<br><span>•<i> Cp</i>. καλλίων, IL. <i>24, 52, etc. ;</i> OD. <i>10, 396, etc. ;</i> ATT. ; <i>avec</i> <span>[ῐ]</span> <i>chez les épq. et les lyr.,</i> <span>[ῑ]</span> <i>chez les Att., excepté</i> MÉN. <i>Monost. 726 ; postér</i>. καλλιώτερος, PHRYN. <i>p. 136 ;</i> GEOP. <i>2, 23 ;</i> HSCH. <i>v°</i> αἱρετώτερον ; <i>sup</i>. κάλλιστος, IL. <i>2, 673, etc. ;</i> XÉN. <i>Cyr. 1, 2, 1, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ᾱ]</span> <i>chez les Épq., sauf</i> HÉS. <i>O. 63, Th. 585</i>.<br><span><b>Étym</b>. <i>p</i>. καλϝός ; <i>p.-ê. apparenté à sscr</i>. kalyaḥ, « sain ».</span></span></span><br><br>\n➁ <b>κάλος, ου (ὁ)</b> <i>v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καλος - καλός</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n101 fois dans 90 versets de 16 livres bibliques (NT)\n<ul>\n<li>Matthieu (21)</li>\n<li>Marc (11)</li>\n<li>Luc (9)</li>\n<li>Jean (7)</li>\n<li>Actes (1)</li>\n<li>Romains (5)</li>\n<li>1 Corinthiens (6)</li>\n<li>2 Corinthiens (2)</li>\n<li>Galates (3)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Timothée (16)</li>\n<li>2 Timothée (3)</li>\n<li>Tite (5)</li>\n<li>Hébreux (5)</li>\n<li>Jacques (3)</li>\n<li>1 Pierre (3)</li>\n</ul>\n</td></tr>\n</table>","G2571":"<h1>kalumma</h1>\n<p>Strong n° 2571 <i>Prononciation [kal'-oo-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un voile, ce qui couvre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κάλυμμα, ατος (τὸ)</b> <span>[κᾰ]</span> ce qui sert à couvrir, <i>particul. :</i><br><b>      1</b> voile de femme, <i>qui couvrait toute la figure, excepté les yeux, en retombant sur les épaules,</i> ESCHL. <i>Ch. 494 ;</i> SOPH. <i>Aj. 245 ;</i> EUR. <i>I.T. 372, etc. ; particul</i>. voile de deuil, IL. <i>24, 93 ;</i> HH. <i>Cer. 42 ; fig</i>. ESCHL. <i>Ag. 1178 ; à Thèbes,</i> sorte de capuche de femme, DICÉARQ. <i>p. 16 ;</i><br><b>      2</b> filet de pêche, <i>en forme de sac,</i> OPP. <i>H. 3, 82 ;</i><br><b>      3</b> tombeau, ANTH. <i>7, 227 ;</i><br><b>      4</b> tête, crâne (<i>c</i>. enveloppe du cerveau) NIC. <i>Th. 906 ;</i><br><b>      5</b> peau d’un fruit, NIC. <i>Al. 269 ;</i><br><b>      6</b> <i>chez les animaux,</i> ouïes des poissons, ARSTT. <i>H.A. 1, 13, 6, ou</i> opercule de certains mollusques gastéropodes <i>comme le buccin ou le pourpre,</i> ARSTT. <i>H.A. 5, 15, 12 ;</i><br><b>      7</b> rayon de miel, ARSTT. <i>H.A. 9, 40, 21 ;</i><br><b>      8</b> volet de fenêtre, DS. <i>20, 91</i>.<br><span><b>Étym</b>. καλύπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καλυμμα - κάλυμμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (4)</li>\n</ul>\n</td></tr>\n</table>","G2572":"<h1>kalupto</h1>\n<p>Strong n° 2572 <i>Prononciation [kal-oop'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>cacher, voiler, couvrir (d'un voile)\n<ol type=\"a\">\n<li>empêcher la connaissance d'une chose</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καλύπτω</b> <span>(<i>f</i>. -ύψω, <i>ao</i>. ἐκάλυψα, <i>pf. inus. ; pass. ao</i>. ἐκαλύφθην, <i>pf</i>. κεκάλυμμαι)</span><br><b>      1</b> couvrir, envelopper, cacher : τί τινι, IL. <i>10, 29 ;</i> ATT. couvrir une chose d’une autre, cacher une chose sous une autre ; <i>en parl. de la mort :</i> τινά, IL. <i>16, 502,</i> envelopper qqn ; <i>avec deux acc</i>. τὸν δὲ σκότος ὄσσε κάλυψεν, IL. <i>4, 461,</i> les ténèbres couvrirent ses yeux ; τινὰ τάφῳ κ. SOPH. <i>Ant. 28 ;</i> νεκρὸν γῇ, EUR. <i>Suppl. 531 ;</i> χθονὶ γυῖα, PD. <i>N. 8, 65,</i> couvrir de terre <i>ou</i> d’un tombeau un mort, les membres d’un mort ; <i>avec un seul rég. :</i> νυκτί, IL. <i>5, 23,</i> couvrir d’un nuage obscur ; πέτρον χεὶρ ἐκάλυψεν, IL. <i>16, 735,</i> sa main tenait une pierre ; <i>au pass. :</i> ἀσπίδι κεκαλυμμένος ὤμους, IL. <i>16, 360,</i> ayant les épaules couvertes d’un bouclier ; ἐν χλαίνῃ κεκαλυμμένος, IL. <i>24, 163,</i> enveloppé d’un manteau ; <i>fig</i>. τι καρδίᾳ, SOPH. <i>Ant. 1254,</i> cacher qqe ch. dans son cœur ; σιγῇ, EUR. <i>Hipp. 712,</i> envelopper un secret dans le silence ;<br><b>      2</b> étendre pour couvrir : τι πρόσθεν τινός, IL. <i>22, 313 ;</i> ἀμφί τινι, IL. <i>17, 132,</i> qqe ch. devant qqn, autour de qqn ;<br><b><i>Moy.</i></b> s’envelopper, se couvrir, <i>abs</i>. OD. <i>10, 53 ;</i> AR. <i>Nub. 740 ;</i> τινι, IL. <i>3, 141 ; 14, 184,</i> de qqe ch. ; πρόσωπα, HH. <i>Ven. 183,</i> le visage.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καλυπτω - καλύπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 7 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (2)</li>\n<li>2 Corinthiens (2)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2573":"<h1>kalos</h1>\n<p>Strong n° 2573 <i>Prononciation [kal-oce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>admirablement, finement, d'une façon excellente, bien\n<ol type=\"a\">\n<li>droitement, ne laissant pas de place au reproche, vrai</li>\n<li>noblement, convenablement</li>\n<li>honorablement, avec honneur\n<ol>\n<li>dans un bon endroit, lieu confortable</li>\n</ol>\n</li>\n<li>bien parler de quelqu'un, faire le bien</li>\n<li>être bien (pour ceux qui retrouvent la santé)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>καλῶς</b> <span>[ᾰ]</span> <i>adv</i>., bellement, bien :<br><b>   I</b> <i>au propre, en parl. de beauté physique :</i> καλῶς ἔχειν, XÉN. <i>Mem. 3, 11, 1,</i> être beau ;<br><b>   II</b> <i>fig. en parl. de beauté morale, càd. :</i><br><b>      1</b> honnêtement, honorablement, OD. <i>2, 63 ;</i> ESCHL. <i>Pr. 1012, etc. ;</i> SOPH. <i>Tr. 442 ; etc. ;</i> καλῶς πεφυκέναι, SOPH. <i>El. 989,</i> être bien né, <i>càd. :</i> avoir des sentiments nobles <i>ou</i> généreux ; καλῶς ἀκούειν, PLUT. <i>M. 177</i> e, avoir une bonne réputation ; <i>p. opp. à</i> αἰσχρῶς, PLAT. <i>Conv. 183</i> d ; <i>joint à</i> εὖ : καλῶς καὶ εὖ, PLAT. <i>Prot. 319</i> e, <i>etc. ;</i> καλῶς τε καὶ εὖ, ATT. ; εὖ καὶ κ. ATT. ; εὖ τε καὶ καλῶς, ATT. bien et honnêtement ;<br><b>      2</b> glorieusement : κ. τεθνηκέναι, πίπτειν, ATT. mourir, succomber glorieusement ;<br><b>   III</b> <i>p. suite,</i> convenablement, <i>d’où :</i><br><b>      1</b> favorablement : κ. πράσσειν, ESCHL. <i>Pr. 979 ;</i> SOPH. <i>Tr. 57, etc. ;</i> κ. καὶ εὖ πράττειν, PLAT. <i>Charm. 172</i> a, être dans une belle et bonne situation, être heureux ; καλῶς ἔχει πάντα, DÉM. <i>36, 24,</i> tout va bien ; κ. ἔχει, <i>avec l’inf</i>. XÉN. <i>Mem. 3, 11, 1,</i> il est avantageux de, <i>etc. ;</i> κ. ἔχει τινός, HPC. <i>264, 13,</i> tout va bien du côté de qqe ch., en ce qui regarde qqe ch. ; κ. τινος κεῖσθαι, THC. <i>1, 36 ; ou</i> τινι, THC. <i>1, 44,</i> être en bonne situation pour qqe ch., en vue de qqe ch. ;<br><b>      2</b> convenablement, avec raison : μετὰ ταῦτα ἡ τύχη κ. ποιοῦσα πολλὰ πεποίηκε τὰ κοινά, DÉM. <i>141, 14,</i> après cela, la fortune, avec justice, a accru les revenus de l’État ; <i>cf</i>. AR. <i>Pl. 863 ;</i><br><b>      3</b> parfaitement bien : ταῦτ' ἐγὼ κ. ἔξοιδα, SOPH. <i>O.C. 269,</i> je le sais parfaitement ; <i>particul. dans les réponses, pour approuver ce qui vient d’être dit :</i> καλῶς, EUR. <i>Or. 1216 ;</i> AR. <i>Ran. 888 ;</i> DÉM. <i>998, 24,</i> très bien ; <i>ou pour décliner poliment ou ironiquement une offre :</i> πάνυ καλῶς, AR. <i>Ran. 512,</i> bien, parfaitement, je vous remercie ; <i>au</i> <i>• Sup</i>. κάλλιστ' ἐπαινῶ, AR. <i>Ran. 508,</i> très bien ; <i>avec un adj. :</i> καλῶς εὐδαίμων, ESCHL. <i>fr. 280,</i> tout à fait heureux ; καλῶς εἶ δῆλος οὐκ εἰδώς τί δρᾷς, SOPH. <i>O.R. 1008,</i> il est bien évident que tu ne sais ce que tu fais ; <i>particul. avec</i> καλός : καλὴ καλῶς, AR. <i>Ach. 253, Pax 1330,</i> tout à fait belle : καλὸς κάλλιστα, PD. <i>O. 9, 142,</i> admirablement beau.<br><span>•<i> Cp</i>. κάλλιον, PLAT. <i>Theæt. 161</i> b, <i>Hipp. ma. 300</i> d ; <i>d’où rar</i>. καλλιόνως, PLAT. <i>Theæt. 169</i> e, <i>Leg. 600</i> d. <i>• Sup</i>. κάλλιστα, SOPH. <i>O.R. 1172, 1380 ;</i> PLAT. <i>Pol. 269</i> e, <i>etc. ; ou</i> καλλίστως, A. TR. <i>p. 431, 478, 500</i>.<br><span><b>Étym</b>. καλός.</span></span><br><br>\n➁ <b>κάλως, ω (ὁ)</b> <span>[ᾰ]</span> câble, corde, <i>particul. :</i><br><b>      1</b> câble de navire, <i>pour manœuvrer les voiles :</i> κάλως ἐξιέναι, EUR. <i>Tr. 94,</i> lâcher les câbles, <i>càd</i>. mettre à la voile : <i>proverb</i>. πάντα κάλων ἐξιέναι, EUR. <i>Med. 278 ;</i> AR. <i>Eq. 756 ;</i> ἐφιέναι, PLAT. <i>Sis. 389</i> c ; ἐκτείνειν, PLAT. <i>Prot. 338</i> a ; κινεῖν, LUC. <i>Scyth. 17,</i> lâcher <i>ou</i> mettre en mouvement tous les câbles, <i>càd</i>. larguer toutes les voiles, <i>p. suite, fig</i>. faire jouer tous les ressorts ;<br><b>      2</b> câble pour sonder : κάλων κατιέναι, HDT. <i>2, 28,</i> laisser tomber la sonde ;<br><b>      3</b> câble pour haler : ἀπὸ κάλω παραπλεῖν, THC. <i>4, 25 ;</i> διαπλεῖν, APP. <i>Mithr. 78,</i> naviguer (près du bord, à travers un canal, <i>etc</i>.) en se faisant tirer par une corde, <i>càd. :</i> se faire haler.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att. nom. plur</i>. κάλως, <i>par l’influence de l’acc. plur</i>. CIA. <i>2, 793 a, 62-65 (357 av. J.C.), etc., v. Meisterh. p. 100, 19. À côté de</i> κάλως, <i>on trouve égal. dans les inscr. att. la forme</i> κάλος, <i>d’où plur</i>. κάλοι, CIA. <i>2, 689, 6 (mil. du 4<sup>e</sup> siècle av. J.C.) ; v. Meisterh. ibid. ; ion. et épq</i>. κάλος, OD. <i>5, 260</i>.<br><span><b>Étym</b>. <i>cf</i>. κάλως².</span></span><br><br>\n➂ <b>κάλως, ωος (ὁ)</b> <span>[ᾰ]</span> <i>seul. pl. aux cas suiv. : nom</i>. κάλωες, ORPH. <i>Arg. 621 ;</i> A. RH. <i>2, 725 ; dat</i>. κάλωσι, ORPH. <i>Arg. 237 ; acc</i>. κάλωας, ORPH. <i>Arg. 253 ; c</i>. κάλως.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καλως - καλῶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n37 fois dans 37 versets de 15 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (6)</li>\n<li>Luc (3)</li>\n<li>Jean (4)</li>\n<li>Actes (3)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (2)</li>\n<li>Philippiens (1)</li>\n<li>1 Timothée (4)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (3)</li>\n<li>2 Pierre (1)</li>\n<li>3 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G2574":"<h1>kamelos</h1>\n<p>Strong n° 2574 <i>Prononciation [kam'-ay-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>chameau</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κάμηλος, ου</b> <span>[ᾰ]</span><br><b>      1 (ὁ</b> <i>et</i> <b>ἡ)</b> chameau, chamelle, HDT. <i>3, 105 ;</i> ESCHL. <i>Suppl. 285 ;</i> AR. <i>Av. 1559 ;</i> κ. δρομάς, PLUT. <i>Alex. 31,</i> dromadaire ;<br><b>      2 (ἡ)</b> troupe de chameaux dans une armée, HDT. <i>1, 80</i>.<br><span><b>Étym</b>. <i>emprunt sémitique, cf. hébr</i>. gāmāl, γάμμα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καμηλος - κάμηλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2575":"<h1>kaminos</h1>\n<p>Strong n° 2575 <i>Prononciation [kam'-ee-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un fourneau, un four, une fournaise\n<ol type=\"a\">\n<li>pour une fonderie</li>\n<li>pour incinérer certains produits</li>\n<li>pour cuire le pain</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κάμινος, ου (ἡ)</b> <span>[ᾰῑ]</span><br><b>      1</b> four, fourneau, HOM. <i>Ep. 14 ;</i> CROBYL. (ATH. <i>5</i> f) ; HDT. <i>1, 179 ;</i><br><b>      2</b> fournaise, feu, CHRYS. <i>1Cor. 12</i>.<br><span><b>Étym</b>. <i>p.-ê. pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καμινος - κάμινος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2576":"<h1>kammuo</h1>\n<p>Strong n° 2576 <i>Prononciation [kam-moo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>fermer les yeux, des yeux clos</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>καμμῦσαι</b>, <i>v</i>. καταμύω.<br><br>\n<b>κατα·μύω</b> <span>[ῡ <i>prés. et impf.,</i> ῠ <i>fut. et ao</i>.]</span><br><b>      1</b> cligner des yeux, HPC. <i>1230</i> f ; XÉN. <i>Cyr. 8, 3, 28 ;</i> AR. <i>Vesp. 92 ;</i><br><b>      2</b> fermer les yeux, <i>en parl. de gens effrayés,</i> PHILSTR. <i>242 ; de mourants,</i> LUC. <i>D. mer. 7, 2 ;</i> DL. <i>4, 49 ; de statues,</i> avoir les yeux fermés, STR. <i>264 ; fig. en parl. des yeux de l’âme,</i> PHIL. <i>1, 645, ou de l’intelligence,</i> M. ANT. <i>4, 29</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. avec sync</i>. ἐκάμμυσα, NT. <i>Ap. 28, 27 ; inf. épq</i>. καμμῦσαι, BATR. <i>192</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καμμυω - καμμύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2577":"<h1>kamno</h1>\n<p>Strong n° 2577 <i>Prononciation [kam'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se lasser, être las</li>\n<li>être malade</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κάμνω</b> <span>(<i>f</i>. καμοῦμαι <span>[ᾰ]</span>, <i>ao.2</i> ἔκαμον <span>[ᾰ]</span>, <i>pf</i>. κέκμηκα)</span><br><b>   I <i>intr</i>.<br>      1</b> travailler, prendre de la peine, faire effort, se fatiguer : πολλά, IL. <i>8, 22,</i> grandement ; τινί, OD. <i>14, 65,</i> pour qqn ; <i>avec un inf</i>. οὐ μέν θην κάμετον ὀλλῦσαι Τρῶας, IL. <i>8, 448,</i> vous n’avez pas dû vous fatiguer beaucoup à tuer des Troyens ; <i>ou un part. :</i> οὐκ ἔκαμον τανύων, OD. <i>21, 426,</i> je n’eus pas besoin de beaucoup d’efforts pour tendre (l’arc) ;<br><b>      2</b> être fatigué : χεῖρα, ὦμον, γυῖα, IL. <i>23, 89 ; 16, 106 ; 19, 170,</i> avoir la main, l’épaule, les membres fatigués ; <i>avec un part</i>. se lasser de faire qqe ch. : ἐπεί κε κάμω πολεμίζων, IL. <i>1, 168,</i> après que je me suis fatigué à combattre ; μὴ κάμῃς φίλον ἄνδρα εὐεργετῶν, PLAT. <i>Gorg. 470</i> c, ne te lasse pas de faire du bien à un ami ; <i>cf</i>. ESCHL. <i>Eum. 881 ;</i> PLAT. <i>Rsp. 458</i> a, <i>etc. ; en parl. d’un navire,</i> souffrir d’une traversée, ESCHL. <i>Sept. 210 ; en parl. d’une armée,</i> céder, plier, PD. <i>P. 1, 156 ;</i> EUR. <i>Suppl. 709 ;</i><br><b>      3</b> être souffrant, souffrir, <i>physiq. :</i> νόσου, SOPH. <i>Ph. 282 ;</i> νοσήματι, PLAT. <i>Leg. 916</i> a ; ARSTT. <i>H.A. 8, 21 ;</i> ὑπὸ νόσου τινός, HDN <i>3, 14, 4,</i> être atteint d’une maladie ; <i>avec l’acc. de la maladie :</i> νόσον τινά, EUR. <i>Her. 990 ;</i> PLAT. <i>Rsp. 408</i> e ; ARSTT. <i>H.A. 8, 24, ou de l’organe malade :</i> κ. τοὺς ὀφθαλμούς, HDT. <i>2, 111 ;</i> τὸ σῶμα, PLAT. <i>Gorg. 478</i> a, avoir les yeux, le corps malade ; <i>abs</i>. κεκμηκώς, souffrant, fatigué, <i>joint à</i> τετρωμένος, PLAT. <i>Hipp. ma. 301</i> a ; <i>à</i> ἐκλελυμένος, PLUT. <i>M. 161</i> b ; <i>au mor</i>. ἴσον λύπης, SOPH. <i>El. 532,</i> souffrir d’une peine égale ; τοῖς αἰσχροῖσι, EUR. <i>H.f. 293,</i> d’actions déshonorantes ;<br><b>      4</b> <i>abs</i>. οἱ καμόντες, IL. <i>3, 278 ;</i> OD. <i>11, 476, etc. ;</i> οἱ κεκμηκότες, ESCHL. <i>Suppl. 149 ;</i> THC. <i>3, 59 ;</i> EUR. <i>Suppl. 756, etc. ;</i> PLAT. <i>Leg. 718</i> a, <i>etc</i>. les morts (<i>propr</i>. ceux qui ont supporté les fatigues de la vie) ;<br><b>   II</b> <i>tr. (d’ord. à l’ao.2</i>) travailler : μίτρην, IL. <i>4, 187, 216 ;</i> ὅπλα, IL. <i>18, 614,</i> fabriquer une mitre (<i>ou</i> caleçon garni de plaques de métal), des armes ; πέπλον, IL. <i>5, 338, etc</i>. confectionner un manteau ;<br><b><i>Moy.</i></b> <span>(<i>ao.2</i> ἐκαμόμην)</span><br><b>      1</b> travailler pour soi : νῆσον, OD. <i>9, 130,</i> labourer et cultiver une île pour son usage ; ἱρόν, A. RH. <i>2, 718,</i> se construire un temple ;<br><b>      2</b> gagner <i>ou</i> obtenir par ses efforts ; τι IL. <i>18, 341,</i> qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Act. ao.2 poét</i>. κάμον, IL. <i>8, 195 ;</i> OD. <i>23, 189, etc. ; sbj. 3 sg. épq</i>. κάμῃσι, IL. <i>17, 658 ;</i> OD. <i>14, 65 ; inf</i>. καμέειν, A. RH. <i>1, 19 ; autre ao.2 épq. sbj</i>. κεκάμω, IL. <i>1, 168 ; 3 pl</i>. κεκάμωσιν, IL. <i>7, 5. Pf. dor</i>. κέκμακα <span>[μᾱ]</span> THCR. <i>1, 17 ; pf. part. épq</i>. κεκμηώς, ῶτος, <i>etc</i>. IL. <i>6, 261 ; 23, 232 ;</i> OD. <i>13, 282 ;</i> A. RH. <i>3, 1341, etc. ; par exc. acc. sg. et pl</i>. κεκμηότα, A. RH. <i>3, 234,</i> -ότας, IL. <i>11, 802. Moy. ao.2 poét</i>. καμόμην, IL. <i>18, 341</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *ḱemh₂-, s’efforcer, se fatiguer ; <i>cf</i>. κομέω, κομίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καμνω - κάμνω</font>\n<br><br>apparemment un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2578":"<h1>kampto</h1>\n<p>Strong n° 2578 <i>Prononciation [kamp'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>plier, courber, fléchir le genou\n<ol type=\"a\">\n<li>devant quelqu'un\n<ol>\n<li>en l'honneur de</li>\n<li>en vénération religieuse</li>\n</ol>\n</li>\n<li>utilisé pour ceux qui adorent</li>\n</ol>\n</li>\n<li>s'agenouiller</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κάμπτω</b> <span>(<i>f</i>. κάμψω, <i>ao</i>. ἔκαμψα, <i>pf. inus. ; pass. ao</i>. ἐκάμφθην, <i>pf</i>. κέκαμμαι, -αμψαι, -αμπται, <i>etc</i>.)</span> courber, <i>càd. :</i><br><b>   I</b> plier, faire fléchir :<br><b>      1</b> <i>au propre,</i> IL. <i>4, 486, etc. ;</i> γόνυ, γούνατα, HOM. (IL. <i>7, 118, etc</i>.) ; ESCHL. <i>Pr. 32, etc</i>. plier le genou, les genoux (pour s’asseoir) ; <i>abs</i>. SOPH. <i>O.C. 85 ;</i> κῶλα, SOPH. <i>O.C. 19,</i> faire fléchir ses membres (pour s’asseoir) ; <i>fig. avec un acc. de pers</i>. κ. τινά, PD. <i>P. 2, 94,</i> faire fléchir qqn, l’abattre, l’humilier ; <i>au pass</i>. πημοναῖσι κάμπτεσθαι, ESCHL. <i>Pr. 237, etc</i>. fléchir sous le poids de la douleur ; καμφθῆναι, THC. <i>3, 58 ;</i> PLUT. <i>Per. 36,</i> se laisser fléchir ; κάμπτεσθαι πρός τι, PLAT. <i>Rsp. 494</i> e, <i>ou</i> ἐπί τι, PLAT. <i>Theæt. 173</i> a, se laisser détourner vers qqe ch. ;<br><b>      2</b> <i>t. de mus</i>. faire des inflexions de voix, AR. <i>Th. 53 ;</i><br><b>   II</b> diriger un cheval, un char autour de la borne dans l’hippodrome, <i>càd</i>. doubler le but, <i>d’où en parl. du cheval ou du char :</i> κάμπτοντος ἵππου, SOPH. <i>El. 744,</i> comme le cheval tournait la borne ; <i>p. anal</i>. κάμπτειν ἀκρωτήριον, ἄκραν, HDT. <i>4, 43 ;</i> PLUT. <i>M. 1032</i> f ; <i>ou</i> ἄκρην, HDT. <i>7, 122 ;</i> περὶ ἄκραν, AR. <i>Ach. 96,</i> doubler un cap ; κόλπον, HDT. <i>7, 58,</i> contourner un golfe ; <i>fig</i>. τὸν βίον, SOPH. <i>O.C. 91 ;</i> EUR. <i>Hipp. 87, etc</i>. parcourir le dernier terme de la vie ;<br><b><i>Moy.</i></b> (<i>prés. 2 sg. att</i>. κάμπτει) s’approcher de, <i>fig</i>. EUR. <i>I.T. 815</i> (κάμπτεις <i>Weil</i>).<br><span><b>Étym</b>. <i>emprunt à un substrat pré-grec ou pré-indo-europ</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καμπτω - κάμπτω</font>\n<br><br>apparemment un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (3)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2579":"<h1>kan</h1>\n<p>Strong n° 2579 <i>Prononciation [kan]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>et si</li>\n<li>aussi ou même si\n<ol type=\"a\">\n<li>seulement, au moins</li>\n<li>même si</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>κἀν</b>, <i>par crase p</i>.  .<br><br>\n➁ κἄν<br>   I</b> <i>par crase p</i>.  :<br><b>      1</b> également, aussi bien, <i>avec les mêmes modes que</i> ἄν, ATT. ; <i>en ce sens devant un pronom avec idée de conditionnel :</i> εἰ γὰρ… κἂν ἐγώ, <i>etc</i>. car si… moi aussi je (serais) <i>etc. ;</i> κἂν σύ, <i>etc</i>. toi aussi tu (serais), aussi bien tu (serais) ; <i>qqf. avec un autre</i> ἄν : κἂν σὺ… βελτίων ἂν γένοιο, PLAT. <i>Prot. 318</i> b, toi aussi tu deviendrais meilleur ;<br><b>      2</b> même, <i>souv. suivi de</i> εἰ : κἂν εἰ = καὶ ἂν εἰ, même si, <i>avec idée de conditionnel :</i> κἂν εἰ μὴ δοκεῖ, PLAT. <i>Rsp. 473, etc</i>. même si cela ne paraît pas bon, quand même cela ne paraîtrait pas bon, <i>ou avec l’opt</i>. κἂν εἰ τύχοιεν, PLAT. <i>Rsp. 408</i> b, quand même ils se trouveraient, <i>etc. ;</i><br><b>      3</b> <i>postér</i>. κἄν (<i>non suivi de</i> εἰ) même, <i>au sens de</i> « au moins » : ἀλλά μοι πάρες κἂν σμικρὸν εἰπεῖν, SOPH. <i>El. 1483,</i> mais permets-moi, de parler, ne fût-ce qu’un peu ; οἷς οὐδὲ κἂν ὄνος ὑπῆρξε πώποτε, LUC. <i>Tim. 20,</i> ceux qui n’ont jamais eu même un âne ; <i>cf</i>. NT. <i>Marc. 5, 28 ; 6, 56 ; Ap. 5, 15, etc. ; particul. avec</i> εἷς, μία, ἕν : κἂν εἷς, κἂν μία, κἂν ἕν, PHIL. <i>2, 29 ;</i> SEXT. <i>102, 16 Bkk., etc</i>. au moins un, au moins une ; οὐδὲ κἂν ἅπαξ, POL. <i>3, 9, 2,</i> pas même une fois ;<br><b>   II</b> pour καὶ ἐάν :<br><b>      1</b> et si : κἂν… κἄν, DÉM. <i>774, 7,</i> et si… et si, soit que… soit que, <i>avec les mêmes modes que</i> ἐάν ;<br><b>      2</b> même si, quand même, quoique, <i>avec le sbj. ou l’opt</i>. SOPH. <i>Aj. 15 ;</i> AR. <i>Ach. 957, etc. ; postér. avec l’ind</i>. GAL.<br><span><b>Étym</b>. <i>v</i>. ἄν <i>et</i> ἐάν.</span><br><br>\n➂ <b>κάν</b>, <i>par sync. et assimil. p</i>. κατά : κὰν νόμον, PD. <i>O. 8, 103, p</i>. κατὰ νόμον.<br><span><b>Étym</b>. <i>cf</i>. κάκ <i>et</i> κάμ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καν - κἄν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Particule</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 13 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (3)</li>\n<li>Luc (1)</li>\n<li>Jean (3)</li>\n<li>Actes (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2580":"<h1>Kana</h1>\n<p>Strong n° 2580 <i>Prononciation [kan-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Cana = « l'endroit des roseaux »\n<ol><li>village de Galilée à environ 8 kilomètres au nord ouest de Nazareth</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κανα</font> &lt; נקה - <font face=\"Georgia\">Κανά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>Jean (4)</li>\n</ul>\n</td></tr>\n</table>","G2581":"<h1>Kananites</h1>\n<p>Strong n° 2581 <i>Prononciation [kan-an-ee'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Cananite (Angl. Canaanite) = « zélé »\n<ol><li>le surnom de l'apôtre Simon, autrement connu comme « Simon le Zélote »</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κανανιτης</font> &lt; הקני - <font face=\"Georgia\">Καναναῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G2582":"<h1>Kandake</h1>\n<p>Strong n° 2582 <i>Prononciation [kan-dak'-ay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Candace = « qui possède », « qui se repent »\n<ol><li>reine d'Ethiopie mentionnée en <a class=\"ref\" data-r=\"ACT8.27\">Actes 8.27</a> (38 ap. J.C.) Le nom n'est pas celui d'une personne particulière, mais celui d'une dynastie de reines Ethiopiennes</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κανδακη - Κανδάκη</font>\n<br><br>origine étrangère</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2583":"<h1>kanon</h1>\n<p>Strong n° 2583 <i>Prononciation [kan-ohn']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une verge, ou une pièce de bois droite à laquelle on fixe une chose qui doit rester droite\n<ol type=\"a\">\n<li>utilisé dans de nombreuses occasions\n<ol>\n<li>canne à mesurer, règle</li>\n<li>ligne de charpentier, fil à mesurer</li>\n<li>la mesure d'un saut, comme aux jeux Olympiques</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>limite définie ou espace fixé entre des limites sur lesquelles un pouvoir ou une influence sont impartis\n<ol type=\"a\">\n<li>une province attribuée</li>\n<li>sa propre sphère d'activité</li>\n</ol>\n</li>\n<li>métaph. toute règle ou standard, principe ou loi concernant les jugements, la vie, les actions</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κανών, όνος (ὁ)</b> <span>[ᾰ]</span><br><b>   I</b> <i>propr</i>. tige de roseau, <i>d’où en gén</i>. toute barre de bois longue et droite, <i>particul. :</i><br><b>      1</b> <i>au pl</i>. règles en croix qui maintenaient le derrière du bouclier, <i>d’où</i> poignée de bouclier, IL. <i>8, 193 ; 13, 407 ;</i><br><b>      2</b> tige d’une quenouille, IL. <i>23, 761 ;</i> DH. <i>2, 71 ;</i> AR. <i>Th. 822 ;</i> PLUT. <i>M. 156</i> b ;<br><b>      3</b> règle, <i>d’ord. en bois, à l’usage des maçons et des charpentiers,</i> SOPH. <i>fr. 421 ;</i> EUR. <i>Tr. 6 ;</i> AR. <i>Ran. 799 ;</i> PLAT. <i>Phil. 56</i> b ; <i>particul</i>. règle à régler le papier, ANTH. <i>6, 63 ; d’où</i> ligne droite, <i>en parl. des rayons du soleil,</i> EUR. <i>Suppl. 650 ;</i><br><b>      4</b> pièce <i>ou</i> partie quelconque d’une machine <i>ou</i> d’un assemblage de construction ; <i>particul</i>. bande de bois, longrine, HÉRON <i>Aut. 244 ;</i><br><b>      5</b> fléau d’une balance, <i>d’où</i> balance, ANTH. <i>11, 334 ;</i><br><b>      6</b> <i>au plur</i>. tringles de rideaux, CHARÈS (ATH. <i>538</i> d) ;<br><b>      7</b> clef d’une flûte, ANTH. <i>9, 365 ;</i><br><b>      8</b> barreau d’une cage, CHRYS. <i>Ep. ad Ephes. p. 173 ;</i><br><b>      9</b> <i>au plur</i>. colonnes d’un lit, SPT. <i>Judith 13, 6</i> :<br><b>      10</b> ligne-frontière, limite, NT. <i>2Cor. 10, 15 ;</i><br><b>   II</b> <i>fig</i>. règle, type, modèle, principe, EUR. <i>Hec. 602 ;</i> LYCURG. <i>149, 2 ;</i> DÉM. <i>324, 27 ; joint à</i> στάθμη, LUC. <i>H. conscr. 63 ; à</i> γνώμων, LUC. <i>Harm. 3 ; particul. :</i><br><b>      1</b> μουσικὸς κανών, THEOL. <i>2, 27 ;</i> DL. <i>8, 12,</i> appareil monocorde, sorte de diapason ;<br><b>      2</b> χρονικοὶ κανόνες, PLUT. <i>Sol. 27,</i> époques principales de l’histoire, <i>qui servent comme de points de repère pour les événements moins importants, d’où au sg</i>. système de chronologie, DH. <i>1, 74 ;</i><br><b>      3</b> <i>t. de gramm</i>. règle <i>ou</i> modèle de déclinaison et de conjugaison, règle de grammaire, <i>en gén</i>. GRAMM. ;<br><b>      4</b> le canon alexandrin, <i>liste, dressée par les grammairiens alexandrins, des meilleurs classiques grecs,</i> QUINT. <i>10, 1, 54 et 59</i>.<br><span><b>Étym</b>. <i>cf</i>. κάννα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κανων - κανών</font>\n<br><br>vient de 'kane' (un roseau droit, une verge)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (3)</li>\n<li>Galates (1)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2584":"<h1>Kapernaoum</h1>\n<p>Strong n° 2584 <i>Prononciation [cap-er-nah-oom']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Capernaüm (Angl. Capernaum) = « village de Nahum, de la consolation »\n<ol><li>ville florissante de Galilée située sur la côte ouest de la Mer de Galilée ou Lac de Génésareth, vers le lieu où le Jourdain se jette dans le lac</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Καπερναουμ</font> &lt; כפר נחום - <font face=\"Georgia\">Καφαρναούμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 16 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (3)</li>\n<li>Luc (4)</li>\n<li>Jean (5)</li>\n</ul>\n</td></tr>\n</table>","G2585":"<h1>kapeleuo</h1>\n<p>Strong n° 2585 <i>Prononciation [kap-ale-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être un détaillant, colporter</li>\n<li>gagner de l'argent en vendant quelque chose\n<ol type=\"a\">\n<li>faire un gain sordide en fournissant n'importe quoi, faire une chose pour un gain ridicule</li>\n<li>faire du commerce avec la parole de Dieu\n<ol>\n<li>essayer de faire un gain en enseignant la vérité divine</li>\n</ol>\n</li>\n<li>corrompre, frelater\n<ol>\n<li>les colporteurs avaient l'habitude de falsifier leurs produits pour l'amour du gain</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καπηλεύω</b> <span>[ᾰ]</span><br><b>   I <i>intr.</i></b> être petit marchand <i>ou</i> brocanteur, HDT. <i>1, 155 ; 2, 35 ;</i><br><b>   II</b> <i>tr. en mauv. part :</i><br><b>      1</b> brocanter, trafiquer de : τι, HDT. <i>3, 89 ;</i> HIPPON. <i>fr. 51,</i> de qqe ch. ; <i>fig</i>. κ. εἰρήνην χρυσίου, HDN <i>6, 7,</i> trafiquer de la paix à prix d’or ;<br><b>      2</b> débiter chichement : μάχην, ESCHL. <i>Sept. 545,</i> lésiner <i>ou</i> recourir à de petits moyens à la guerre, faire la guerre petitement (<i>lat</i>. bellum cauponari) ; τὰ μαθήματα, PLAT. <i>Prot. 313</i> d, trafiquer de sa science, la vendre en détail ;<br><b>      3</b> frelater, falsifier, altérer : τὸν βίον, ANTH. <i>9, 180,</i> corrompre la vie, <i>en parl. de la prospérité ;</i><br><b>      4</b> vanter comme un charlatan, <i>acc</i>. EUR. <i>Hipp. 953</i>.<br><span><b>Étym</b>. κάπηλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καπηλευω - καπηλεύω</font>\n<br><br>vient de 'kapelos' (un revendeur)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2586":"<h1>kapnos</h1>\n<p>Strong n° 2586 <i>Prononciation [kap-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>fumée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καπνός, οῦ (ὁ) :<br>      1</b> vapeur, fumée, IL. <i>1, 317, etc. ;</i> OD. <i>1, 58, etc. ; fig. en parl. de choses sans consistance ou sans réalité :</i> καπνοῦ σκιά, ESCHL. <i>fr. 295 ;</i> SOPH. <i>Ant. 1170,</i> une ombre de fumée ; κ. καὶ φλυαρία, PLAT. <i>Rsp. 581</i> d, fumée et bavardage sans raison ; <i>au pl</i>. γραμμάτων καπνοί, EUR. <i>Hipp. 946,</i> savantes niaiseries ;<br><b>      2</b> fumeterre, <i>plante,</i> DIOSC. <i>4, 110, etc</i>.<br><span><b>Étym</b>. <i>p.-ê. pré-grec ou emprunt à un substrat pré-indo-europ. ; cf</i>. καπύω, καπυρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καπνος - καπνός</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 11 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Apocalypse (12)</li>\n</ul>\n</td></tr>\n</table>","G2587":"<h1>Kappadokia</h1>\n<p>Strong n° 2587 <i>Prononciation [kap-pad-ok-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Cappadoce (Angl. Cappadocia) = « province des bons chevaux »\n<ol><li>province montagneuse de l'Asie Mineure, limitée au nord par le Pont, au sud par la Cilicie, à l'est par la Syrie, à l'ouest par la Lycaonie. Ses habitants, adonnés à certaines coutumes immorales étaient considérés comme incultes.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Καππαδοκία, ας (ἡ)</b> <span>[πᾰ]</span> la Cappadoce, <i>contrée de l’Asie Mineure,</i> STR. <i>533 ;</i> HDT. <i>1, 72, etc. ;</i> XÉN. <i>Cyr. 8, 6, 7, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -ίη, HDT. <i>l. c. etc</i>.<br><span><b>Étym</b>. <i>cf</i>. Καππαδόκης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Καππαδοκια - Καππαδοκία</font>\n<br><br>origine étrangère</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2588":"<h1>kardia</h1>\n<p>Strong n° 2588 <i>Prononciation [kar-dee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le cœur\n<ol type=\"a\">\n<li>cet organe du corps animal qui est le centre de la circulation du sang, et donc considéré comme le siège de la vie physique</li>\n<li>le centre de toute vie physique et spirituelle</li>\n<li>la vigueur et le sens de la vie physique</li>\n<li>le centre et le siège de la vie spirituelle\n<ol>\n<li>âme ou esprit, la source et le siège de tous les désirs, envies, buts, efforts</li>\n<li>compréhension, faculté et siège de l'intelligence</li>\n<li>de la volonté et du caractère</li>\n<li>de l'âme affectée et mise en mouvement, dans un bon ou mauvais sens, l'âme siège des sensibilités, affections, émotions, désirs, appétits, passions</li>\n</ol>\n</li>\n<li>l'intérieur, le milieu, le centre de quelque chose, même ce qui est inanimé</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καρδία, ας (ἡ) :<br>   I</b> cœur :<br><b>      1</b> <i>comme organe du corps,</i> IL. <i>13, 282, etc. ;</i> ATT. <i>etc. ; en parl. des animaux, par comparaison, pour marquer la lâcheté</i> (cœur de biche, <i>etc</i>.) IL. <i>1, 225 ;</i> ESCHL. <i>Eum. 861 ;</i> LUC. <i>Salt. 85 ;</i><br><b>      2</b> <i>comme siège des passions ou des facultés de l’âme (courage, amitié, amour, colère, etc</i>.) IL. <i>1, 225, etc. ;</i> ESCHL. <i>Ch. 167, etc. ;</i> PLAT. <i>Conv. 215</i> d ; ἐκ καρδίας φιλεῖν, AR. <i>Nub. 86 ;</i> ἐξ ὅλης καρδίας, NT. <i>Marc. 12, 30, 33 ; Luc. 10, 27 ;</i> ἀπὸ καρδίας, THCR. <i>Idyl. 29, 4,</i> aimer de tout cœur ; τὰ ἀπὸ καρδίας λέγειν, EUR. <i>I.A. 475 ;</i> PLUT. <i>M. 63</i> a, parler à cœur ouvert, franchement, librement ;<br><b>      3</b> <i>comme siège de l’intelligence,</i> IL. <i>21, 441, etc. ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> orifice supérieur de l’estomac, <i>d’où</i> estomac, THC. <i>2, 49 ;</i> GAL. <i>5, 108 ;</i><br><b>      2</b> intérieur d’une chose (d’une clepsydre, ARSTT. <i>Probl. 16, 8 ;</i> de la mer, SPT. <i>Ezech. 27, 4, etc.) ; particul</i>. moelle d’un arbre, TH. <i>H.P. 1, 2, 6, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dissyll</i>. <span>[‒ ‒]</span> ESCHL. <i>Sept. 288, Suppl. 72, 799 ; ion</i>. καρδίη, ης, <i>seul. au commenc. des vers,</i> IL. <i>2, 452 ; 11, 12 ; 14, 152 ; poét</i>. κραδία, ESCHL. <i>Sept. 781, etc. ;</i> EUR. <i>Med. 99, etc. dans les vers dactyliques et anapestiques ; ion</i>. κραδίη, IL. <i>1, 225, etc. ;</i> OD. <i>4, 427, etc</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *ḱēr(d)-, ḱrd-, cœur ; <i>cf</i>. κῆρ, <i>lat</i>. cor, <i>th</i>. cord-.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καρδια - καρδία</font>\n<br><br>vient du mot primaire 'kar' (Latin, cor, « cœur »)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n158 fois dans 151 versets de 22 livres bibliques (NT)\n<ul>\n<li>Matthieu (16)</li>\n<li>Marc (12)</li>\n<li>Luc (23)</li>\n<li>Jean (7)</li>\n<li>Actes (21)</li>\n<li>Romains (15)</li>\n<li>1 Corinthiens (5)</li>\n<li>2 Corinthiens (11)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (5)</li>\n<li>Philippiens (2)</li>\n<li>Colossiens (5)</li>\n<li>1 Thessaloniciens (3)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (11)</li>\n<li>Jacques (5)</li>\n<li>1 Pierre (3)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (4)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G2589":"<h1>kardiognostes</h1>\n<p>Strong n° 2589 <i>Prononciation [kar-dee-og-noce'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>celui qui connaît les cœurs</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καρδιο·γνώστης, ου</b>, <i>adj. m</i>. qui connaît le fond des cœurs, NT. <i>Ap. 1, 24 ;</i> CLÉM. <i>Str. 2, 13, § 56</i>.<br><span><b>Étym</b>. κ. γιγνώσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καρδιογωστης - καρδιογνώστης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G2590":"<h1>karpos</h1>\n<p>Strong n° 2590 <i>Prononciation [kar-pos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fruit\n<ol type=\"a\">\n<li>le fruit des arbres, des vignes, des champs</li>\n<li>le fruit de ses reins : progéniture, descendant, postérité</li>\n</ol>\n</li>\n<li>ce qui a son origine ou qui vient de quelque chose, un effet, un résultat\n<ol type=\"a\">\n<li>travail, action, un fait</li>\n<li>avantage, profit, utilité</li>\n<li>louanges, qui sont présentées à Dieu en offrandes de remerciement</li>\n<li>récolter le fruit (moissonner la récolte) dans la vie éternelle pour ceux qui auront travaillé leur âme pour cette récolte</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καρπός, οῦ (ὁ) :<br>   I</b> fruit, <i>au propre, càd. :</i><br><b>      1</b> fruit de la terre <i>ou</i> des plantes, IL. <i>6, 142, etc. ;</i> HÉS. <i>O. 117 ;</i> XÉN. <i>Œc. 7, 12 ;</i> PLAT. <i>Menex. 238</i> a, <i>etc. ; p. ext</i>. produit des biens de la terre : ὑγροὶ καὶ ξηροὶ κ. XÉN. <i>Œc. 5, 20,</i> les produits liquides (vin, huile) et les produits secs ;<br><b>      2</b> grain, graine, semence, HPC. <i>687, 12, etc. ;</i> XÉN. <i>Œc. 16, 11 ;</i> TH. <i>H.P. 1, 2, 1, etc. ;</i><br><b>      3</b> produit, rejeton d’animal, XÉN. <i>Cyr. 1, 1, 2 ;</i> OPP. <i>H. 2, 22, etc. ;</i><br><b>      4</b> <i>fig. en parl. du produit des champs, des bestiaux, etc. (cf. lat</i>. fructus) produit, revenu, profit, SOPH. <i>fr. 717 ;</i> PLAT. <i>Phædr. 260</i> c, <i>etc. ; d’où, en parl. d’actions,</i> produit, résultat, effet, <i>en b. et en mauv. part,</i> PD. <i>O. 7, 15, etc. ;</i> ESCHL. <i>Eum. 830, etc. ;</i><br><b>   II</b> jointure de la main et du bras, carpe, poignet, IL. <i>24, 671 ;</i> OD. <i>24, 398 ;</i> ARSTT. <i>H.A. 1, 15, etc. ;</i> κ. χερός, EUR. <i>Ion 1009 ;</i> κ. χειρῶν, EUR. <i>Ion 891, m. sign</i>.<br><span><b>Étym</b>. <i>p.-ê. emprunt à un substrat pré-indo-europ. ; selon d’autres, R. indo-europ</i>. *kerp-, cueillir ; <i>cf. lat</i>. carpō, <i>all</i>. Herbst.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καρπος - καρπός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n66 fois dans 56 versets de 14 livres bibliques (NT)\n<ul>\n<li>Matthieu (19)</li>\n<li>Marc (5)</li>\n<li>Luc (12)</li>\n<li>Jean (10)</li>\n<li>Actes (1)</li>\n<li>Romains (4)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (3)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (4)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2591":"<h1>Karpos</h1>\n<p>Strong n° 2591 <i>Prononciation [kar'-pos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Carpus = « le fruit »\n<ol><li>un chrétien de Troas (<a class=\"ref\" data-r=\"2TI4.13\">2 Timothée 4.13</a>)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Κάρπος, ου (ὁ)</b> Karpos, <i>h</i>. ANTH. <i>App. 177</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Καρπος - Κάρπος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2592":"<h1>karpophoreo</h1>\n<p>Strong n° 2592 <i>Prononciation [kar-pof-or-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>porter du fruit</li>\n<li>porter, apporter</li>\n<li>porter le fruit de soi-même</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καρποφορέω-ῶ</b>, porter <i>ou</i> produire des fruits, XÉN. <i>Vect. 1, 3 ;</i> TH. <i>H.P. 3, 3, 7, etc</i>.<br><span><b>Étym</b>. καρποφόρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καρποφορεω - καρποφορέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>Romains (2)</li>\n<li>Colossiens (2)</li>\n</ul>\n</td></tr>\n</table>","G2593":"<h1>karpophoros</h1>\n<p>Strong n° 2593 <i>Prononciation [kar-pof-or'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>qui porte du fruit, fructueux, fertile, productif</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καρπο·φόρος, ος, ον</b>, qui porte <i>ou</i> produit des fruits, <i>en parl. d’arbres,</i> XÉN. <i>Cyr. 6, 2, 22 ; en parl. de pays,</i> PD. <i>P. 4, 11 ; en parl. de Dèmèter,</i> AR. <i>Ran. 382 ; en gén</i>. productif, EUR. <i>I.T. 1235</i>.<br><span><b>Étym</b>. κ. φέρω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καρποφορος - καρποφόρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2594":"<h1>kartereo</h1>\n<p>Strong n° 2594 <i>Prononciation [kar-ter-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être constant</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καρτερέω-ῶ</b> <span>(<i>ao</i>. ἐκαρτέρησα, <i>pf. pass</i>. κεκαρτέρημαι)</span><br><b>      1</b> être ferme, patient, <i>abs</i>. SOPH. <i>Ph. 1274 ;</i> ἐν πολέμῳ, PLAT. <i>Lach. 193</i> a, <i>ou sans prép. :</i> μάχῃ, EUR. <i>Her. 837,</i> à la guerre, dans le combat ; ἐπί τινι, ISOCR. <i>125</i> d ; <i>ou</i> πρός τι, XÉN. <i>Cyr. 2, 3, 13 ;</i> PLAT. <i>Rsp. 566</i> b, contre qqe ch. supporter qqe ch. avec patience, résignation <i>ou</i> courage ; ἀπό τινος, EL. <i>N.A. 13, 13,</i> s’abstenir <i>ou</i> se passer facilement de qqe ch. ; τι, SOPH. <i>Aj. 650 ;</i> XÉN. <i>Mem. 1, 6, 7 ;</i> ISOCR. <i>8</i> d, supporter patiemment qqe ch. <i>ou</i> s’obstiner à faire qqe ch., EUR. <i>I.A. 1370 ; avec un part</i>. persister à, PLAT. <i>Lach. 192</i> e ; ἅ. ἐγὼ οὔτε τότ' ἐκαρτέρουν ἀκούων, ESCHN. <i>88, 19,</i> choses que je n’ai pas eu alors le courage <i>ou</i> la patience d’écouter ; <i>au pass</i>. κεκαρτέρηται τἀμά, EUR. <i>Hipp. 1457,</i> je suis arrivé au terme de mes efforts, <i>càd</i>. je suis mort ;<br><b>      2</b> <i>p. suite,</i> être modéré : ἐν ταῖς ἡδοναῖς, PLAT. <i>Leg. 635</i> c, dans les plaisirs.<br><span><b>Étym</b>. καρτερός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καρτερεω - καρτερέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2595":"<h1>karphos</h1>\n<p>Strong n° 2595 <i>Prononciation [kar'-fos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une tige sèche ou brindille, une paille</li>\n<li>menue paille, balle</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κάρφος, εος-ους (τὸ) :<br>   I</b> tout corps sec provenant d’une écorce <i>ou</i> de rognure, <i>particul. :</i><br><b>      1</b> brin de paille, fétu, ESCHL. (SCH.-NIC. <i>Th. 288</i>) ; ARSTT. <i>H.A. 6, 2, 20 ;</i> ATH. <i>187</i> c ; <i>au pl</i>. brindilles, AR. <i>Av. 641 ;</i> LUC. <i>Herm. 33 ;</i> POLYEN <i>4, 3 ;</i><br><b>      2</b> petite planchette où l’on inscrivait le mot d’ordre, POL. <i>6, 36, 3 ;</i><br><b>      3</b> baguette dont le préteur touchait les esclaves pour les affranchir, PLUT. <i>M. 550</i> b ;<br><b>   II</b> fruit mûr (<i>cf</i>. καρπός) NIC. <i>Al. 230, 491 ; Th. 893</i>.<br><span><b>Étym</b>. <i>cf</i>. καρφόω <i>et</i> καρπός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καρφος - κάρφος</font>\n<br><br>vient de karpho (flétrir)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (3)</li>\n</ul>\n</td></tr>\n</table>","G2596":"<h1>kata</h1>\n<p>Strong n° 2596 <i>Prononciation [kat-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>depuis, entre</li>\n<li>selon, envers, le long de, contre ...</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>κατά</b> <span>[ᾰᾰ]</span> <b><i>adv. et prép. : Adv. :</i><br>   I</b> de haut en bas, <i>d’où :</i><br><b>      1</b> en bas : κατὰ δάκρυ χέουσα, IL. <i>1, 413,</i> laissant tomber une larme ; κὰδ δέ οἱ ὕδωρ χεῦαν, IL. <i>14, 435,</i> ils versèrent de l’eau sur son corps ; κὰδ δ' ἄρ' ἑζέσθην, IL. <i>7, 58,</i> (Athèna et Apollon) descendirent se poser (sous la forme de deux vautours) ; κατ' ἄρ' ἕζετο, IL. <i>1, 68</i> (après avoir ainsi parlé) il s’assit ; <i>fig</i>. ὕπνον κατ' ἀπείρονα χεῦεν, OD. <i>7, 286,</i> (et un dieu) versa (sur moi) un profond sommeil ;<br><b>      2</b> en dessous, au fond, <i>d’où</i> à fond, tout à fait, complètement : κατὰ ταῦρον ἐδηδώς, IL. <i>17, 542,</i> (semblable au lion) qui a dévoré un taureau ; κατὰ τέκν' ἔφαγε, IL. <i>2, 317,</i> (dès qu’) il eut mangé les petits passereaux ; κατὰ μηρί' ἔκηα, IL. <i>1, 40,</i> (si) j’ai brûlé (en ton honneur) des cuisses (de victimes) ;<br><b>      3</b> <i>avec</i> κατά <i>ainsi employé on rencontre qqf. dans la propos. un gén. de direction indépendant de la préposition :</i> κατὰ δ' αἷμα ἔρρεε χειρός, IL. <i>13, 539,</i> de sa main le sang coulait ; κατὰ δὲ ῥέεν ἱδρὼς ὤμων καὶ κεφαλῆς, IL. <i>11, 811,</i> de ses épaules et de sa tête la sueur coulait ;<br><b>   II</b> <i>p. ext</i>. en arrière, <i>t. de balist., le bas d’une machine de jet étant en même temps l’arrière,</i> HÉRON, PHIL. BYZ.<br><i>Prép. avec le gén. et l’acc. :</i><br><b>A</b> <i>avec le gén. :</i><br><b>   I</b> <i>pour marquer le point de départ :</i> du haut de : βῆ δὲ κατ' Οὐλύμποιο καρήνων, IL. <i>22, 187,</i> (Athèna) descendit des sommets de l’Olympe ; δάκρυα δέ σφιν κατὰ βλεφάρων χαμάδις ῥέεν, IL. <i>17, 438,</i> des larmes coulèrent de leurs paupières ; ἅλλεσθαι κατὰ τῆς πέτρας, XÉN. <i>An. 4, 2, 17,</i> sauter du haut du rocher ; <i>fig. dans la locut</i>. κατ' ἄκρας ἑλεῖν, THC. <i>4, 112,</i> s’assurer de la ville en occupant les parties élevées ; κατ' ἰχνῶν τινος ὁδεύειν, LUC. <i>Rh. præc. 9,</i> marcher sur les traces de qqn, <i>càd</i>. en passant d’une trace à l’autre comme on descend d’un échelon à un autre ;<br><b>   II</b> <i>pour marquer le point d’arrivée, càd. :</i><br><b>      1</b> sur : κατὰ χθονὸς ὄμματα πήξας, IL. <i>3, 217,</i> ayant fixé ses yeux à terre ; ὕδωρ κατὰ χειρὸς καταχεῖν, AR. <i>Av. 464,</i> verser de l’eau sur la main ; μύρον κατὰ τῆς κεφαλῆς καταχεῖν, PLAT. <i>Rsp. 398</i> a, répandre une huile parfumée sur la tête (de qqn) ; <i>fig</i>. κατὰ δ' ὀφθαλμῶν κέχυτ' ἀχλύς, IL. <i>5, 696,</i> et les ténèbres se répandirent sur ses yeux ; τῷ μὲν ἔπειτα κατ' ὀφθαλμῶν χέεν ἀχλύν, IL. <i>20, 321,</i> ensuite il répandit sur les yeux (d’Achille) un sombre nuage ; <i>p. anal. dans les serments, à cause de l’imposition des mains sur l’objet au nom duquel on parle :</i> κατὰ τῶν παίδων ὀμνύναι, DÉM. <i>852, 18,</i> jurer sur la tête de ses enfants ; ἐπιορκεῖν κατὰ τῶν παίδων, LYS. <i>210, 9,</i> violer un serment qu’on a fait sur la tête de ses enfants ; <i>p. ext</i>. κατ' ἐξωλείας ὀμνύναι, ATT. jurer par sa perte, <i>càd</i>. sur sa propre tête (<i>v</i>. ἐξώλεια) ;<br><b>      2</b> au fond de, à l’intérieur de, dans : αἰχμὴ κατὰ γαίης ᾤχετο, IL. <i>13, 504,</i> la javeline tomba à terre ; καταδῦναι κατὰ θαλάσσης, HDT. <i>7, 6,</i> s’enfoncer dans la mer ; κατὰ χθονὸς κρύπτειν, SOPH. <i>Ant. 24,</i> déposer dans le sein de la terre ; ὁ κατὰ γῆς, XÉN. <i>Cyr. 4, 6, 5,</i> celui qui est sous terre, le mort ; οἱ κατὰ χθονὸς θεοί, ESCHL. <i>Pers. 689,</i> les divinités souterraines, les dieux infernaux ;<br><b>   III</b> <i>pour marquer la direction, le but :</i><br><b>      1</b> en vue de : τοξεύειν κατὰ σκοποῦ, HDN <i>6, 7, 19,</i> lancer un trait dans la direction d’un but ; <i>fig</i>. en vue de, à l’égard de : λέγειν κατά τινος, XÉN. <i>Cyr. 1, 2, 16,</i> parler sur qqn <i>ou</i> sur qqe ch. (<i>mais v. ci-dessous la même locut. en mauv. part</i>) ; ἔπαινος κατά τινος, PLAT. <i>Phædr. 260</i> b, éloge de qqn ; καθ' ὅλου, ATT. <i>c</i>. ὅλως, en général ; κατὰ παντός, ATT. <i>c</i>. πάντως, <i>m. sign. ;</i><br><b>      2</b> <i>en mauv. part,</i> contre : λόγχην στῆσαι κατά τινος, SOPH. <i>Ant. 145,</i> tenir sa lance en arrêt contre qqn ; λέγειν κατά τινος, SOPH. <i>Ph. 65,</i> parler contre qqn ; οἱ κατὰ Φιλίππου λόγοι, les discours (de Démosthène) contre Philippe ;<br><b>B</b> <i>avec l’acc. :</i><br><b>   I</b> en suivant de haut en bas, en descendant :<br><b>      1</b> <i>avec idée de lieu :</i> κατὰ ῥόον, HDT. <i>2, 96,</i> en descendant le courant (<i>p. opp. à</i> ἀνὰ ῥόον) ; τὸ ὕδωρ κατὰ τὰς τάφρους ἐχώρει, XÉN. <i>Cyr. 7, 5, 16,</i> l’eau s’épanchait dans les tranchées ; <i>particul. pour marquer une idée de distribution, de répartition (propr</i>. en descendant de l’un à l’autre) : πορεύεσθαι κατὰ τὰ ἴχνη, XÉN. <i>Cyn. 8, 2,</i> suivre les traces, <i>litt</i>. aller de l’une à l’autre ; κατὰ φῦλα, κατὰ φρήτρας, IL. <i>2, 362,</i> par tribus, par familles ; καθ' ἕνα ἕκαστον, XÉN. <i>Hell. 1, 7, 23,</i> un par un ; κατ' ἄνδρα, HDT. <i>6, 79,</i> homme par homme ; κατὰ κώμας κατῳκῆσθαι, HDT. <i>1, 96,</i> habiter dans des villages séparés ; ἐσκήνουν κατὰ τάξεις, XÉN. <i>Cyr. 2, 1, 25,</i> les troupes logeaient sous des tentes par compagnies ; κατὰ διακοσίας καὶ τριακοσίας, DÉM. <i>817, 1,</i> payer par sommes de 200 et de 300 drachmes ; κατὰ μέρος φυλάττειν, XÉN. <i>An. 5, 1, 9,</i> monter la garde par détachements ; κατὰ σμικρὸν ἀποκρίνεσθαι, PLAT. <i>Prot. 338</i> c, répondre en détail ;<br><b>      2</b> <i>avec idée de temps,</i> pendant : κατὰ τὸν πόλεμον, HDT. <i>7, 157,</i> pendant la guerre, (<i>litt</i>. d’un bout à l’autre de la guerre) ; δεῖπνον κατὰ φῶς ἐποιοῦντο, XÉN. <i>Cyr. 3, 3, 25,</i> ils prenaient le repas du soir pendant qu’il faisait encore jour ; κατὰ τὸν κατὰ Κροῖσον, HDT. <i>1, 67,</i> au temps de Crésus ; κατὰ τὸν αὐτὸν χρόνον, HDT. <i>3, 131,</i> dans le même temps ; κατὰ τοὺς Ἡρακλείδας, XÉN. <i>Lac. 10, 8,</i> du temps des Héraclides ; οἱ κατ' ἐκείνους ὑμέτεροι πρόγονοι, DÉM. <i>561 fin,</i> vos ancêtres leurs contemporains ; <i>avec idée de distribution :</i> καθ' ἡμέραν, ESCHL. <i>Ch. 819,</i> jour par jour ; κατ' ἐνιαυτόν, XÉN. <i>An. 3, 2, 12,</i> chaque année ;<br><b>   II</b> en tombant sur :<br><b>      1</b> <i>au propre :</i> βέλος κατὰ καίριον ἦλθεν, IL. <i>11, 439,</i> le trait (ne) l’atteignit (pas) mortellement (<i>litt</i>. en le frappant sur un point vital) ; παίειν κατὰ τὸ στέρνον, XÉN. <i>An. 1, 8, 26,</i> frapper à la poitrine ;<br><b>      2</b> <i>p. ext</i>. à travers (du haut en bas, d’un bout à l’autre) : καθ' Ἑλλάδα, ESCHL. <i>Ag. 578,</i> par toute la Grèce ; κατὰ πόλιν, ESCHL. <i>Sept. 6,</i> par la ville ; κατὰ γῆν, κατὰ θάλατταν, XÉN. <i>Hell. 8, 1,</i> par terre, par mer ; sur terre, sur mer ; κατὰ τὴν ὁδόν, sur le chemin, XÉN. <i>An. 4, 2, 16, ou</i> le long de la rue, XÉN. <i>An. 5, 2, 19 ;</i><br><b>      3</b> <i>p. ext</i>. dans le voisinage de, auprès de : τύμϐον κατ' αὐτόν, ESCHL. <i>Sept. 528,</i> près du tombeau même ; κατὰ τὸ προάστειον, HDT. <i>3, 54,</i> à l’entrée du faubourg ; <i>avec idée de nombre :</i> κατὰ ἑξήκοντα ἔτεα καὶ χίλια, HDT. <i>2, 145,</i> vers <i>ou</i> environ 1060 années ; <i>cf</i>. HDT. <i>6, 117 ;</i><br><b>   III</b> <i>p. anal. avec simple idée de direction,</i> en regardant vers :<br><b>      1</b> en face de : κατὰ βορέαν ἑστηκώς, THC. <i>6, 104,</i> exposé au vent du nord ; <i>cf</i>. THC. <i>2, 30 ; 3, 107 ; fig</i>. en vue de : πλάζεσθαι κατὰ ληΐδα, OD. <i>3, 106, ou</i> κατὰ ληΐην, HDT. <i>2, 152,</i> aller de côté et d’autre en quête d’un butin ; καθ' ἁρπαγὴν ἐσκεδασμένοι, XÉN. <i>An. 3, 5, 2,</i> s’étant dispersés pour piller ; κατὰ θέαν ἥκειν, THC. <i>6, 31,</i> être venu dans le dessein de voir ; καθ' ἡδονήν, ESCHL. <i>Pr. 261,</i> pour plaire ;<br><b>      2</b> <i>avec idée d’hostilité,</i> contre : ἀνὴρ κατ' ἄνδρα, ESCHL. <i>Sept. 505,</i> homme contre homme ; οἱ μὲν Ἀθηναῖοι κατὰ Λακεδαιμονίους ἐγένοντο, XÉN. <i>Hell. 4, 2, 18,</i> les Athéniens se trouvèrent en face des Lacédémoniens ;<br><b>      3</b> <i>fig</i>. au sujet de, par rapport à, en ce qui concerne : τὰ κατ' ἀνθρώπους, ESCHL. <i>Eum. 930,</i> les affaires humaines ; τὰ κατὰ τὴν μουσικήν, PLAT. <i>Ax. commenc</i>. les préceptes de la musique ; <i>en ce sens, construit avec un nom abstrait, il équivaut à une locut. adverb. :</i> καθ' ἡσυχίην, HDT. <i>1, 9, c</i>. ἡσύχως, en sécurité, en paix ; κατὰ τάχος, HDT. <i>7, 178, c</i>. ταχέως, en hâte ; κατὰ κράτος, XÉN. <i>Hell. 2, 1, 19,</i> de force ; κατὰ σπουδήν, XÉN. <i>An. 7, 6, 28,</i> vivement, avec célérité ;<br><b>      4</b> <i>p. suite,</i> selon, suivant, d’après : καθ' ἡμέτερον νόον, IL. <i>9, 108,</i> selon notre sentiment ; κατὰ τὸν νόμον, XÉN. <i>An. 7, 3, 23,</i> conformément à la loi, selon la loi ; καθ' ἔχθραν, ESCHL. <i>Suppl. 335 ;</i> κατ' ἔχθος, THC. <i>1, 103,</i> par haine ; κατὰ φθόνον, ESCHL. <i>Eum. 686,</i> par jalousie ; <i>avec un n. de pers. :</i> κατ' Αἰσχύλον, AR. <i>Th. 134,</i> d’après Eschyle, comme dit Eschyle ; κατὰ Πίνδαρον, PLAT. <i>Phædr. 227</i> b, selon Pindare ; <i>avec idée de comparaison :</i> κρομύοιο λοπὸν κάτα (<i>pour l’accent, v. fin de l’article</i>) OD. <i>19, 233,</i> comme une pelure d’oignon ; κηδεῦσαι καθ' ἑαυτόν, ESCHL. <i>Pr. 890,</i> se marier selon son rang ; οὐ κατ' ἄνθρωπον φρονεῖν, ESCHL. <i>Sept. 425,</i> n’avoir pas les sentiments d’un homme ; <i>particul. après un compar</i>. μείζων ἢ κατ' ἀνθρώπου φύσιν, HDT. <i>8, 38,</i> plus grand que selon la nature humaine ; μείζω ἢ κατὰ δάκρυα, THC. <i>7, 75,</i> (les maux que l’armée avait soufferts étaient) de ceux que les larmes ne sauraient égaler ;<br><b>      5</b> au fond de, dans : κατὰ θυμόν, IL. <i>2, 409,</i> au fond de son cœur, dans son cœur.<br><span><b><span class=\"arrow\"></span><br>   I</b> <i>l’α final allongé à l’arsis,</i> HÉS. <i>Th. 417 ;</i> DP. <i>572 ;</i><br><b>   II</b> κατά <i>en poésie se place qqf. après son régime, et dans ce cas il s’accentue</i> κάτα : ἕλος κάτα, IL. <i>20, 221 ;</i> δῶμα κάτα, OD. <i>19, 345 ; cf</i>. OD. <i>20, 369, etc. ;</i><br><b>   III</b> <i>devant un mot commençant par une des gutturales</i> γ, κ ; <i>une des dentales</i> δ, τ ; <i>une des labiales</i> π, φ ; <i>une des liquides</i> μ, ν, ρ, <i>il peut se syncoper et s’assimiler</i> (<i>v</i>. κάγ, κάκ ; κάδ, κάτ ; κάπ ; κάμ, κάν, κάρ) ; <i>dans les inscr. att. la prépos. conserve sa forme régulière jusque vers 350 av. J.C. ; à partir de 345 av. J.C. elle se réduit par syncope et assimilation à κα- pour κατ- devant un</i> τ : κατάδε <i>pour</i> κὰτ τάδε (κατὰ τάδε) CIA. <i>2, 1055, 1 (345 av. J.C</i>.) ; κατὰ εἰωθότα <i>pour</i> κὰτ (κατὰ) τὰ εἰωθότα, <i>Th. 163, 15 (334/326 av. J.C</i>.) ; κατοὺς νόμους <i>pour</i> κὰτ (κατὰ) τοὺς νόμους, <i>Th. 594, 15 (127 av. J.C.) ; v. Meisterh. p. 178, 32. En composition il peut de même se changer en καϐ devant</i> β : <i>v</i>. κάϐϐαλε ; <i>en κατ devant</i> θ (<i>v</i>. κάτθανε) ; <i>en καλ devant</i> λ (<i>v</i>. κάλλιπε) ; <i>en καρ devant</i> ρ (<i>v</i>. καρρέζουσα) ; <i>devant στ et σχ il se réduit à</i> κα (<i>v</i>. καστορνῦσα <i>et</i> κάσχετε) ;<br><b>   IV</b> <i>En composition avec le radical βα de βαίνω, κατά devient</i> καται- : <i>v</i>. καταιϐάτης, καταιϐατός ; <i>cf</i>. παραί- <i>de</i> παρά ;<br><b>   V</b> <i>En composition κατά marque :</i><br><b>      1</b> <i>l’idée de</i> « descendre » : <i>v</i>. καταϐαίνω, καταϐάλλω, κατάκειμαι, κατέρχομαι, <i>etc. ;</i><br><b>      2</b> <i>l’idée de</i> « aller dans le sens de », <i>d’où l’idée de</i> « en conformité », « d’accord avec », « selon » : <i>v</i>. κατᾴδω ; <i>p. suite, l’idée de</i> « en réponse à » : <i>v</i>. καταϐοάω ;<br><b>      3</b> <i>en mauv. part, l’idée de</i> « aller contre », <i>d’où en gén. l’idée d’hostilité : v</i>. καταγιγνώσκω, κατακρίνω, κατηγορέω, <i>qqf. avec un subst</i>. καταδίκη ;<br><b>      4</b> <i>l’idée de</i> « tout à fait », « complètement », <i>d’ord. en mauv. part : v</i>. κατακαίω, κατακτείνω, καταφαγεῖν, καταλειτουργέω, <i>etc. ;</i><br><b>      5</b> <i>p. suite, une simple idée de renforcement : v</i>. καταθρηνέω.<br><span><b>Étym</b>. <i>indo-europ</i>. *kmt-, en bas, avec, le long de ; <i>cf</i>. κοινός, <i>lat</i>. cum.</span></span><br><br>\n➁ <b>κᾆτα</b>, <i>crase att. p</i>.  .<br><br>\n➂ <b>κάτα</b>, <i>v</i>. κατά, <i>fin</i> II.<br><br>\n➃ <b>κατά</b>, <i>p</i>. κὰτ τά.<br><span><b>Étym</b>. <i>v</i>. κατά, <i>fin</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κατα - κατά</font>\n<br><br>particule primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Préposition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n475 fois dans 433 versets de 26 livres bibliques (NT)\n<ul>\n<li>Matthieu (37)</li>\n<li>Marc (20)</li>\n<li>Luc (43)</li>\n<li>Jean (10)</li>\n<li>Actes (94)</li>\n<li>Romains (50)</li>\n<li>1 Corinthiens (24)</li>\n<li>2 Corinthiens (26)</li>\n<li>Galates (17)</li>\n<li>Ephésiens (24)</li>\n<li>Philippiens (10)</li>\n<li>Colossiens (14)</li>\n<li>2 Thessaloniciens (4)</li>\n<li>1 Timothée (6)</li>\n<li>2 Timothée (8)</li>\n<li>Tite (8)</li>\n<li>Philémon (3)</li>\n<li>Hébreux (42)</li>\n<li>Jacques (5)</li>\n<li>1 Pierre (9)</li>\n<li>2 Pierre (4)</li>\n<li>1 Jean (1)</li>\n<li>2 Jean (1)</li>\n<li>3 Jean (1)</li>\n<li>Jude (4)</li>\n<li>Apocalypse (10)</li>\n</ul>\n</td></tr>\n</table>","G2597":"<h1>katabaino</h1>\n<p>Strong n° 2597 <i>Prononciation [kat-ab-ah'-ee-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>descendre, arriver, venir\n<ol type=\"a\">\n<li>le lieu d'où quelqu'un est descendu ou arrivé</li>\n<li>venir de\n<ol>\n<li>de la ville de Jérusalem</li>\n<li>des êtres célestes venant sur la terre</li>\n</ol>\n</li>\n<li>être jeté</li>\n</ol>\n</li>\n<li>de choses\n<ol type=\"a\">\n<li>venir (être envoyé)</li>\n<li>survenir, tomber\n<ol>\n<li>du haut des cieux</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>métaph. être jeté dans un état inférieur, misérable et honteux</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κατα·ϐαίνω :<br>   I <i>intr.</i></b> descendre, OD. <i>12, 77, etc. ;</i> οὐρανόθεν, IL. <i>11, 184, etc</i>. descendre du ciel ; <i>avec le gén</i>. δίφρου, IL. <i>5, 109,</i> d’un char ; <i>avec le gén. précédé d’une prép. :</i> ἐξ ὄρεος, IL. <i>13, 17 ;</i> ἐκ τῆς ἁρμαμάξης, HDT. <i>9, 76,</i> d’une montagne, du chariot ; ἀπὸ τοῦ ἵππου, XÉN. <i>Cyr. 5, 5, 6,</i> de cheval ; ἀπὸ τοῦ βήματος, DÉM. <i>375, 20,</i> de la tribune ; <i>en ce sens, abs</i>. DÉM. <i>348, 9 ; 351, 4, etc. ; avec l’acc. du lieu où l’on descend :</i> θάλαμον, OD. <i>2, 337,</i> dans la chambre ; <i>cf</i>. OD. <i>23, 252 ; avec l’acc. du lieu d’où l’on descend,</i> OD. <i>18, 206 ; avec l’acc. précédé d’une prép. :</i> ἐς πεδίον, IL. <i>3, 252, etc. ;</i> ἐς θάλαμον, IL. <i>6, 288,</i> dans la plaine, dans la chambre ; <i>ou l’acc. de l’instrument au moyen duquel on descend :</i> κλίμακα, OD. <i>1, 330,</i> descendre une échelle ; <i>d’où au pass. :</i> ἵππος καταϐαίνεται, XÉN. <i>Eq. 11, 7,</i> on descend de cheval ; <i>avec un suj. de chose (vent,</i> IL. <i>14, 19 ; larmes,</i> EUR. <i>Andr. 111 ; courant d’un fleuve,</i> PLAT. <i>Criti. 118, etc.) particul. :</i><br><b>      1</b> descendre de l’intérieur des terres vers la mer, <i>abs</i>. ESCHN. <i>77, 8 ; avec un rég. :</i> εἰς τὸν Πειραιᾶ, PLAT. <i>Rsp. 328</i> c, au Pirée ; <i>particul</i>. de l’intérieur de l’Asie (<i>p. opp. à</i> ἀναϐαίνω) HDT. <i>1, 94 ;</i><br><b>      2</b> descendre dans l’arène, <i>au pr. et au fig. (cf. lat</i>. in certamen descendere) ATT. ;<br><b>      3</b> descendre de la tribune (<i>avec</i> ἀπὸ τοῦ βήματος, <i>v. ci-dessus</i>) ATT. ; <i>fig</i>. ἀπὸ τοῦ λόγου, ἀπὸ τῶν ἰαμϐείων, LUC. <i>Tox. 35, Nec. 2,</i> cesser le discours, les ïambes ;<br><b>      4</b> descendre à terre, aborder, PD. <i>N. 4, 63 ; fig</i>. arriver au terme, atteindre le but, PD. <i>N. 3, 73 ;</i><br><b>      5</b> <i>abs</i>. faire son chemin, avancer, PD. <i>N. 3, 73 ; 4, 63 ;</i><br><b>      6</b> en venir à, aboutir à, <i>particul. dans un discours :</i> ἐς λιτάς, HDT. <i>1, 116,</i> en venir à des prières ; <i>avec un part. :</i> κατέϐαινε λέγων, HDT. <i>1, 118,</i> il dit en finissant ; <i>avec idée de temps :</i> εἰς τοὺς χρόνους τούτους, ARSTT. <i>Pol. 7, 16, 5,</i> tomber en ce temps-là ;<br><b>   II</b> <i>tr. aux temps suiv. : (prés., f</i>. καταϐήσω, <i>ao</i>. κατέϐησα) faire descendre, amener en bas, <i>d’où</i> anéantir, PD. <i>P. 8, 78, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao.2, 3 pl. épq</i>. κατέϐαν, IL. <i>24, 329 ; impér. 2 sg. épq</i>. κατάϐηθι, OD. <i>23, 20 ;</i> AR. <i>Lys. 873 ; att</i>. κατάϐα <span>[ϐᾱ]</span> AR. <i>Vesp. 979, Ran. 35 ; sbj. 1 pl. épq</i>. καταϐείομεν, <i>p</i>. καταϐῶμεν, IL. <i>10, 97 ; inf. épq</i>. καταϐήμεναι, OD. <i>14, 19 ; part. dor</i>. καϐϐάς, PD. <i>N. 6, 87 — Moy. ao.1 épq. 3 sg</i>. κατεϐήσετο, IL. <i>6, 288 ; 13, 17 ;</i> OD. <i>2, 337 ; impér</i>. καταϐήσεο, IL. <i>5, 109</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καταβαινω - καταβαίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n83 fois dans 80 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (10)</li>\n<li>Marc (7)</li>\n<li>Luc (12)</li>\n<li>Jean (18)</li>\n<li>Actes (19)</li>\n<li>Romains (1)</li>\n<li>Ephésiens (3)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (11)</li>\n</ul>\n</td></tr>\n</table>","G2598":"<h1>kataballo</h1>\n<p>Strong n° 2598 <i>Prononciation [kat-ab-al'-lo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>abattre\n<ol type=\"a\">\n<li>jeter au sol, prosterner</li>\n</ol>\n</li>\n<li>précipiter vers un lieu plus bas\n<ol type=\"a\">\n<li>poser une fondation</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κατα·ϐάλλω</b> <span>(<i>f</i>. ϐαλῶ, <i>ao.2</i> κατέϐαλον)</span> <i>propr</i>. jeter de haut en bas, <i>d’où :</i><br><b>      1</b> abattre, renverser, jeter à bas, <i>abs</i>. PLAT. <i>Hipp. mi. 374</i> a ; PLUT. <i>Per. 8, etc. ; avec un acc. :</i> οἰκήματα, HDT. <i>1, 17,</i> détruire des habitations ; τῶν θεῶν τὰ ἀγάλματα, HDT. <i>8, 109,</i> renverser les statues des dieux ; τὰ δένδρα, ARSTT. <i>H.A. 9, 9,</i> abattre les arbres ; <i>avec un rég. de pers. :</i> τινὰ ἀπὸ τοῦ ἵππου, XÉN. <i>Hell. 5, 2, 41,</i> renverser qqn de cheval ; ἐπ' ἀκτῆς, IL. <i>23, 125 ;</i> ἐπὶ χθονί, HÉS. <i>Sc. 462 ;</i> ἐνὶ πόντῳ, HÉS. <i>Th. 189,</i> jeter sur le rivage, à terre, dans la mer ; <i>fig</i>. ἀπ' ἐλπίδος PLAT. <i>Euthyd. 15</i> e, précipiter d’une espérance ;<br><b>      2</b> baisser, abaisser : οὔατα, OD. <i>17, 302,</i> baisser les oreilles ; ὀφρῦς, EUR. <i>Cycl. 167,</i> les sourcils ; τὰ κέρατα, ARSTT. <i>H.A. 8, 2,</i> les cornes ; ἀπὸ ἕο κάϐϐαλεν υἱόν, IL. <i>5, 343,</i> elle laissa retomber son fils ; ἴουλον ἀπὸ κροτάφων, THCR. <i>Idyl. 15, 85,</i> laisser pendre de ses tempes des boucles frisées ; ἱστία, THGN. <i>671,</i> baisser les voiles ; <i>fig</i>. κ. ἑαυτόν, PLUT. <i>Cæs. 38,</i> s’abandonner, se dégrader (<i>lat</i>. se abjicere) ; οἱ καταϐεϐλημένοι, ISOCR. <i>254,</i> les gens de rien ;<br><b>      3</b> enfoncer, jeter dans ; <i>fig</i>. τινὰ εἰς φόϐον, PLAT. <i>Ep. 333</i> c ; εἰς ἀπορίαν, PLAT. <i>Phil. 15</i> e ; εἰς ἀπιστίαν, PLAT. <i>Phæd. 88</i> c, jeter qqn dans la crainte, dans l’incertitude, dans la défiance ; <i>particul</i>. jeter dans la foule, répandre : φάτιν, HDT. <i>1, 122,</i> un bruit ;<br><b>      4</b> déposer : κρεῖον ἐν πυρὸς αὐγῇ, IL. <i>9, 206,</i> dresser une table à découper à la lueur du foyer ; <i>cf</i>. AR. <i>Ach. 165, Vesp. 727 ; fig</i>. γεγραμμένα, PLAT. <i>Soph. 232</i> d, déposer des documents écrits ; <i>particul</i>. déposer une somme d’argent, payer, <i>acc</i>. HDT. <i>2, 159 ;</i> PLUT. <i>Them. 24, etc. ;</i> LUC. <i>Cat. 18, etc. ;</i> ζημίας, DÉM. <i>727, 4,</i> acquitter des amendes ; κ. τιμήν τινι ὑπέρ τινος, PLAT. <i>Leg. 932</i> d, payer une amende à qqn pour qqe ch. ; <i>d’où</i> rapporter, produire : ἡ λίμνη καταϐάλλει ἐς τὸ βασιλήϊον ἐπ' ἡμέρην ἑκάστην τάλαντον ἐκ τῶν ἰχθύων, HDT. <i>2, 149,</i> le lac rapporte chaque jour au palais un revenu d’un talent de la vente des poissons ;<br><b>      5</b> rejeter, mettre de côté, XÉN. <i>Cyr. 2, 2, 4 ; fig. en parl. d’un projet de résolution, d’une loi, etc</i>. DÉM. <i>260 ; joint à</i> ἀμελεῖν, PLUT. <i>Cæs. 38 ; abs</i>. laisser tomber de sa mémoire, oublier, EL. (SUID. <i>v°</i> Μάρκος Ἀπίκιος) ;<br><b><i>Moy.</i></b> :<br><b>   I <i>intr.</i></b> se jeter, se lancer : <i>fig</i>. εἰς φθόνον, PLAT. <i>Ep. 344</i> c, se laisser aller à la jalousie ;<br><b>   II <i>tr</i>.<br>      1</b> déposer pour soi : εἰς τὰ δημόσια γράμματα, DÉM. <i>243, 25,</i> déposer dans les registres publics ;<br><b>      2</b> <i>particul</i>. déposer une semence, un germe, PLUT. <i>M. 905 ;</i><br><b>      3</b> poser les fondements de, fonder, établir, <i>acc</i>. SOSIPATER (ATH. <i>378</i> d) ; <i>fig</i>. EUR. <i>H.f. 1261 ;</i> DS. <i>12, 20 ;</i> DH. <i>1, 1 ;</i> ἀρχήν, PLAT. <i>Leg. 803</i> a, un pouvoir ; φιλοσοφίαν, STR. <i>837 ;</i> αἵρεσιν, PLUT. <i>M. 329</i> a, une doctrine, une école de philosophie ;<br><b>      4</b> faire déposer, <i>acc</i>. DÉM. <i>731, 7</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao.2 poét. avec sync. 3 sg</i>. κάϐϐαλε, OD. <i>6, 172 ;</i> HÉS. <i>Sc. 462, Th. 189 ;</i> κάϐϐαλεν, IL. <i>5, 343, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καταβαλλω - καταβάλλω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2599":"<h1>katabareo</h1>\n<p>Strong n° 2599 <i>Prononciation [kat-ab-ar-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>charger d'un poids imposant</li>\n<li>peser lourdement</li>\n<li>métaph. être un fardeau</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>καταϐαρέω-ῶ</b> <span>[ϐᾰ]</span> surcharger, accabler sous le poids, LUC. <i>D. deor. 21, 1 ; fig</i>. POL. <i>18, 4, 4 ;</i> DS. <i>19, 24 ;</i> APP. <i>Civ. 5, 67</i>.<br><span><b>Étym</b>. καταϐαρής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">καταβαρεω - καταβαρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>"};
